/* ══════════════════════════════════════════════════════════════════════════
   EPIC DEVICES design system
   Icy light canvas · electric blue→cyan gradient · violet for offers ·
   deep navy for promotional bands. Glass surfaces float over an aurora
   wash; product media sits on a lit podium.
   Saira (display) / Plus Jakarta Sans (body) / JetBrains Mono (data)
   ══════════════════════════════════════════════════════════════════════════ */
const CSS_A = `


.tx{
  --bg:#EEF3FC; --bg2:#F7FAFF; --surface:#FFFFFF; --surface2:#F5F8FE; --surface3:#EAF1FC;
  --ink:#0A1020; --ink2:#54637E; --ink3:#93A2BC; --ink4:#B9C6DC;
  --line:rgba(10,16,32,.07); --line2:rgba(10,16,32,.12); --line3:rgba(10,16,32,.20);
  --blue:#2563EB; --blue-l:#3B82F6; --blue-d:#1D4ED8; --cyan:#22D3EE; --sky:#60A5FA;
  --blue-soft:#E4EDFF; --blue-soft2:#CFE0FF; --blue-tint:rgba(37,99,235,.07);
  --violet:#7C3AED; --violet-l:#A855F7; --violet-soft:#F0E7FE;
  --navy:#101A3A; --navy2:#1B1147;
  --ok:#0E9F6E; --ok-soft:#E1F7EF; --warn:#C2760A; --warn-soft:#FDF2DE; --bad:#DC2F3E; --bad-soft:#FDEAEC;
  --grad:linear-gradient(135deg,#1D4ED8 0%,#2563EB 42%,#22D3EE 100%);
  --grad-soft:linear-gradient(135deg,#EAF1FF 0%,#F3F8FF 50%,#E9F7FD 100%);
  --f-display:'Saira',system-ui,sans-serif; --f-body:'Plus Jakarta Sans',system-ui,sans-serif; --f-mono:'JetBrains Mono',monospace;
  --r-xs:8px; --r-sm:12px; --r:16px; --r-lg:22px; --r-xl:28px;
  --sh-1:0 1px 2px rgba(16,32,64,.05), 0 2px 8px rgba(37,99,235,.05);
  --sh-2:0 4px 14px rgba(16,32,64,.07), 0 12px 32px rgba(37,99,235,.07);
  --sh-3:0 12px 30px rgba(16,32,64,.12), 0 34px 70px rgba(37,99,235,.13);
  --sh-blue:0 6px 18px rgba(37,99,235,.30);
  --wash:
    radial-gradient(760px 500px at 78% -6%, rgba(34,211,238,.20), transparent 62%),
    radial-gradient(680px 460px at 8% 4%, rgba(37,99,235,.16), transparent 60%),
    radial-gradient(900px 620px at 50% 108%, rgba(124,58,237,.10), transparent 64%);
  font-family:var(--f-body); color:var(--ink); line-height:1.55; min-height:100vh; position:relative;
  -webkit-font-smoothing:antialiased; background:var(--bg); overflow-x:hidden;
}
.tx::before{content:""; position:fixed; inset:0; pointer-events:none; z-index:0; background:var(--wash);}
.tx *{box-sizing:border-box; margin:0; padding:0;}
.tx > *{position:relative; z-index:1;}
.tx h1,.tx h2,.tx h3,.tx h4{font-family:var(--f-display); font-weight:700; letter-spacing:-.02em; color:var(--ink); line-height:1.14;}
.tx button{font-family:inherit; cursor:pointer; color:inherit;}
.tx input,.tx select,.tx textarea{font-family:inherit; color:inherit;}
.tx a{cursor:pointer; text-decoration:none; color:inherit;}
.tx :focus-visible{outline:2px solid var(--blue); outline-offset:2px; border-radius:6px;}
.mono{font-family:var(--f-mono); font-variant-numeric:tabular-nums;}
.muted{color:var(--ink2);}
.gtext{background:var(--grad); -webkit-background-clip:text; background-clip:text; color:transparent;}
.wrap{max-width:1340px; margin:0 auto; padding:0 24px;}
.section{padding:52px 0;}
.section.tight{padding:34px 0;}

.eyebrow{display:inline-flex; align-items:center; gap:7px; font-family:var(--f-mono); font-size:10.5px; font-weight:600; letter-spacing:.18em; text-transform:uppercase; color:var(--blue);}
.sec-head{display:flex; align-items:center; justify-content:space-between; gap:20px; margin-bottom:22px; flex-wrap:wrap;}
.sec-title{display:flex; align-items:center; gap:12px;}
.sec-title .dashes{display:flex; flex-direction:column; gap:4px; flex-shrink:0;}
.sec-title .dashes i{display:block; width:20px; height:3px; border-radius:2px; background:var(--grad);}
.sec-title .dashes i:last-child{width:12px; opacity:.5;}
.sec-title h2{font-size:clamp(21px,2.5vw,28px); font-weight:700; letter-spacing:-.025em;}
.sec-head .link{display:inline-flex; align-items:center; gap:6px; color:var(--blue); font-weight:600; font-size:13.5px; background:none; border:none; transition:.16s;}
.sec-head .link:hover{gap:10px;}

/* ── buttons ────────────────────────────────────────────────── */
.btn{display:inline-flex; align-items:center; justify-content:center; gap:8px; border:1px solid var(--line2); background:var(--surface); color:var(--ink); border-radius:999px; padding:10px 18px; font-size:13.5px; font-weight:600; transition:.18s cubic-bezier(.2,.8,.3,1); white-space:nowrap; box-shadow:var(--sh-1); letter-spacing:-.005em;}
.btn:hover{border-color:var(--blue-soft2); transform:translateY(-1px); box-shadow:var(--sh-2);}
.btn:active{transform:translateY(0);}
.btn:disabled{opacity:.45; cursor:not-allowed; transform:none; box-shadow:none;}
.btn svg{flex-shrink:0;}
.btn-pri{background:var(--grad); border-color:transparent; color:#fff; box-shadow:var(--sh-blue);}
.btn-pri:hover{border-color:transparent; box-shadow:0 10px 26px rgba(37,99,235,.42);}
.btn-dark{background:var(--ink); border-color:var(--ink); color:#fff;}
.btn-dark:hover{background:#18213A; border-color:#18213A;}
.btn-ghost{background:transparent; border-color:transparent; color:var(--ink2); box-shadow:none;}
.btn-ghost:hover{background:var(--blue-tint); color:var(--blue); border-color:transparent; box-shadow:none;}
.btn-soft{background:var(--blue-soft); border-color:transparent; color:var(--blue-d); box-shadow:none;}
.btn-soft:hover{background:var(--blue-soft2); box-shadow:none;}
.btn-danger{color:var(--bad); border-color:var(--line2); background:var(--surface);}
.btn-danger:hover{border-color:var(--bad); background:var(--bad-soft);}
.btn-sm{padding:7px 14px; font-size:12.5px;}
.btn-xs{padding:5px 11px; font-size:11.5px; gap:5px;}
.btn-lg{padding:14px 26px; font-size:15px;}
.btn-block{width:100%;}
.btn-cta{padding:7px 24px 7px 7px; font-size:14.5px; gap:11px;}
.btn-cta .knob{width:32px; height:32px; border-radius:50%; background:rgba(255,255,255,.22); display:grid; place-items:center; flex-shrink:0;}
.btn-cta.light .knob{background:var(--blue-soft); color:var(--blue);}
.iconbtn{width:34px; height:34px; border-radius:10px; border:1px solid var(--line); background:var(--surface); display:grid; place-items:center; color:var(--ink2); transition:.16s; flex-shrink:0;}
.iconbtn:hover{color:var(--blue); border-color:var(--blue-soft2); background:var(--blue-soft);}
.iconbtn.danger:hover{color:var(--bad); border-color:var(--bad); background:var(--bad-soft);}

.tgl{width:38px; height:21px; border-radius:999px; background:var(--line3); border:none; position:relative; transition:.2s; flex-shrink:0; cursor:pointer;}
.tgl::after{content:""; position:absolute; top:2.5px; left:2.5px; width:16px; height:16px; border-radius:50%; background:#fff; transition:.2s; box-shadow:0 1px 3px rgba(10,16,32,.3);}
.tgl.on{background:var(--grad);}
.tgl.on::after{transform:translateX(17px);}
.tgl.violet.on{background:linear-gradient(135deg,#7C3AED,#A855F7);}
.tgl.danger.on{background:var(--bad);}

.pill{display:inline-flex; align-items:center; gap:5px; font-size:10.5px; font-weight:700; letter-spacing:.04em; padding:4px 10px; border-radius:999px; white-space:nowrap;}
.pill.ok{background:var(--ok-soft); color:var(--ok);}
.pill.low{background:var(--warn-soft); color:var(--warn);}
.pill.out{background:var(--bad-soft); color:var(--bad);}
.pill.blue{background:var(--grad); color:#fff;}
.pill.violet{background:linear-gradient(135deg,#7C3AED,#A855F7); color:#fff;}
.pill.ink{background:var(--ink); color:#fff;}
.pill.line{background:var(--surface); color:var(--ink2); box-shadow:inset 0 0 0 1px var(--line2);}
.pill.soft{background:var(--blue-soft); color:var(--blue-d);}

/* ── announcement + nav ─────────────────────────────────────── */
.annc{background:var(--ink); color:#D7E2F5; font-size:12.5px; position:relative; z-index:70;}
.annc-in{max-width:1340px; margin:0 auto; padding:0 24px; height:36px; display:flex; align-items:center; justify-content:space-between; gap:16px;}
.annc-l{display:flex; align-items:center; gap:10px; overflow:hidden; font-weight:500;}
.annc-l .bolt{width:20px; height:20px; border-radius:6px; background:var(--grad); display:grid; place-items:center; flex-shrink:0;}
.annc-msg{animation:tickIn .5s ease; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.annc-r{display:flex; align-items:center; gap:20px; flex-shrink:0;}
.annc-r button{background:none; border:none; color:#9FB0CC; font-size:12.5px; display:flex; align-items:center; gap:6px; transition:.16s; font-weight:500;}
.annc-r button:hover{color:var(--cyan);}

.topwrap{position:sticky; top:0; z-index:60; padding:12px 0; background:linear-gradient(180deg,rgba(238,243,252,.96) 58%,rgba(238,243,252,0));}
.nav{max-width:1340px; margin:0 auto; background:rgba(255,255,255,.84); backdrop-filter:blur(22px) saturate(1.5); border:1px solid rgba(255,255,255,.85); border-radius:var(--r-lg); box-shadow:var(--sh-2); padding:0 16px; height:66px; display:flex; align-items:center; gap:14px;}
.logo{display:flex; align-items:center; gap:11px; cursor:pointer; flex-shrink:0;}
.logo-mk{width:38px; height:38px; border-radius:11px; background:var(--grad); display:grid; place-items:center; box-shadow:var(--sh-blue); position:relative; overflow:hidden; flex-shrink:0;}
.logo-mk::after{content:""; position:absolute; inset:0; background:linear-gradient(160deg,rgba(255,255,255,.45),transparent 55%);}
.logo-mk svg{position:relative; z-index:1;}
.logo-tx{font-family:var(--f-display); font-weight:800; font-size:21px; letter-spacing:.03em; text-transform:uppercase; line-height:1;}
.logo-tx i{font-style:normal; font-family:var(--f-mono); font-size:8px; letter-spacing:.26em; color:var(--ink3); display:block; margin-top:2px; font-weight:500;}
.nav-links{display:flex; align-items:center; gap:1px; margin:0 auto;}
.nav-links > div{position:relative;}
.nlink{padding:9px 13px; border-radius:10px; font-size:13.5px; font-weight:600; color:var(--ink2); background:none; border:none; transition:.16s; display:flex; align-items:center; gap:5px; position:relative;}
.nlink:hover{color:var(--ink);}
.nlink.on{color:var(--blue);}
.nlink.on::after{content:""; position:absolute; left:13px; right:13px; bottom:1px; height:2.5px; border-radius:2px; background:var(--grad);}
.dropdown{position:absolute; top:calc(100% + 14px); left:50%; transform:translateX(-50%); min-width:252px; background:rgba(255,255,255,.97); backdrop-filter:blur(20px); border:1px solid var(--line); border-radius:var(--r); box-shadow:var(--sh-3); padding:8px; z-index:70; animation:pop .17s cubic-bezier(.2,.85,.3,1);}
.dropdown.wide{min-width:440px; display:grid; grid-template-columns:1fr 1fr; gap:2px;}
.dd-h{font-family:var(--f-mono); font-size:9.5px; letter-spacing:.16em; text-transform:uppercase; color:var(--ink3); padding:8px 12px 4px; font-weight:600; grid-column:1/-1;}
.dd-item{display:flex; align-items:center; gap:10px; width:100%; padding:9px 11px; border-radius:11px; background:none; border:none; text-align:left; font-size:13.5px; font-weight:500; color:var(--ink2); transition:.14s;}
.dd-item:hover{background:var(--blue-soft); color:var(--blue-d);}
.dd-item .ic{width:28px; height:28px; border-radius:8px; background:var(--surface2); display:grid; place-items:center; color:var(--blue); flex-shrink:0; transition:.14s;}
.dd-item:hover .ic{background:var(--grad); color:#fff;}
.dd-item .ct{margin-left:auto; font-family:var(--f-mono); font-size:10.5px; color:var(--ink3);}
.nav-search{position:relative; width:280px; flex-shrink:1; min-width:150px;}
.nav-search .box{display:flex; align-items:center; gap:9px; border:1px solid var(--line2); border-radius:999px; padding:5px 5px 5px 15px; background:var(--surface2); transition:.18s;}
.nav-search .box:focus-within{background:#fff; border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.nav-search input{border:none; background:transparent; width:100%; font-size:13.5px; outline:none; min-width:0;}
.nav-search input::placeholder{color:var(--ink3);}
.nav-search .go{width:30px; height:30px; border-radius:50%; background:var(--grad); color:#fff; display:grid; place-items:center; border:none; flex-shrink:0; transition:.16s;}
.nav-search .go:hover{transform:scale(1.07);}
.suggest{position:absolute; top:calc(100% + 10px); left:0; right:0; background:rgba(255,255,255,.97); backdrop-filter:blur(20px); border:1px solid var(--line); border-radius:var(--r); box-shadow:var(--sh-3); overflow:hidden; z-index:70; animation:pop .16s ease; padding:6px;}
.suggest .sg{display:flex; align-items:center; gap:11px; padding:9px 11px; border-radius:11px; transition:.13s; width:100%; background:none; border:none; text-align:left;}
.suggest .sg:hover{background:var(--blue-soft);}
.suggest .sg .ic{width:36px; height:36px; border-radius:10px; background:var(--surface2); display:grid; place-items:center; color:var(--blue); flex-shrink:0;}
.suggest .sg .nm{font-size:13.5px; font-weight:600; line-height:1.25;}
.suggest .sg .mt{font-size:11.5px; color:var(--ink3);}
.suggest .sg .pr{margin-left:auto; font-family:var(--f-mono); font-size:13px; font-weight:700; color:var(--blue-d);}
.suggest .none{padding:18px; text-align:center; font-size:13px; color:var(--ink2);}
.nav-ic{display:flex; align-items:center; gap:7px; flex-shrink:0;}
.nib{width:40px; height:40px; border-radius:12px; border:1px solid var(--line2); background:var(--surface); display:grid; place-items:center; position:relative; transition:.16s; color:var(--ink2);}
.nib:hover{color:var(--blue); border-color:var(--blue-soft2); background:var(--blue-soft);}
.nib.cart{background:var(--grad); border-color:transparent; color:#fff; box-shadow:var(--sh-blue);}
.nib.cart:hover{color:#fff; transform:translateY(-1px);}
.badge{position:absolute; top:-5px; right:-5px; min-width:19px; height:19px; padding:0 5px; border-radius:10px; background:var(--blue); color:#fff; font-size:10.5px; font-weight:700; display:grid; place-items:center; font-family:var(--f-mono); border:2px solid #fff;}
.nib.cart .badge{background:var(--ink);}
.badge.violet{background:var(--violet);}
.menu-btn{display:none;}
`;

const CSS_B = `
/* ── hero ───────────────────────────────────────────────────── */
.hero{position:relative; border-radius:var(--r-xl); overflow:hidden; background:var(--grad-soft); border:1px solid rgba(255,255,255,.9); box-shadow:var(--sh-2); margin-top:6px;}
.hero::before{content:""; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(620px 420px at 76% 44%, rgba(34,211,238,.28), transparent 66%),
             radial-gradient(520px 340px at 96% 10%, rgba(124,58,237,.16), transparent 62%);}
.hero-in{position:relative; z-index:2; display:grid; grid-template-columns:1.02fr .98fr; gap:26px; align-items:center; padding:46px 44px 0;}
.hero-tag{display:inline-flex; align-items:center; gap:9px; padding:7px 16px 7px 12px; border-radius:999px; background:rgba(255,255,255,.86); border:1px solid rgba(255,255,255,.9); box-shadow:var(--sh-1); margin-bottom:22px; font-size:11px; font-weight:700; letter-spacing:.16em; text-transform:uppercase; font-family:var(--f-mono);}
.hero-tag .dot{width:8px; height:8px; border-radius:50%; background:var(--grad); box-shadow:0 0 0 4px rgba(37,99,235,.14); animation:pulse 2.4s ease-in-out infinite;}
.hero h1{font-family:var(--f-display); font-size:clamp(34px,4.6vw,60px); font-weight:800; line-height:1.02; letter-spacing:-.02em; text-transform:uppercase;}
.hero h1 .gtext{display:block;}
.hero .lead{color:var(--ink2); font-size:15.5px; margin:20px 0 26px; max-width:430px; line-height:1.65;}
.hero-cta{display:flex; gap:11px; flex-wrap:wrap;}
.hero-dots{position:absolute; right:18px; top:50%; transform:translateY(-50%); display:flex; flex-direction:column; gap:9px; z-index:4;}
.hero-dots button{width:9px; height:9px; border-radius:50%; border:none; background:var(--line3); transition:.22s; padding:0;}
.hero-dots button.on{background:var(--grad); height:24px; border-radius:6px; box-shadow:var(--sh-blue);}

/* the lit podium, a CSS stand-in for a product render */
.podium{position:relative; height:330px; display:grid; place-items:center;}
.podium .ring{position:absolute; border-radius:50%; border:1px solid rgba(37,99,235,.16);}
.podium .r1{width:300px; height:300px;}
.podium .r2{width:390px; height:390px; border-color:rgba(34,211,238,.18);}
.podium .r3{width:480px; height:480px; border-color:rgba(37,99,235,.08);}
.podium .halo{position:absolute; width:330px; height:330px; border-radius:50%;
  background:radial-gradient(circle, rgba(96,165,250,.34) 0%, rgba(34,211,238,.16) 42%, transparent 68%); filter:blur(6px);}
.podium .disc{position:absolute; bottom:24px; width:290px; height:70px; border-radius:50%;
  background:radial-gradient(ellipse at center, rgba(37,99,235,.34) 0%, rgba(34,211,238,.20) 42%, transparent 72%);
  box-shadow:0 0 60px 18px rgba(37,99,235,.18);}
.podium .disc::after{content:""; position:absolute; inset:14px 40px; border-radius:50%; border:1px solid rgba(255,255,255,.55);}
.pod-stack{position:relative; z-index:3; display:flex; align-items:flex-end; gap:14px;}
.pod-item{border-radius:20px; background:rgba(255,255,255,.72); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); box-shadow:0 16px 40px rgba(23,58,120,.20); display:grid; place-items:center; color:var(--blue-d); animation:bob 5.5s ease-in-out infinite;}
.pod-item.a{width:112px; height:112px; animation-delay:0s;}
.pod-item.b{width:146px; height:146px; margin-bottom:26px; animation-delay:.5s; color:var(--blue);}
.pod-item.c{width:112px; height:112px; animation-delay:1s;}
.pod-item::after{content:""; position:absolute; inset:0; border-radius:20px; background:linear-gradient(150deg,rgba(255,255,255,.7),transparent 52%); pointer-events:none;}

/* trust strip inside the hero card */
.trust{margin:34px 22px 22px; background:rgba(255,255,255,.9); backdrop-filter:blur(14px); border:1px solid rgba(255,255,255,.95); border-radius:var(--r-lg); box-shadow:var(--sh-1); display:grid; grid-template-columns:repeat(4,1fr); position:relative; z-index:3;}
.trust-cell{display:flex; align-items:center; gap:12px; padding:16px 20px; border-right:1px solid var(--line);}
.trust-cell:last-child{border-right:none;}
.trust-cell .ic{width:36px; height:36px; border-radius:11px; background:var(--blue-soft); color:var(--blue); display:grid; place-items:center; flex-shrink:0;}
.trust-cell .t{font-size:13px; font-weight:700; letter-spacing:-.01em;}
.trust-cell .s{font-size:11.5px; color:var(--ink2); margin-top:1px;}

/* ── category cards (horizontal, per the reference) ─────────── */
.catrow{display:grid; grid-template-columns:repeat(4,1fr); gap:14px;}
.catcard{position:relative; display:flex; align-items:center; gap:12px; background:rgba(255,255,255,.9); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r-lg); box-shadow:var(--sh-1); padding:16px 16px 16px 20px; text-align:left; transition:.22s cubic-bezier(.2,.8,.3,1); overflow:hidden;}
.catcard::before{content:""; position:absolute; inset:0; background:var(--grad); opacity:0; transition:.22s;}
.catcard:hover{transform:translateY(-4px); box-shadow:var(--sh-2); border-color:var(--blue-soft2);}
.catcard > *{position:relative; z-index:1;}
.catcard .cc-t{font-family:var(--f-display); font-weight:700; font-size:16px; letter-spacing:-.02em;}
.catcard .cc-d{font-size:11.5px; color:var(--ink2); line-height:1.45; margin-top:3px;}
.catcard .cc-art{width:74px; height:60px; border-radius:14px; background:var(--grad-soft); display:grid; place-items:center; color:var(--blue); flex-shrink:0; margin-left:auto; position:relative; overflow:hidden; transition:.22s;}
.catcard .cc-art::after{content:""; position:absolute; bottom:-14px; left:50%; transform:translateX(-50%); width:56px; height:20px; border-radius:50%; background:radial-gradient(ellipse,rgba(37,99,235,.35),transparent 70%);}
.catcard:hover .cc-art{background:var(--grad); color:#fff;}
.catcard .cc-go{width:32px; height:32px; border-radius:50%; background:var(--surface); border:1px solid var(--line2); display:grid; place-items:center; color:var(--ink2); flex-shrink:0; transition:.22s;}
.catcard:hover .cc-go{background:var(--grad); color:#fff; border-color:transparent; box-shadow:var(--sh-blue);}

/* ── product card ───────────────────────────────────────────── */
.grid{display:grid; grid-template-columns:repeat(4,1fr); gap:16px;}
.grid.five{grid-template-columns:repeat(5,1fr);}
.grid.list{grid-template-columns:1fr; gap:11px;}
.card{position:relative; background:rgba(255,255,255,.92); backdrop-filter:blur(10px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r-lg); box-shadow:var(--sh-1); overflow:hidden; display:flex; flex-direction:column; transition:.24s cubic-bezier(.2,.8,.3,1); animation:fadeUp .45s both;}
.card:hover{transform:translateY(-5px); box-shadow:var(--sh-2); border-color:var(--blue-soft2);}
.card-media{position:relative; height:210px; display:grid; place-items:center; background:var(--grad-soft); overflow:hidden; cursor:pointer;}
.card-media .glow{position:absolute; width:150px; height:150px; border-radius:50%; background:radial-gradient(circle,rgba(96,165,250,.30),transparent 66%); transition:.3s;}
.card:hover .card-media .glow{transform:scale(1.16);}
.card-media .pad{position:absolute; bottom:20px; width:112px; height:26px; border-radius:50%; background:radial-gradient(ellipse,rgba(37,99,235,.28),transparent 72%); transition:.3s;}
.card-media .icn{position:relative; z-index:2; color:var(--blue-d); transition:.3s cubic-bezier(.2,.8,.3,1); filter:drop-shadow(0 8px 14px rgba(29,78,216,.22));}
.card-media .shot{position:relative; z-index:2; width:100%; height:100%; padding:14px; object-fit:contain; transition:.3s cubic-bezier(.2,.8,.3,1); filter:drop-shadow(0 12px 18px rgba(29,78,216,.18));}
.card-media > .shot{position:relative;}   /* legacy single-image path */
.card:hover .card-media .icn{transform:translateY(-6px) scale(1.07);}
.card-tags{position:absolute; top:12px; left:12px; display:flex; flex-direction:column; gap:5px; z-index:3; align-items:flex-start;}
.card-acts{position:absolute; top:12px; right:12px; display:flex; flex-direction:column; gap:5px; z-index:3;}
.mini{width:30px; height:30px; border-radius:50%; border:1px solid var(--line2); background:rgba(255,255,255,.92); backdrop-filter:blur(8px); color:var(--ink2); display:grid; place-items:center; transition:.16s;}
.mini:hover{color:var(--blue); border-color:var(--blue); background:#fff; transform:scale(1.08);}
.mini.on{color:#fff; background:var(--bad); border-color:var(--bad);}
.mini.cmp.on{color:#fff; background:var(--grad); border-color:transparent;}
.soldout-ov{position:absolute; inset:0; background:rgba(240,245,253,.72); backdrop-filter:blur(2px); display:grid; place-items:center; z-index:4;}
.soldout-ov span{font-family:var(--f-mono); font-weight:700; font-size:11px; letter-spacing:.18em; color:var(--bad); border:1.5px solid var(--bad); padding:7px 15px; border-radius:999px; background:rgba(255,255,255,.92);}
.card-body{padding:15px 16px 16px; display:flex; flex-direction:column; flex:1;}
.card-body h3{font-family:var(--f-display); font-size:14.5px; font-weight:700; letter-spacing:-.02em; line-height:1.3; margin-bottom:3px; cursor:pointer;}
.card-body h3:hover{color:var(--blue);}
.card-sub{font-size:11.5px; color:var(--ink2); line-height:1.4; margin-bottom:9px; min-height:16px;}
.card-rate{display:flex; align-items:center; gap:6px; margin-bottom:11px;}
.stars{display:inline-flex; gap:1px;}
.rc{font-size:11px; color:var(--ink3); font-family:var(--f-mono);}
.card-foot{display:flex; align-items:flex-end; justify-content:space-between; gap:10px; margin-top:auto;}
.price{font-family:var(--f-display); font-weight:800; font-size:18px; letter-spacing:-.03em; display:flex; align-items:baseline; gap:7px; flex-wrap:wrap; color:var(--ink);}
.price s{font-size:12.5px; color:var(--ink3); font-weight:500; font-family:var(--f-body);}
.price-off{font-size:11px; color:var(--blue); font-weight:600; margin-top:3px;}
.add-btn{width:38px; height:38px; border-radius:12px; border:1px solid var(--line2); background:var(--surface); color:var(--blue); display:grid; place-items:center; transition:.18s; flex-shrink:0;}
.add-btn:hover:not(:disabled){background:var(--grad); color:#fff; border-color:transparent; box-shadow:var(--sh-blue); transform:translateY(-2px);}
.add-btn:disabled{color:var(--ink4); cursor:not-allowed;}
.stockline{display:flex; align-items:center; gap:8px; margin-bottom:11px;}
.stockline .mv{font-size:10.5px; font-family:var(--f-mono); color:var(--ink3);}
.stockline .mv.low{color:var(--warn);}
.stockline .mv.out{color:var(--bad);}
/* list variant */
.grid.list .card{flex-direction:row;}
.grid.list .card-media{width:170px; height:auto; min-height:140px; flex-shrink:0;}
.grid.list .card-body{flex-direction:row; align-items:center; gap:22px;}
.grid.list .lb-main{flex:1; min-width:0;}
.grid.list .lb-mid{width:170px; flex-shrink:0;}
.grid.list .card-foot{margin-top:0; width:200px; flex-shrink:0; justify-content:flex-end;}
.grid.list .card-sub,.grid.list .card-rate,.grid.list .stockline{margin-bottom:0;}
.grid.list .card-rate{margin-top:5px;}

/* ── the meter (kept for stock + progress readouts) ─────────── */
.meter{display:inline-flex; gap:2px; align-items:center;}
.meter i{width:5px; height:12px; border-radius:2px; background:var(--line2); transition:background .3s;}
.meter i.on{background:var(--grad);}
.meter.low i.on{background:linear-gradient(135deg,#D97706,#F59E0B);}
.meter.out i.on{background:linear-gradient(135deg,#B91C1C,#EF4444);}
.meter.sm i{width:4px; height:10px;}
.meter-row{display:flex; align-items:center; gap:9px;}
.meter-row .mv{font-family:var(--f-mono); font-size:11.5px; font-weight:600; color:var(--ink2); white-space:nowrap;}

/* ── featured tabs ──────────────────────────────────────────── */
.ftabs{display:flex; gap:3px; background:rgba(255,255,255,.85); backdrop-filter:blur(12px); border:1px solid var(--line); padding:4px; border-radius:999px; width:max-content;}
.ftabs button{border:none; background:transparent; color:var(--ink2); padding:8px 16px; border-radius:999px; font-weight:600; font-size:13px; transition:.18s;}
.ftabs button.on{background:var(--grad); color:#fff; box-shadow:var(--sh-blue);}

/* ── promo / newsletter band ────────────────────────────────── */
.band{position:relative; border-radius:var(--r-xl); overflow:hidden; background:linear-gradient(110deg,#0C1330 0%,#161B4B 44%,#2B1A63 100%); color:#fff; padding:26px 30px; display:flex; align-items:center; gap:26px; flex-wrap:wrap;}
.band::before{content:""; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(560px 260px at 88% 50%, rgba(124,58,237,.42), transparent 66%),
             radial-gradient(420px 220px at 12% 20%, rgba(37,99,235,.36), transparent 66%);}
.band::after{content:""; position:absolute; inset:0; pointer-events:none; opacity:.16;
  background-image:linear-gradient(rgba(255,255,255,.5) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.5) 1px,transparent 1px);
  background-size:46px 46px; mask-image:radial-gradient(500px 240px at 70% 50%,#000,transparent 74%);}
.band > *{position:relative; z-index:2;}
.band .hexi{width:56px; height:56px; border-radius:17px; background:linear-gradient(135deg,#3B82F6,#22D3EE); display:grid; place-items:center; flex-shrink:0; box-shadow:0 10px 26px rgba(59,130,246,.45); position:relative;}
.band .hexi::after{content:""; position:absolute; inset:0; border-radius:17px; background:linear-gradient(160deg,rgba(255,255,255,.4),transparent 55%);}
.band .bh{font-family:var(--f-display); font-weight:800; font-size:22px; line-height:1.08; text-transform:uppercase; letter-spacing:-.01em;}
.band .bh span{display:block; background:linear-gradient(135deg,#93C5FD,#22D3EE); -webkit-background-clip:text; background-clip:text; color:transparent;}
.band .bm{flex:1; min-width:220px;}
.band .bm .t{font-family:var(--f-display); font-size:18px; font-weight:700; margin-bottom:4px;}
.band .bm .s{font-size:13px; color:#A9B7D6; line-height:1.5;}
.band .news{display:flex; gap:8px; align-items:center; flex-shrink:0;}
.band .news input{border:1px solid rgba(255,255,255,.18); background:rgba(255,255,255,.96); color:var(--ink); border-radius:999px; padding:11px 18px; font-size:13.5px; outline:none; width:220px; min-width:0;}
.band .news input::placeholder{color:var(--ink3);}
.band .orb{position:absolute; right:22px; top:50%; transform:translateY(-50%); width:130px; height:130px; border-radius:50%; background:radial-gradient(circle at 34% 32%, rgba(147,197,253,.7), rgba(124,58,237,.42) 46%, transparent 70%); filter:blur(2px); z-index:1;}
.countdown{display:flex; gap:8px; align-items:center; flex-shrink:0;}
.cd-cell{background:rgba(255,255,255,.1); border:1px solid rgba(255,255,255,.16); border-radius:12px; padding:8px 12px; text-align:center; min-width:56px; backdrop-filter:blur(8px);}
.cd-cell .v{font-family:var(--f-mono); font-size:19px; font-weight:700; line-height:1; color:#fff;}
.cd-cell .k{font-size:9px; letter-spacing:.12em; text-transform:uppercase; color:#8FA0C4; margin-top:4px; font-weight:600;}

/* ── shop page ──────────────────────────────────────────────── */
.crumb-bar{display:flex; align-items:center; gap:8px; font-size:13px; color:var(--ink2); margin-bottom:14px; font-weight:500;}
.crumb-bar b{color:var(--blue); font-weight:600;}
.shophero{position:relative; border-radius:var(--r-xl); overflow:hidden; background:var(--grad-soft); border:1px solid rgba(255,255,255,.9); box-shadow:var(--sh-1); padding:34px 36px; display:grid; grid-template-columns:1fr 340px; gap:20px; align-items:center; margin-bottom:16px;}
.shophero::before{content:""; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(480px 280px at 82% 50%, rgba(34,211,238,.26), transparent 66%);}
.shophero > *{position:relative; z-index:2;}
.shophero h1{font-family:var(--f-display); font-size:clamp(26px,3.4vw,42px); font-weight:800; text-transform:uppercase; letter-spacing:-.02em;}
.shophero p{color:var(--ink2); font-size:14.5px; margin-top:8px; max-width:460px;}
.shophero .podium{height:180px;}
.shophero .podium .r1{width:180px; height:180px;} .shophero .podium .r2{width:238px; height:238px;} .shophero .podium .r3{width:296px; height:296px;}
.shophero .podium .halo{width:200px; height:200px;} .shophero .podium .disc{width:180px; height:44px; bottom:12px;}
.shophero .pod-item.a,.shophero .pod-item.c{width:62px; height:62px; border-radius:14px;}
.shophero .pod-item.b{width:82px; height:82px; border-radius:16px; margin-bottom:14px;}

.pilltabs{display:flex; gap:9px; overflow-x:auto; padding:2px 2px 6px; margin-bottom:18px;}
.ptab{display:inline-flex; align-items:center; gap:9px; padding:11px 20px; border-radius:999px; background:rgba(255,255,255,.88); backdrop-filter:blur(10px); border:1px solid rgba(255,255,255,.9); box-shadow:var(--sh-1); font-size:13.5px; font-weight:600; color:var(--ink2); white-space:nowrap; transition:.18s;}
.ptab:hover{color:var(--ink); transform:translateY(-2px);}
.ptab .ic{color:var(--ink3); display:flex; transition:.18s;}
.ptab.on{color:var(--blue-d); border-color:var(--blue-soft2); box-shadow:var(--sh-2); background:#fff;}
.ptab.on .ic{color:var(--blue);}

.shop-grid{display:grid; grid-template-columns:264px 1fr; gap:20px; align-items:start;}
.filters{position:sticky; top:92px; background:rgba(255,255,255,.92); backdrop-filter:blur(14px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r-lg); box-shadow:var(--sh-1); overflow:hidden;}
.filters-h{display:flex; align-items:center; justify-content:space-between; padding:16px 18px 12px;}
.filters-h h3{font-size:15.5px; font-weight:700;}
.filters-h button{display:inline-flex; align-items:center; gap:6px; background:none; border:none; color:var(--blue); font-size:12.5px; font-weight:600; transition:.16s;}
.facet{border-top:1px solid var(--line); padding:13px 18px;}
.facet-h{display:flex; align-items:center; justify-content:space-between; width:100%; background:none; border:none; padding:0; font-size:13px; font-weight:700; color:var(--ink); margin-bottom:2px;}
.facet-h svg{color:var(--ink3); transition:.2s;}
.facet-b{padding-top:10px; animation:fadeUp .2s both;}
.fchk{display:flex; align-items:center; gap:10px; padding:6px 0; font-size:13px; color:var(--ink2); font-weight:500; background:none; border:none; width:100%; text-align:left; transition:.14s;}
.fchk:hover{color:var(--ink);}
.fchk .bx{width:17px; height:17px; border-radius:5px; border:1.5px solid var(--line3); display:grid; place-items:center; flex-shrink:0; transition:.16s; color:transparent; background:#fff;}
.fchk.on .bx{background:var(--grad); border-color:transparent; color:#fff;}
.fchk.on{color:var(--ink); font-weight:600;}
.fchk .ct{margin-left:auto; font-family:var(--f-mono); font-size:10.5px; color:var(--ink3);}
.fchk .rd{width:17px; height:17px; border-radius:50%; border:1.5px solid var(--line3); flex-shrink:0; display:grid; place-items:center; background:#fff; transition:.16s;}
.fchk.on .rd{border-color:var(--blue); border-width:5px;}
.fchk.sub{padding-left:10px; font-size:12.5px;}
.showmore{background:none; border:none; color:var(--blue); font-size:12.5px; font-weight:600; padding:6px 0; display:flex; align-items:center; gap:5px;}

/* dual range slider */
.range{padding:6px 0 2px;}
.range-vals{display:flex; align-items:center; justify-content:space-between; font-family:var(--f-mono); font-size:12px; font-weight:600; color:var(--ink); margin-bottom:12px;}
.range-track{position:relative; height:26px;}
.range-track .rail{position:absolute; top:11px; left:0; right:0; height:4px; border-radius:3px; background:var(--surface3);}
.range-track .fill{position:absolute; top:11px; height:4px; border-radius:3px; background:var(--grad);}
.range-track input[type=range]{position:absolute; top:0; left:0; width:100%; height:26px; -webkit-appearance:none; appearance:none; background:none; pointer-events:none; margin:0;}
.range-track input[type=range]::-webkit-slider-thumb{-webkit-appearance:none; appearance:none; width:17px; height:17px; border-radius:50%; background:#fff; border:3px solid var(--blue); box-shadow:0 2px 6px rgba(37,99,235,.35); pointer-events:auto; cursor:grab;}
.range-track input[type=range]::-moz-range-thumb{width:17px; height:17px; border-radius:50%; background:#fff; border:3px solid var(--blue); box-shadow:0 2px 6px rgba(37,99,235,.35); pointer-events:auto; cursor:grab;}

/* toolbar */
.shop-top{display:flex; align-items:center; gap:12px; margin-bottom:16px; flex-wrap:wrap; background:rgba(255,255,255,.86); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r); box-shadow:var(--sh-1); padding:11px 15px;}
.shop-top .cnt{font-size:13px; color:var(--ink2); font-weight:500;}
.shop-top .cnt b{color:var(--ink); font-weight:700;}
.viewtog{display:flex; gap:3px; background:var(--surface2); border-radius:11px; padding:3px;}
.viewtog button{width:32px; height:32px; display:grid; place-items:center; border:none; background:transparent; color:var(--ink3); border-radius:9px; transition:.16s;}
.viewtog button.on{background:var(--grad); color:#fff; box-shadow:var(--sh-blue);}
.select{border:1px solid var(--line2); background:var(--surface); border-radius:999px; padding:9px 14px; font-size:13px; outline:none; cursor:pointer; transition:.16s; font-weight:600; color:var(--ink);}
.select:focus{border-color:var(--blue); box-shadow:0 0 0 4px var(--blue-tint);}
.searchbox{display:flex; align-items:center; gap:9px; border:1px solid var(--line2); border-radius:999px; padding:9px 16px; background:var(--surface); transition:.16s;}
.searchbox:focus-within{border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.searchbox input{border:none; background:transparent; width:100%; font-size:13.5px; outline:none; min-width:0;}
.searchbox input::placeholder{color:var(--ink3);}
.chips{display:flex; gap:7px; flex-wrap:wrap; align-items:center;}
.chip{display:inline-flex; align-items:center; gap:6px; border:1px solid var(--blue-soft2); background:var(--blue-soft); color:var(--blue-d); padding:5px 12px; border-radius:999px; font-size:12px; font-weight:600;}
.chip button{background:none; border:none; display:flex; padding:0; color:inherit; opacity:.6;}
.chip button:hover{opacity:1;}
.empty{text-align:center; color:var(--ink2); padding:56px 20px;}
.empty h4{font-size:17px; margin:14px 0 6px;}
.empty p{font-size:13.5px; max-width:340px; margin:0 auto 16px;}

/* pagination */
.pagination{display:flex; align-items:center; justify-content:center; gap:7px; margin-top:22px;}
.pg{min-width:38px; height:38px; padding:0 12px; border-radius:12px; border:1px solid var(--line2); background:var(--surface); display:grid; place-items:center; font-size:13.5px; font-weight:600; color:var(--ink2); transition:.16s; box-shadow:var(--sh-1);}
.pg:hover:not(:disabled):not(.on){border-color:var(--blue-soft2); color:var(--blue); transform:translateY(-1px);}
.pg.on{background:var(--grad); color:#fff; border-color:transparent; box-shadow:var(--sh-blue);}
.pg:disabled{opacity:.4; cursor:not-allowed;}
.pg.dots{border:none; background:none; box-shadow:none; color:var(--ink3); min-width:24px; padding:0;}

/* ── footer ─────────────────────────────────────────────────── */
.footer{margin-top:44px; background:rgba(255,255,255,.72); backdrop-filter:blur(16px); border-top:1px solid rgba(255,255,255,.9); padding:44px 0 22px;}
.foot-grid{display:grid; grid-template-columns:1.6fr repeat(4,.85fr) 1.35fr; gap:26px;}
.footer h4{font-size:12.5px; margin-bottom:14px; font-weight:700; letter-spacing:.02em; font-family:var(--f-body);}
.footer button.fl{display:block; color:var(--ink2); font-size:13px; padding:5px 0; transition:.16s; background:none; border:none; text-align:left; font-weight:500;}
.footer button.fl:hover{color:var(--blue); transform:translateX(3px);}
.socials{display:flex; gap:8px; margin-top:16px;}
.socials button{width:34px; height:34px; border-radius:11px; border:1px solid var(--line2); background:var(--surface); display:grid; place-items:center; color:var(--ink2); transition:.18s;}
.socials button:hover{background:var(--grad); color:#fff; border-color:transparent; transform:translateY(-2px); box-shadow:var(--sh-blue);}
.foot-news{display:flex; gap:8px; margin-top:12px;}
.foot-news input{flex:1; border:1px solid var(--line2); background:var(--surface); border-radius:999px; padding:10px 16px; font-size:13px; outline:none; min-width:0;}
.foot-news input:focus{border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.foot-news .go{width:40px; height:40px; border-radius:50%; background:var(--grad); color:#fff; border:none; display:grid; place-items:center; flex-shrink:0; box-shadow:var(--sh-blue); transition:.16s;}
.foot-news .go:hover{transform:scale(1.06);}
.foot-bot{display:flex; align-items:center; justify-content:space-between; gap:16px; margin-top:34px; padding-top:20px; border-top:1px solid var(--line); flex-wrap:wrap; font-size:12.5px; color:var(--ink3);}
.foot-bot .links{display:flex; gap:18px;}
.foot-bot .links button{background:none; border:none; color:var(--ink3); font-size:12.5px; transition:.16s;}
.foot-bot .links button:hover{color:var(--blue);}
`;

const CSS_C = `
/* ── overlay / drawer / modal ───────────────────────────────── */
.overlay{position:fixed; inset:0; z-index:80; background:rgba(10,16,32,.42); backdrop-filter:blur(4px); animation:fade .2s;}
.drawer{position:fixed; top:0; right:0; bottom:0; width:min(452px,100%); z-index:81; background:var(--bg2); display:flex; flex-direction:column; box-shadow:var(--sh-3); animation:slideIn .32s cubic-bezier(.2,.85,.25,1);}
.drawer.wide{width:min(680px,100%);}
.drawer-head{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:18px 20px; border-bottom:1px solid var(--line); background:rgba(255,255,255,.9); backdrop-filter:blur(12px);}
.drawer-head h3{font-size:17px; display:flex; align-items:center; gap:9px;}
.drawer-body{flex:1; overflow-y:auto; padding:18px 20px;}
.drawer-foot{border-top:1px solid var(--line); padding:16px 20px; background:rgba(255,255,255,.94); backdrop-filter:blur(12px);}
.line{display:flex; gap:12px; padding:14px 0; border-bottom:1px solid var(--line);}
.line-media{width:60px; height:60px; border-radius:15px; display:grid; place-items:center; flex-shrink:0; background:var(--grad-soft); border:1px solid var(--line); color:var(--blue-d);}
.line-info{flex:1; min-width:0;}
.line-info .n{font-weight:700; font-size:13.5px; line-height:1.3; font-family:var(--f-display); letter-spacing:-.015em;}
.line-info .b{font-size:11px; color:var(--blue); font-weight:600; margin-bottom:2px;}
.line-info .p{font-family:var(--f-mono); font-size:11.5px; color:var(--ink2); margin-top:4px;}
.qty{display:flex; align-items:center; border:1px solid var(--line2); border-radius:999px; overflow:hidden; width:max-content; background:var(--surface);}
.qty button{width:28px; height:28px; border:none; background:transparent; color:var(--ink2); display:grid; place-items:center; transition:.14s;}
.qty button:hover{color:var(--blue); background:var(--blue-soft);}
.qty span{min-width:30px; text-align:center; font-family:var(--f-mono); font-size:12.5px; font-weight:700;}
.ship-prog{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px 16px; margin-bottom:16px; box-shadow:var(--sh-1);}
.ship-prog .t{display:flex; align-items:center; justify-content:space-between; font-size:12.5px; margin-bottom:10px; font-weight:600; gap:10px;}
.ship-prog .t b{font-family:var(--f-mono); color:var(--blue);}

.modal-wrap{position:fixed; inset:0; z-index:90; background:rgba(10,16,32,.46); backdrop-filter:blur(4px); display:grid; place-items:center; padding:22px; animation:fade .18s; overflow-y:auto;}
.modal{width:100%; max-width:620px; background:var(--bg2); border-radius:var(--r-lg); box-shadow:var(--sh-3); overflow:hidden; animation:pop .24s cubic-bezier(.2,.85,.25,1); max-height:92vh; display:flex; flex-direction:column;}
.modal.lg{max-width:840px;}
.modal.xl{max-width:1020px;}
.modal-head{display:flex; align-items:center; gap:12px; padding:16px 20px; border-bottom:1px solid var(--line); background:rgba(255,255,255,.94); flex-shrink:0;}
.modal-head .mh-ic{width:36px; height:36px; border-radius:11px; background:var(--grad); color:#fff; display:grid; place-items:center; flex-shrink:0; box-shadow:var(--sh-blue);}
.modal-head .mh-t{font-family:var(--f-display); font-weight:700; font-size:16px; letter-spacing:-.02em;}
.modal-head .mh-s{font-size:11.5px; color:var(--ink3);}
.modal-x{margin-left:auto; width:34px; height:34px; border-radius:10px; border:1px solid var(--line2); background:var(--surface); display:grid; place-items:center; color:var(--ink2); transition:.16s; flex-shrink:0;}
.modal-x:hover{background:var(--bad-soft); color:var(--bad); border-color:var(--bad);}
.modal-body{padding:20px; overflow-y:auto; flex:1;}
.modal-foot{padding:14px 20px; border-top:1px solid var(--line); background:rgba(255,255,255,.94); display:flex; align-items:center; justify-content:space-between; gap:10px; flex-shrink:0; flex-wrap:wrap;}
.mtabs{display:flex; gap:3px; padding:8px 16px; background:rgba(255,255,255,.9); border-bottom:1px solid var(--line); overflow-x:auto; flex-shrink:0;}
.mtabs button{border:none; background:none; padding:9px 14px; font-size:13px; font-weight:600; color:var(--ink2); border-radius:999px; transition:.16s; white-space:nowrap; display:flex; align-items:center; gap:7px;}
.mtabs button:hover{color:var(--ink); background:var(--surface2);}
.mtabs button.on{color:#fff; background:var(--grad); box-shadow:var(--sh-blue);}

/* ── forms ──────────────────────────────────────────────────── */
.field{margin-bottom:14px;}
.field label{display:block; font-size:11.5px; letter-spacing:.01em; color:var(--ink2); margin-bottom:6px; font-weight:700;}
.inp,.finp{width:100%; border:1px solid var(--line2); background:var(--surface); border-radius:var(--r-sm); padding:11px 14px; font-size:13.5px; outline:none; transition:.16s;}
.inp:focus,.finp:focus{border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.inp::placeholder,.finp::placeholder{color:var(--ink3);}
select.finp,select.inp{cursor:pointer;}
.textarea{width:100%; border:1px solid var(--line2); background:var(--surface); border-radius:var(--r-sm); padding:11px 14px; font-size:13.5px; outline:none; resize:vertical; min-height:78px; line-height:1.55; transition:.16s;}
.textarea:focus{border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.form-row{display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:14px;}
.form-row.three{grid-template-columns:1fr 1fr 1fr;}
.hint{font-size:11.5px; color:var(--ink3); margin-top:5px; line-height:1.45;}
.mini-toggle{display:flex; align-items:center; gap:11px; padding:12px 14px; border:1px solid var(--line); border-radius:var(--r-sm); background:var(--surface); cursor:pointer; font-size:13px; font-weight:600; transition:.16s;}
.mini-toggle:hover{border-color:var(--blue-soft2); background:var(--surface2);}
.mini-toggle small{display:block; font-size:11.5px; color:var(--ink3); font-weight:400; margin-top:1px;}
.icon-picker{display:grid; grid-template-columns:repeat(auto-fill,minmax(42px,1fr)); gap:6px; max-height:160px; overflow-y:auto; padding:9px; border:1px solid var(--line); border-radius:var(--r-sm); background:var(--surface);}
.icon-opt{height:40px; border-radius:10px; border:1px solid transparent; background:var(--surface2); display:grid; place-items:center; color:var(--ink2); transition:.14s;}
.icon-opt:hover{background:var(--blue-soft); color:var(--blue);}
.icon-opt.on{background:var(--grad); color:#fff; box-shadow:var(--sh-blue);}
.panel{background:rgba(255,255,255,.92); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r-lg); padding:22px; box-shadow:var(--sh-1);}
.panel h3{font-size:16px; display:flex; align-items:center; gap:9px; margin-bottom:16px;}
.panel h3 svg{color:var(--blue);}

/* ── checkout ───────────────────────────────────────────────── */
.co-grid{display:grid; grid-template-columns:1fr 396px; gap:20px; align-items:start;}
.co-summary{position:sticky; top:92px;}
.method{display:flex; align-items:center; gap:12px; border:1px solid var(--line2); border-radius:var(--r); padding:14px 16px; margin-bottom:9px; cursor:pointer; transition:.18s; background:var(--surface); width:100%; text-align:left;}
.method:hover{border-color:var(--blue-soft2);}
.method.on{border-color:var(--blue); background:var(--blue-soft); box-shadow:0 0 0 3px var(--blue-tint);}
.method .radio{width:19px; height:19px; border-radius:50%; border:2px solid var(--line3); flex-shrink:0; display:grid; place-items:center; transition:.16s; background:#fff;}
.method.on .radio{border-color:var(--blue);}
.method.on .radio::after{content:""; width:9px; height:9px; border-radius:50%; background:var(--grad);}
.method .m-name{font-weight:700; font-size:13.5px; display:flex; align-items:center; gap:8px;}
.method .m-eta{font-size:12px; color:var(--ink2); margin-top:2px;}
.method .m-price{margin-left:auto; font-family:var(--f-mono); font-weight:700; font-size:13.5px;}
.sum-row{display:flex; justify-content:space-between; align-items:center; padding:6px 0; font-size:13.5px; gap:12px;}
.sum-row .k{color:var(--ink2);}
.sum-row .v{font-family:var(--f-mono); font-weight:600;}
.sum-row.total{border-top:1px solid var(--line); margin-top:9px; padding-top:14px; font-size:15px; font-weight:700;}
.sum-row.total .v{font-family:var(--f-display); font-weight:800; font-size:21px; letter-spacing:-.03em;}
.sum-row.disc .v{color:var(--ok);}
.promo-entry{display:flex; gap:8px; margin:4px 0 14px;}
.promo-entry input{flex:1; border:1px solid var(--line2); background:var(--surface); border-radius:999px; padding:10px 16px; font-family:var(--f-mono); font-size:12.5px; letter-spacing:.08em; text-transform:uppercase; outline:none; min-width:0;}
.promo-entry input:focus{border-color:var(--blue-soft2); box-shadow:0 0 0 4px var(--blue-tint);}
.applied-code{display:flex; align-items:center; gap:8px; padding:11px 14px; border-radius:var(--r-sm); background:var(--ok-soft); border:1px dashed rgba(14,159,110,.4); font-size:12.5px; color:var(--ok); margin-bottom:14px; font-weight:700;}
.applied-code .x{margin-left:auto; cursor:pointer; display:flex; background:none; border:none; color:var(--ink2);}
.zone-info{border:1px dashed var(--blue-soft2); border-radius:var(--r-sm); padding:13px 15px; background:var(--blue-soft);}
.zone-info .zn{font-weight:700; font-size:13.5px; display:flex; align-items:center; gap:8px; color:var(--blue-d);}
.zone-info .zr{font-size:12px; color:var(--ink2); margin-top:3px;}
.confirm{max-width:620px; margin:0 auto; padding:44px 0;}
.confirm .ok{width:76px; height:76px; border-radius:24px; margin:0 auto 22px; display:grid; place-items:center; background:var(--grad); color:#fff; box-shadow:0 14px 34px rgba(37,99,235,.4);}
.confirm h2{font-size:32px; margin-bottom:10px; text-align:center;}
.confirm .oid{font-family:var(--f-mono); font-size:14px; color:var(--blue-d); background:var(--blue-soft); padding:8px 18px; border-radius:999px; display:inline-block; margin:4px 0 22px; font-weight:700; letter-spacing:.06em;}

/* ── compare + product detail ───────────────────────────────── */
.cmp-tray{position:fixed; left:0; right:0; bottom:0; z-index:75; background:rgba(10,16,32,.94); backdrop-filter:blur(16px); color:#fff; padding:13px 0; box-shadow:0 -8px 30px rgba(10,16,32,.3); animation:slideUp .28s cubic-bezier(.2,.85,.25,1);}
.cmp-in{max-width:1340px; margin:0 auto; padding:0 24px; display:flex; align-items:center; gap:12px; flex-wrap:wrap;}
.cmp-slot{display:flex; align-items:center; gap:9px; background:rgba(255,255,255,.09); border:1px solid rgba(255,255,255,.15); border-radius:999px; padding:7px 13px; font-size:12.5px; max-width:230px;}
.cmp-slot .ic{color:var(--cyan); flex-shrink:0;}
.cmp-slot .nm{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.cmp-slot button{background:none; border:none; color:#8A9CBC; display:flex; padding:0;}
.cmp-slot button:hover{color:#fff;}
.cmp-table{width:100%; border-collapse:collapse; font-size:13px;}
.cmp-table th,.cmp-table td{padding:12px 14px; text-align:left; border-bottom:1px solid var(--line); vertical-align:top;}
.cmp-table th{font-size:12.5px; color:var(--ink); font-weight:700; background:var(--surface2); white-space:nowrap; font-family:var(--f-display);}
.cmp-table td:first-child{font-size:11.5px; color:var(--ink2); white-space:nowrap; background:var(--surface2); font-weight:600;}
.cmp-table .best{background:var(--blue-soft); font-weight:700;}
.pd-hero{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:30px; margin-bottom:26px; align-items:start;}
.pd-media{background:var(--grad-soft); border:1px solid var(--line); border-radius:var(--r-lg); aspect-ratio:1/1; width:100%; display:grid; place-items:center; position:relative; overflow:hidden;}
.pd-media .glow{position:absolute; width:200px; height:200px; border-radius:50%; background:radial-gradient(circle,rgba(96,165,250,.34),transparent 66%);}
.pd-media .pad{position:absolute; bottom:32px; width:170px; height:36px; border-radius:50%; background:radial-gradient(ellipse,rgba(37,99,235,.3),transparent 72%);}
.pd-media svg{position:relative; z-index:2; color:var(--blue-d); filter:drop-shadow(0 12px 20px rgba(29,78,216,.24));}
/* fill the frame, contain so nothing is cropped, small inset so it breathes */
.pd-media .shot{position:relative; z-index:2; width:100%; height:100%; padding:18px; object-fit:contain; filter:drop-shadow(0 16px 24px rgba(29,78,216,.18));}
.pd-media img{width:100%; height:100%; padding:18px; object-fit:contain;}
.pd-media .pd-vid{padding:0;}
/* over a white product shot these read as stray text unless they sit on something */
.pd-media .tick{position:absolute; font-family:var(--f-mono); font-size:9.5px; color:var(--ink2); letter-spacing:.1em; z-index:3;
  background:rgba(255,255,255,.78); backdrop-filter:blur(4px); border:1px solid var(--line); border-radius:999px; padding:3px 9px;}
.spec-table{width:100%; border-collapse:collapse; font-size:13px;}
.spec-table td{padding:10px 0; border-bottom:1px dashed var(--line);}
.spec-table td:first-child{font-size:12px; color:var(--ink2); width:44%; font-weight:600;}
.spec-table td:last-child{font-weight:600;}
.spec-table tr:last-child td{border-bottom:none;}
.rel-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:10px;}
.rel{border:1px solid var(--line); border-radius:var(--r-sm); padding:12px; background:var(--surface); text-align:left; transition:.18s;}
.rel:hover{border-color:var(--blue-soft2); transform:translateY(-2px); box-shadow:var(--sh-1);}
.rel .ic{width:34px; height:34px; border-radius:10px; background:var(--grad-soft); display:grid; place-items:center; color:var(--blue); margin-bottom:8px;}
.rel .n{font-size:12px; font-weight:700; line-height:1.3; margin-bottom:4px;}
.rel .p{font-family:var(--f-mono); font-size:11.5px; color:var(--ink2);}

/* ── toasts + mobile menu ───────────────────────────────────── */
.toasts{position:fixed; right:20px; bottom:20px; z-index:120; display:flex; flex-direction:column; gap:8px; align-items:flex-end;}
.toast{display:flex; align-items:center; gap:11px; background:rgba(10,16,32,.96); backdrop-filter:blur(12px); color:#fff; border-radius:999px; padding:11px 18px 11px 11px; font-size:13px; font-weight:600; box-shadow:var(--sh-3); animation:toastIn .28s cubic-bezier(.2,.85,.25,1); max-width:340px;}
.toast .ti{width:26px; height:26px; border-radius:50%; background:var(--grad); color:#fff; display:grid; place-items:center; flex-shrink:0;}
.toast.err .ti{background:var(--bad);}
.mmenu{position:fixed; inset:0; z-index:85; background:var(--bg2); padding:20px; animation:fade .18s; overflow-y:auto;}
.mmenu-top{display:flex; align-items:center; justify-content:space-between; margin-bottom:22px;}
.mmenu button.ml{display:flex; align-items:center; justify-content:space-between; width:100%; padding:15px 4px; border-bottom:1px solid var(--line); font-size:16px; font-weight:600; background:none; border-left:none; border-right:none; border-top:none; text-align:left;}

/* ══════════ CONSOLE ══════════ */
.cshell{display:grid; grid-template-columns:236px 1fr; min-height:100vh;}
.rail{background:linear-gradient(170deg,#0C1330 0%,#111A3E 58%,#1B1147 100%); color:#93A6CC; padding:18px 12px; position:sticky; top:0; height:100vh; overflow-y:auto; display:flex; flex-direction:column; position:relative;}
.rail::before{content:""; position:absolute; inset:0; pointer-events:none; background:radial-gradient(340px 220px at 50% 0%, rgba(37,99,235,.28), transparent 70%);}
.rail > *{position:relative; z-index:1;}
.rail-logo{display:flex; align-items:center; gap:10px; padding:4px 8px 18px; margin-bottom:4px; border-bottom:1px solid rgba(255,255,255,.09);}
.rail-logo .logo-mk{width:34px; height:34px;}
.rail-logo .logo-tx{color:#fff; font-size:18px;}
.rail-logo .logo-tx i{color:#6C80A8;}
.rail-sec{font-family:var(--f-mono); font-size:9.5px; letter-spacing:.18em; text-transform:uppercase; color:#5B6E96; padding:16px 12px 7px; font-weight:600;}
.rail-btn{display:flex; align-items:center; gap:11px; width:100%; padding:10px 12px; border-radius:12px; background:none; border:none; color:#93A6CC; font-size:13.5px; font-weight:600; transition:.16s; text-align:left; margin-bottom:2px;}
.rail-btn:hover{background:rgba(255,255,255,.07); color:#fff;}
.rail-btn.on{background:var(--grad); color:#fff; box-shadow:0 6px 18px rgba(37,99,235,.4);}
.rail-btn .ct{margin-left:auto; font-family:var(--f-mono); font-size:10.5px; background:rgba(255,255,255,.13); padding:2px 7px; border-radius:999px;}
.rail-foot{margin-top:auto; padding-top:14px; border-top:1px solid rgba(255,255,255,.09);}
.rail-user{display:flex; align-items:center; gap:10px; padding:10px 11px; border-radius:12px; background:rgba(255,255,255,.07); margin-bottom:8px;}
.rail-user .av{width:30px; height:30px; border-radius:10px; background:var(--grad); color:#fff; display:grid; place-items:center; font-weight:800; font-size:12.5px; font-family:var(--f-display); flex-shrink:0;}
.rail-user .nm{font-size:12.5px; color:#fff; font-weight:700; line-height:1.2;}
.rail-user .rl{font-family:var(--f-mono); font-size:9.5px; color:#6C80A8; letter-spacing:.1em; text-transform:uppercase;}
.cmain{min-width:0; display:flex; flex-direction:column;}
.ctop{background:rgba(255,255,255,.82); backdrop-filter:blur(18px); border-bottom:1px solid var(--line); padding:0 24px; height:64px; display:flex; align-items:center; gap:14px; position:sticky; top:0; z-index:40;}
.ctop h1{font-size:20px; letter-spacing:-.03em;}
.ctop .crumb{font-family:var(--f-mono); font-size:10px; color:var(--ink3); letter-spacing:.12em; text-transform:uppercase;}
.cbody{padding:22px 24px 70px; min-width:0;}
.covers{display:grid; grid-template-columns:repeat(auto-fit,minmax(196px,1fr)); gap:12px; margin-bottom:18px;}
.cover{background:rgba(255,255,255,.92); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r); padding:16px 18px; position:relative; overflow:hidden; box-shadow:var(--sh-1);}
.cover .ch{display:flex; align-items:center; gap:9px; margin-bottom:11px;}
.cover .cvi{width:32px; height:32px; border-radius:10px; display:grid; place-items:center; background:var(--blue-soft); color:var(--blue); flex-shrink:0;}
.cover .cvl{font-size:11px; color:var(--ink2); font-weight:700; letter-spacing:.01em;}
.cover .cvv{font-family:var(--f-display); font-size:26px; font-weight:800; letter-spacing:-.035em; line-height:1;}
.cover .cvs{font-size:11.5px; color:var(--ink2); margin-top:6px; display:flex; align-items:center; gap:5px;}
.cover .cvs.up{color:var(--ok);} .cover .cvs.dn{color:var(--bad);}
.cover .mtr{margin-top:11px;}
.pgrid{display:grid; gap:14px; margin-bottom:14px;}
.pgrid.two{grid-template-columns:1.55fr 1fr;}
.pgrid.even{grid-template-columns:1fr 1fr;}
.pgrid.three{grid-template-columns:repeat(3,1fr);}
.cpanel{background:rgba(255,255,255,.92); backdrop-filter:blur(12px); border:1px solid rgba(255,255,255,.9); border-radius:var(--r); overflow:hidden; box-shadow:var(--sh-1);}
.cpanel-h{display:flex; align-items:center; gap:10px; padding:15px 18px; border-bottom:1px solid var(--line); flex-wrap:wrap;}
.cpanel-h h3{font-size:15px; display:flex; align-items:center; gap:8px;}
.cpanel-h h3 svg{color:var(--blue);}
.cpanel-h .r{margin-left:auto; display:flex; align-items:center; gap:8px;}
.cpanel-b{padding:17px;}
.cpanel-b.flush{padding:0;}
.dtable{width:100%; border-collapse:collapse; font-size:13px;}
.dtable th{text-align:left; font-size:11px; color:var(--ink2); font-weight:700; padding:12px 14px; border-bottom:1px solid var(--line2); background:var(--surface2); white-space:nowrap; position:sticky; top:0;}
.dtable td{padding:11px 14px; border-bottom:1px solid var(--line); vertical-align:middle;}
.dtable tbody tr{transition:.14s;}
.dtable tbody tr:hover{background:var(--surface2);}
.dtable tbody tr.sel{background:var(--blue-soft);}
.dtable tbody tr.dim{opacity:.5;}
.dtable tbody tr:last-child td{border-bottom:none;}
.dtable .num{font-family:var(--f-mono); font-variant-numeric:tabular-nums; white-space:nowrap;}
.dtable .act{display:flex; gap:4px; justify-content:flex-end;}
.prodcell{display:flex; align-items:center; gap:11px; min-width:200px;}
.prodcell .pm{width:36px; height:36px; border-radius:11px; background:var(--grad-soft); border:1px solid var(--line); display:grid; place-items:center; color:var(--blue); flex-shrink:0;}
.prodcell .pn{font-weight:700; font-size:13px; line-height:1.25;}
.prodcell .ps{font-family:var(--f-mono); font-size:10px; color:var(--ink3); margin-top:1px;}
.cinp{width:100%; max-width:104px; border:1px solid transparent; background:var(--surface2); border-radius:9px; padding:7px 10px; font-family:var(--f-mono); font-size:12.5px; outline:none; transition:.16s;}
.cinp:hover{border-color:var(--line2);}
.cinp:focus{border-color:var(--blue-soft2); background:#fff; box-shadow:0 0 0 3px var(--blue-tint);}
.cinp.txt{font-family:var(--f-body); max-width:none;}
.cbx{width:18px; height:18px; border-radius:5px; border:1.5px solid var(--line3); display:grid; place-items:center; background:#fff; color:transparent; transition:.16s; cursor:pointer;}
.cbx.on{background:var(--grad); border-color:transparent; color:#fff;}
.toolbar{display:flex; align-items:center; gap:9px; flex-wrap:wrap; margin-bottom:14px;}
.toolbar .grow{flex:1; min-width:190px;}
.bulkbar{display:flex; align-items:center; gap:9px; padding:11px 16px; background:linear-gradient(110deg,#0C1330,#1B1147); color:#fff; border-radius:var(--r); margin-bottom:12px; flex-wrap:wrap; animation:fadeUp .2s; box-shadow:var(--sh-2);}
.bulkbar .n{font-family:var(--f-mono); font-size:12.5px; margin-right:6px;}
.bulkbar .btn{background:rgba(255,255,255,.1); border-color:rgba(255,255,255,.16); color:#fff; box-shadow:none;}
.bulkbar .btn:hover{background:rgba(255,255,255,.2); border-color:rgba(255,255,255,.3);}
.bulkbar select{background:rgba(255,255,255,.1); border:1px solid rgba(255,255,255,.16); color:#fff; border-radius:999px; padding:7px 13px; font-size:12.5px; outline:none;}
.bulkbar select option{color:var(--ink);}
.ocard{background:rgba(255,255,255,.92); border:1px solid rgba(255,255,255,.9); border-radius:var(--r); margin-bottom:9px; overflow:hidden; transition:.18s; box-shadow:var(--sh-1);}
.ocard.open{border-color:var(--blue-soft2); box-shadow:var(--sh-2);}
.ohead{display:grid; grid-template-columns:136px 1.5fr 1fr 128px 118px 36px; gap:12px; align-items:center; padding:14px 17px; cursor:pointer;}
.oid{font-family:var(--f-mono); font-size:12.5px; font-weight:700;}
.oid small{display:block; font-size:10px; color:var(--ink3); font-weight:400;}
.ocust{font-size:13px; font-weight:700; line-height:1.25;}
.ocust small{display:block; font-size:11.5px; color:var(--ink2); font-weight:400; display:flex; align-items:center; gap:4px; margin-top:1px;}
.ostat{display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:700; padding:5px 11px; border-radius:999px; white-space:nowrap;}
.ototal{font-family:var(--f-display); font-size:15px; font-weight:800; text-align:right; letter-spacing:-.03em;}
.ototal small{display:block; font-size:9.5px; color:var(--ink3); font-weight:600; font-family:var(--f-mono); letter-spacing:.08em;}
.obody{border-top:1px solid var(--line); padding:18px 17px; background:var(--surface2); animation:fadeUp .2s;}
.ogrid{display:grid; grid-template-columns:1.35fr 1fr; gap:22px;}
.oline{display:flex; align-items:center; gap:11px; padding:9px 0; border-bottom:1px dashed var(--line);}
.oline:last-child{border-bottom:none;}
.oline .om{width:34px; height:34px; border-radius:10px; background:#fff; border:1px solid var(--line); display:grid; place-items:center; color:var(--blue); flex-shrink:0;}
.oline .on{font-size:12.5px; font-weight:600; flex:1; min-width:0; line-height:1.3;}
.oline .oq{font-family:var(--f-mono); font-size:11px; color:var(--ink2);}
.oline .op{font-family:var(--f-mono); font-size:12.5px; font-weight:700;}
.stepper{display:flex; align-items:center; margin:4px 0 16px;}
.step{flex:1; display:flex; flex-direction:column; align-items:center; position:relative;}
.step .dot{width:24px; height:24px; border-radius:50%; background:#fff; border:2px solid var(--line2); display:grid; place-items:center; color:var(--ink3); z-index:1; transition:.22s;}
.step.done .dot{background:var(--grad); border-color:transparent; color:#fff;}
.step.cur .dot{background:var(--grad); border-color:transparent; color:#fff; box-shadow:0 0 0 5px var(--blue-tint);}
.step .lbl{font-size:9.5px; font-weight:700; color:var(--ink3); margin-top:7px; text-align:center;}
.step.done .lbl,.step.cur .lbl{color:var(--ink);}
.step::before{content:""; position:absolute; top:12px; left:-50%; width:100%; height:2px; background:var(--line2);}
.step:first-child::before{display:none;}
.step.done::before,.step.cur::before{background:var(--blue);}
.pager{display:flex; align-items:center; justify-content:center; gap:8px; margin-top:16px;}
.pager .pgl{font-family:var(--f-mono); font-size:12px; color:var(--ink2); padding:0 8px;}
.ctree{display:flex; flex-direction:column;}
.cnode{display:flex; align-items:center; gap:12px; padding:12px 16px; border-bottom:1px solid var(--line); transition:.14s;}
.cnode:hover{background:var(--surface2);}
.cnode:last-child{border-bottom:none;}
.cnode.child{padding-left:40px; background:var(--surface2);}
.cnode.child:hover{background:var(--surface3);}
.cnode .cn-ic{width:36px; height:36px; border-radius:11px; background:var(--grad-soft); display:grid; place-items:center; color:var(--blue); flex-shrink:0;}
.cnode.child .cn-ic{width:30px; height:30px; background:#fff; border:1px solid var(--line);}
.cnode .cn-n{font-weight:700; font-size:13.5px; line-height:1.3;}
.cnode .cn-d{font-size:11.5px; color:var(--ink2); margin-top:1px;}
.cnode .cn-m{margin-left:auto; display:flex; align-items:center; gap:16px;}
.cnode .cn-stat{text-align:right;}
.cnode .cn-stat .v{font-family:var(--f-mono); font-size:13px; font-weight:700;}
.cnode .cn-stat .k{font-size:9.5px; text-transform:uppercase; color:var(--ink3); font-weight:600; letter-spacing:.08em;}
.cnode .cn-act{display:flex; gap:4px;}
.cust{display:flex; align-items:center; gap:13px; background:rgba(255,255,255,.92); border:1px solid rgba(255,255,255,.9); border-radius:var(--r); padding:14px 17px; margin-bottom:8px; transition:.18s; cursor:pointer; box-shadow:var(--sh-1);}
.cust:hover{border-color:var(--blue-soft2); transform:translateX(3px);}
.cust .ava{width:40px; height:40px; border-radius:13px; display:grid; place-items:center; font-family:var(--f-display); font-weight:800; font-size:14px; color:#fff; flex-shrink:0;}
.cust .cn{font-weight:700; font-size:13.5px;}
.cust .cc{font-size:11.5px; color:var(--ink2); display:flex; align-items:center; gap:5px; margin-top:2px;}
.cust .cstats{margin-left:auto; display:flex; gap:24px;}
.cstat{text-align:right;}
.cstat .v{font-family:var(--f-mono); font-size:13.5px; font-weight:700;}
.cstat .k{font-size:9.5px; text-transform:uppercase; color:var(--ink3); margin-top:1px; font-weight:600; letter-spacing:.08em;}
.prow{display:flex; align-items:center; gap:13px; padding:14px 17px; border-bottom:1px solid var(--line); transition:.14s;}
.prow:last-child{border-bottom:none;}
.prow:hover{background:var(--surface2);}
.prow.off{opacity:.55;}
.prow .pi{width:36px; height:36px; border-radius:11px; background:var(--violet-soft); color:var(--violet); display:grid; place-items:center; flex-shrink:0;}
.prow .pn{font-weight:700; font-size:13.5px;}
.prow .pd{font-size:11.5px; color:var(--ink2); margin-top:1px;}
.prow .pv{font-family:var(--f-mono); font-size:13px; font-weight:700; color:var(--blue-d);}
.codetag{font-family:var(--f-mono); font-size:10.5px; font-weight:700; letter-spacing:.08em; padding:3px 9px; border-radius:999px; background:var(--ink); color:var(--cyan);}
.alog{display:flex; gap:12px; padding:12px 17px; border-bottom:1px solid var(--line); font-size:13px;}
.alog:last-child{border-bottom:none;}
.alog .ai{width:30px; height:30px; border-radius:10px; background:var(--surface2); display:grid; place-items:center; color:var(--blue); flex-shrink:0;}
.alog .am{flex:1; min-width:0; line-height:1.45;}
.alog .at{font-family:var(--f-mono); font-size:10.5px; color:var(--ink3); white-space:nowrap;}
.calc-out{background:linear-gradient(160deg,#0C1330,#1B1147); color:#A9B7D6; border-radius:var(--r); padding:20px; box-shadow:var(--sh-2);}
.calc-out h3{color:#fff; font-size:15px; display:flex; align-items:center; gap:8px; margin-bottom:14px;}
.calc-out h3 svg{color:var(--cyan);}
.calc-out .finp,.calc-out .select{background:rgba(255,255,255,.08); border-color:rgba(255,255,255,.15); color:#fff;}
.calc-out .finp:focus,.calc-out .select:focus{border-color:var(--cyan); box-shadow:none;}
.calc-out .select option{color:var(--ink);}
.calc-line{display:flex; justify-content:space-between; align-items:center; padding:7px 0; font-size:13px;}
.calc-line.big{font-size:17px; font-weight:700; color:#fff; padding-top:11px;}
.alert-row{display:flex; align-items:center; gap:12px; padding:12px 17px; border-bottom:1px solid var(--line);}
.alert-row:last-child{border-bottom:none;}
.alert-row .ai{width:32px; height:32px; border-radius:10px; display:grid; place-items:center; flex-shrink:0;}
.alert-row .an{font-size:13px; font-weight:700; line-height:1.25;}
.alert-row .as{font-family:var(--f-mono); font-size:10px; color:var(--ink3); margin-top:2px;}
.rankrow{display:flex; align-items:center; gap:11px; padding:9px 0 3px;}
.rankrow .rk{font-family:var(--f-mono); font-size:11px; color:var(--ink3); width:18px; flex-shrink:0;}
.rankrow .rn{font-size:12.5px; font-weight:600; flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.rankrow .rv{font-family:var(--f-mono); font-size:12px; font-weight:700; white-space:nowrap;}
.rankbar{height:6px; border-radius:3px; background:var(--surface3); overflow:hidden;}
.rankbar i{display:block; height:100%; background:var(--grad); border-radius:3px;}
.login-screen{min-height:100vh; display:grid; place-items:center; padding:40px 20px; position:relative;}
.login-card{width:100%; max-width:430px; border:1px solid rgba(255,255,255,.9); border-radius:var(--r-xl); background:rgba(255,255,255,.9); backdrop-filter:blur(20px); padding:36px 34px; position:relative; z-index:1; box-shadow:var(--sh-3);}
.login-lock{width:58px; height:58px; border-radius:18px; margin:0 auto 18px; display:grid; place-items:center; background:var(--grad); color:#fff; box-shadow:0 12px 28px rgba(37,99,235,.4);}
.login-card h2{text-align:center; font-size:23px; margin-bottom:5px;}
.login-card .ls{text-align:center; color:var(--ink2); font-size:13.5px; margin-bottom:24px;}
.login-err{background:var(--bad-soft); border:1px solid rgba(220,47,62,.28); color:var(--bad); border-radius:var(--r-sm); padding:11px 13px; font-size:12.5px; margin-bottom:14px; display:flex; align-items:center; gap:8px; font-weight:600;}

/* ── animations ─────────────────────────────────────────────── */
@keyframes fade{from{opacity:0}to{opacity:1}}
@keyframes fadeUp{from{opacity:0; transform:translateY(12px)}to{opacity:1; transform:none}}
@keyframes pop{from{opacity:0; transform:scale(.96) translateY(8px)}to{opacity:1; transform:none}}
@keyframes slideIn{from{transform:translateX(100%)}to{transform:none}}
@keyframes slideUp{from{transform:translateY(100%)}to{transform:none}}
@keyframes toastIn{from{opacity:0; transform:translateX(28px)}to{opacity:1; transform:none}}
@keyframes tickIn{from{opacity:0; transform:translateY(-8px)}to{opacity:1; transform:none}}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-11px)}}
@media (prefers-reduced-motion:reduce){ .tx *{animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important;} }

/* ══════════ RESPONSIVE ══════════ */
@media (max-width:1240px){
  .nav-search{width:200px;}
  .nav-links .nlink{padding:9px 10px; font-size:13px;}
  .grid.five{grid-template-columns:repeat(3,1fr);}
}
@media (max-width:1180px){
  .hero-in{grid-template-columns:1fr; padding:38px 30px 0;}
  .podium{height:290px;}
  .hero-dots{display:none;}
  .shop-grid{grid-template-columns:230px 1fr;}
  .grid{grid-template-columns:repeat(3,1fr);}
  .pgrid.two,.pgrid.even{grid-template-columns:1fr;}
  .pgrid.three{grid-template-columns:1fr 1fr;}
  .cshell{grid-template-columns:78px 1fr;}
  .rail-logo .logo-tx,.rail-btn span.lb,.rail-btn .ct,.rail-sec,.rail-user .nm,.rail-user .rl{display:none;}
  .rail-btn{justify-content:center; padding:11px;}
  .rail-user{justify-content:center;}
  .catrow{grid-template-columns:repeat(2,1fr);}
  .foot-grid{grid-template-columns:1.4fr repeat(2,1fr); }
}
@media (max-width:980px){
  .nav-links,.nav-search{display:none;}
  .menu-btn{display:grid;}
  .grid,.grid.five{grid-template-columns:repeat(2,1fr);}
  .co-grid{grid-template-columns:1fr;}
  .co-summary{position:static;}
  .foot-grid{grid-template-columns:1fr 1fr;}
  .trust{grid-template-columns:1fr 1fr;}
  .trust-cell:nth-child(2){border-right:none;}
  .shop-grid{grid-template-columns:1fr;}
  .filters{position:static;}
  .shophero{grid-template-columns:1fr;}
  .shophero .podium{display:none;}
  .ohead{grid-template-columns:1fr 1fr; gap:10px;}
  .ogrid{grid-template-columns:1fr;}
  .pd-hero{grid-template-columns:1fr;}
  .form-row,.form-row.three{grid-template-columns:1fr;}
  .grid.list .card{flex-direction:column;}
  .grid.list .card-media{width:100%; min-height:150px;}
  .grid.list .card-body{flex-direction:column; align-items:stretch;}
  .grid.list .card-foot,.grid.list .lb-mid{width:100%;}
  .grid.list .card-sub,.grid.list .card-rate,.grid.list .stockline{margin-bottom:9px;}
}
@media (max-width:640px){
  .wrap{padding:0 16px;}
  .cbody{padding:18px 15px 60px;} .ctop{padding:0 15px;}
  .grid,.grid.five,.catrow{grid-template-columns:1fr;}
  .foot-grid{grid-template-columns:1fr;}
  .trust{grid-template-columns:1fr; margin:24px 14px 14px;}
  .trust-cell{border-right:none; border-bottom:1px solid var(--line);}
  .trust-cell:last-child{border-bottom:none;}
  .section{padding:38px 0;} .hero-in{padding:30px 20px 0;}
  .band{padding:22px; gap:18px;} .band .orb{display:none;}
  .band .news input{width:100%;}
  .annc-r{display:none;}
  .modal-wrap{padding:0; align-items:flex-end;}
  .modal{max-height:94vh; border-radius:var(--r-xl) var(--r-xl) 0 0;}
  .pgrid.three{grid-template-columns:1fr;}
  .cust .cstats{display:none;}
  .toasts{left:16px; right:16px; align-items:stretch;}
  .toast{max-width:none;}
  .shophero{padding:26px 20px;}
  .podium{height:230px;} .podium .r3{display:none;}
}
/* ── finance ledger ── */
.carrier{border:1px solid var(--line); border-radius:var(--r); padding:13px 14px; margin-bottom:11px; background:var(--surface2);}
.carrier:last-child{margin-bottom:0;}
.cr-top{display:flex; align-items:flex-start; gap:12px; margin-bottom:11px;}
.cr-n{font-family:var(--f-display); font-weight:700; font-size:14.5px; letter-spacing:-.01em;}
.cr-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.cr-net{margin-left:auto; font-family:var(--f-mono); font-size:12.5px; font-weight:600; padding:5px 10px; border-radius:999px; white-space:nowrap;}
.cr-net.pos{background:var(--ok-soft); color:var(--ok);}
.cr-net.neg{background:var(--bad-soft); color:var(--bad);}
.cr-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:9px; margin-bottom:11px;}
.cr-grid > div{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-xs); padding:8px 9px; display:flex; flex-direction:column; gap:2px; min-width:0;}
.cr-grid .k{font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.06em;}
.cr-grid .v{font-family:var(--f-mono); font-size:13px; font-weight:600;}
.cr-grid .v.ok{color:var(--ok);} .cr-grid .v.bad{color:var(--bad);}
.cr-grid .n{font-size:10.5px; color:var(--ink4);}
.cr-acts{display:flex; gap:8px; flex-wrap:wrap;}
.segbtn{display:inline-flex; border:1px solid var(--line2); border-radius:999px; overflow:hidden; background:var(--surface);}
.segbtn button{border:none; background:none; padding:6px 13px; font-size:12px; font-weight:600; color:var(--ink2);}
.segbtn button.on{background:var(--grad); color:#fff;}
.dtable th.num,.dtable td.num{text-align:right; white-space:nowrap;}
.dtable td.num.pos{color:var(--ok);} .dtable td.num.neg{color:var(--bad);}
.muted3{color:var(--ink4); font-size:11.5px;}
.calc-line.strong{font-weight:700; color:#fff;}
@media (max-width:980px){ .cr-grid{grid-template-columns:repeat(2,1fr);} }
.logo-mk.img{background:var(--surface); border:1px solid var(--line2); box-shadow:var(--sh-1);}
.logo-mk.img::after{display:none;}
.logo-mk.img img{width:100%; height:100%; object-fit:contain; padding:4px; border-radius:inherit;}
.logo-set{display:flex; gap:12px; align-items:flex-start;}
.logo-prev{width:66px; height:66px; border-radius:var(--r-sm); border:1px solid var(--line); background:var(--surface2); display:grid; place-items:center; flex-shrink:0; overflow:hidden;}
.logo-prev img{max-width:100%; max-height:100%; object-fit:contain; padding:6px;}
.logo-ctl{flex:1; min-width:0; display:flex; flex-direction:column; gap:8px;}
.logo-btns{display:flex; gap:8px; flex-wrap:wrap;}
/* ── reporting ── */
.rangebar{display:flex; gap:12px; align-items:center; flex-wrap:wrap; background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:11px 13px; margin-bottom:14px; box-shadow:var(--sh-1);}
.rb-presets{display:flex; gap:5px; flex-wrap:wrap;}
.rb-presets button{border:1px solid var(--line2); background:var(--surface); border-radius:999px; padding:6px 12px; font-size:12px; font-weight:600; color:var(--ink2); transition:.16s;}
.rb-presets button:hover{border-color:var(--blue); color:var(--blue-d);}
.rb-presets button.on{background:var(--grad); border-color:transparent; color:#fff; box-shadow:var(--sh-blue);}
.rb-dates{display:flex; gap:10px; align-items:flex-end; margin-left:auto; flex-wrap:wrap;}
.rb-dates label{display:flex; flex-direction:column; gap:3px; font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.06em; font-weight:700;}
.dinp{border:1px solid var(--line2); background:var(--surface); border-radius:var(--r-xs); padding:6px 9px; font-size:12.5px; font-family:var(--f-mono); color:var(--ink);}
.dinp:focus{outline:none; border-color:var(--blue); box-shadow:0 0 0 3px var(--blue-tint);}
.segbtn.wide{width:100%;} .segbtn.wide button{flex:1;}

.pl-row{display:flex; align-items:baseline; gap:12px; padding:7px 0; border-bottom:1px dashed var(--line);}
.pl-row:last-child{border-bottom:none;}
.pl-l{font-size:13px; color:var(--ink2); display:flex; flex-direction:column;}
.pl-l small{font-size:10.5px; color:var(--ink4); margin-top:1px;}
.pl-v{margin-left:auto; font-family:var(--f-mono); font-size:13px; font-weight:600; white-space:nowrap;}
.pl-v.neg{color:var(--bad);}
.pl-row.cost .pl-v{color:var(--ink2);}
.pl-row.strong{border-bottom:1px solid var(--line2); border-top:1px solid var(--line2); background:var(--surface2); margin:3px -13px; padding:9px 13px;}
.pl-row.strong .pl-l{font-weight:700; color:var(--ink); font-family:var(--f-display);}
.pl-row.strong .pl-v{font-size:14.5px; font-weight:700;}
.pl-sec{font-size:10.5px; text-transform:uppercase; letter-spacing:.08em; color:var(--ink3); font-weight:700; margin:14px 0 3px;}

.readout{display:grid; grid-template-columns:repeat(2,1fr); gap:8px; margin-bottom:12px;}
.readout > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:8px 10px; display:flex; flex-direction:column; gap:2px;}
.readout .k{font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.05em;}
.readout .v{font-family:var(--f-mono); font-size:14px; font-weight:700;}
.advice{list-style:none; display:flex; flex-direction:column; gap:8px;}
.advice li{display:flex; gap:8px; align-items:flex-start; font-size:12.5px; line-height:1.5; color:var(--ink2); background:var(--surface2); border:1px solid var(--line); border-left:3px solid var(--ink4); border-radius:var(--r-xs); padding:9px 11px;}
.advice li svg{flex-shrink:0; margin-top:2px;}
.advice li.warn{border-left-color:var(--warn); background:var(--warn-soft);}
.advice li.bad{border-left-color:var(--bad); background:var(--bad-soft);}
.advice li.ok{border-left-color:var(--ok); background:var(--ok-soft);}
.cvs.up{color:var(--ok); display:flex; align-items:center; gap:3px;}
.cvs.down{color:var(--bad); display:flex; align-items:center; gap:3px;}

.grade{display:inline-grid; place-items:center; width:22px; height:22px; border-radius:7px; font-size:11px; font-weight:800; font-family:var(--f-mono);}
.grade.gA{background:var(--ok-soft); color:var(--ok);}
.grade.gB{background:var(--blue-soft); color:var(--blue-d);}
.grade.gC{background:var(--surface3); color:var(--ink3);}
.mtag{padding:2px 7px; border-radius:999px; font-size:11px; font-weight:700;}
.mtag.ok{background:var(--ok-soft); color:var(--ok);}
.mtag.warn{background:var(--warn-soft); color:var(--warn);}
.mtag.bad{background:var(--bad-soft); color:var(--bad);}
.dtable tr.danger-row{background:rgba(220,47,62,.045);}
.dtable tr.hl{background:var(--blue-tint);}
.fixrow{display:flex; align-items:center; gap:12px; padding:9px 0; border-bottom:1px dashed var(--line);}
.fixrow:last-child{border-bottom:none;}
.fx-n{font-weight:650; font-size:13px;}
.fx-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.fixrow .btn{margin-left:auto; flex-shrink:0;}

.pgrid.sidebar{display:grid; grid-template-columns:minmax(0,1.25fr) minmax(0,1fr); gap:14px; align-items:start;}
.pricecard{background:var(--grad); color:#fff; border-radius:var(--r-lg); padding:20px; box-shadow:var(--sh-3); position:relative; overflow:hidden;}
.pricecard::after{content:""; position:absolute; inset:0; background:radial-gradient(600px 220px at 90% -20%, rgba(255,255,255,.34), transparent 62%); pointer-events:none;}
.pricecard.bad{background:linear-gradient(135deg,#9F1239,#DC2F3E);}
.pc-l{font-size:11px; text-transform:uppercase; letter-spacing:.1em; opacity:.82; font-weight:700;}
.pc-v{font-family:var(--f-display); font-size:38px; font-weight:800; letter-spacing:-.03em; line-height:1.05; margin:4px 0 5px;}
.pc-s{font-size:12.5px; opacity:.88; line-height:1.5;}
.pc-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-top:15px; position:relative; z-index:1;}
.pc-grid > div{background:rgba(255,255,255,.16); border:1px solid rgba(255,255,255,.2); border-radius:var(--r-xs); padding:8px 9px; display:flex; flex-direction:column; gap:2px;}
.pc-grid .k{font-size:10px; text-transform:uppercase; letter-spacing:.05em; opacity:.85;}
.pc-grid .v{font-family:var(--f-mono); font-size:13px; font-weight:700;}
.pc-note{margin-top:13px; background:rgba(255,255,255,.16); border:1px solid rgba(255,255,255,.22); border-radius:var(--r-xs); padding:9px 11px; font-size:12px; line-height:1.5; position:relative; z-index:1;}

.stack{display:flex; height:16px; border-radius:999px; overflow:hidden; background:var(--surface3); margin-bottom:12px;}
.stack .seg{transition:width .3s cubic-bezier(.2,.8,.3,1);}
.stack-key{display:grid; grid-template-columns:repeat(2,1fr); gap:6px 14px; margin-bottom:6px;}
.stack-key > div{display:flex; align-items:center; gap:7px; font-size:12px; color:var(--ink2);}
.stack-key b{margin-left:auto; font-family:var(--f-mono); font-size:12px; color:var(--ink);}
.stack-key .dot{width:9px; height:9px; border-radius:3px; flex-shrink:0;}
.inp-suffix{position:relative; display:flex; align-items:center;}
.inp-suffix .finp{padding-right:52px;}
.inp-suffix span{position:absolute; right:11px; font-size:11px; color:var(--ink3); font-weight:600; pointer-events:none;}
.searchbox.sm{max-width:230px;}

@media (max-width:1240px){ .pgrid.sidebar{grid-template-columns:1fr;} }
@media (max-width:640px){ .rb-dates{margin-left:0;} .readout,.stack-key,.pc-grid{grid-template-columns:1fr;} }
/* ── returns ── */
.rma{border:1px solid var(--line); border-radius:var(--r); margin-bottom:9px; background:var(--surface2); overflow:hidden; transition:.16s;}
.rma:last-child{margin-bottom:0;}
.rma.on{border-color:var(--blue); box-shadow:var(--sh-2);}
.rma-top{display:flex; align-items:center; gap:11px; padding:11px 13px; cursor:pointer;}
.rma-st{display:inline-flex; align-items:center; gap:5px; padding:4px 9px; border-radius:999px; font-size:11px; font-weight:700; white-space:nowrap;}
.rma-id{display:flex; flex-direction:column; gap:2px; min-width:0;}
.rma-id .mono{font-size:12.5px; font-weight:600;}
.rma-sub{font-size:11px; color:var(--ink3); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.rma-val{margin-left:auto; text-align:right; display:flex; flex-direction:column; gap:2px;}
.rma-val .mono{font-size:13px; font-weight:700;}
.rma-cv{color:var(--ink3); transition:.2s; flex-shrink:0;}
.rma.on .rma-cv{transform:rotate(180deg);}
.rma-body{padding:0 13px 13px; border-top:1px solid var(--line);}
.rma-meta{display:grid; grid-template-columns:repeat(2,1fr); gap:8px; margin:12px 0;}
.rma-meta > div{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-xs); padding:7px 9px; display:flex; flex-direction:column; gap:2px;}
.rma-meta .k{font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.05em;}
.rma-meta .v{font-size:12.5px; font-weight:600;}
.rma-note{background:var(--surface); border-left:3px solid var(--blue); border-radius:var(--r-xs); padding:9px 11px; font-size:12.5px; color:var(--ink2); margin-bottom:11px; line-height:1.5;}
.dtable.tight th,.dtable.tight td{padding:7px 9px; font-size:12px;}
.rma-result{display:flex; align-items:center; gap:7px; background:var(--ok-soft); color:var(--ok); border-radius:var(--r-xs); padding:8px 11px; font-size:12.5px; font-weight:600; margin:11px 0;}
.rma-acts{display:flex; gap:8px; flex-wrap:wrap; margin:12px 0;}
.rma-timeline{border-top:1px dashed var(--line); padding-top:11px; display:flex; flex-direction:column; gap:7px;}
.rma-timeline > div{display:flex; align-items:center; gap:8px; font-size:12px; color:var(--ink2);}
.rma-timeline .dot{width:7px; height:7px; border-radius:50%; background:var(--blue); flex-shrink:0;}
.rma-timeline .tl-t{margin-left:auto; font-size:11px; color:var(--ink4); font-family:var(--f-mono);}
.reason{margin-bottom:11px;}
.rs-t{display:flex; justify-content:space-between; font-size:12.5px; margin-bottom:5px; color:var(--ink2);}
.rs-bar{height:7px; border-radius:999px; background:var(--surface3); overflow:hidden;}
.rs-bar span{display:block; height:100%; background:var(--grad); border-radius:999px;}
.retline{display:flex; align-items:center; gap:12px; padding:10px 0; border-bottom:1px dashed var(--line);}
.retline:last-child{border-bottom:none;}
.rl-n{font-size:13px; font-weight:600;}
.rl-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.retline .qty{margin-left:auto;}
.qty.sm button{width:26px; height:26px;} .qty.sm span{min-width:26px; font-size:12.5px;}
.retsum{display:flex; justify-content:space-between; align-items:center; background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:11px 13px; font-size:13px; font-weight:700; margin-top:6px;}

/* ── invoice ── */
.inv-wrap{position:fixed; inset:0; background:rgba(10,16,32,.62); backdrop-filter:blur(6px); z-index:120; overflow-y:auto; padding:22px 16px; display:flex; justify-content:center; align-items:flex-start;}
.inv-shell{width:100%; max-width:820px;}
.inv-actions{display:flex; align-items:center; gap:10px; margin-bottom:12px;}
.inv-actions .r{margin-left:auto; display:flex; gap:8px; align-items:center;}
.inv-actions .iconbtn{background:rgba(255,255,255,.9);}
.invoice-sheet{background:#fff; border-radius:var(--r-lg); overflow:hidden; box-shadow:0 26px 70px rgba(10,16,32,.34); color:#101828; position:relative; font-variant-numeric:tabular-nums;}
.inv-band{height:7px; background:var(--iv-band);}
.inv-water{position:absolute; top:150px; right:30px; font-family:var(--f-display); font-size:104px; font-weight:900; letter-spacing:.06em; color:var(--iv-stamp-bg); transform:rotate(-16deg); pointer-events:none; user-select:none; line-height:1; z-index:0;}
.invoice-sheet > *:not(.inv-water):not(.inv-band){position:relative; z-index:1;}
.inv-head{display:flex; gap:24px; padding:28px 34px 20px; align-items:flex-start;}
.inv-brand{display:flex; gap:13px; align-items:flex-start;}
.inv-mk{width:44px; height:44px; border-radius:13px; background:var(--iv-band); display:grid; place-items:center; flex-shrink:0;}
.inv-logo{width:44px; height:44px; object-fit:contain; border-radius:11px; flex-shrink:0;}
.inv-name{font-family:var(--f-display); font-size:21px; font-weight:800; letter-spacing:-.02em; line-height:1.1; color:#101828;}
.inv-sub{font-size:12px; color:#667085; margin-top:2px;}
.inv-contact{display:flex; flex-direction:column; gap:1px; margin-top:7px;}
.inv-contact span{font-size:10.5px; color:#98A2B3; line-height:1.5;}
.inv-doc{margin-left:auto; text-align:right;}
.inv-kind{font-size:10.5px; text-transform:uppercase; letter-spacing:.13em; color:#667085; font-weight:700;}
.inv-no{font-family:var(--f-display); font-size:25px; font-weight:800; letter-spacing:-.02em; margin:1px 0 8px; color:var(--iv-accent);}
.inv-meta{margin-left:auto; font-size:11.5px; border-collapse:collapse;}
.inv-meta td{padding:2px 0; text-align:right; color:#101828;}
.inv-meta td:first-child{color:#98A2B3; padding-right:16px; text-align:left;}
.inv-parties{display:grid; grid-template-columns:repeat(4,1fr); gap:18px; padding:16px 34px 20px; margin:0 34px 0; border-top:1px solid #EAECF0; border-bottom:1px solid #EAECF0; padding-left:0; padding-right:0;}
.inv-parties h4{font-size:10px; text-transform:uppercase; letter-spacing:.11em; color:#98A2B3; margin-bottom:6px; font-weight:700;}
.inv-parties p{font-size:12px; line-height:1.55; color:#475467;}
.inv-parties p.strong{font-weight:700; color:#101828;}
.inv-stamp{display:inline-block; margin-top:7px; padding:3px 9px; border-radius:999px; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:.07em; background:var(--iv-stamp-bg); color:var(--iv-stamp);}
.inv-table{width:100%; border-collapse:collapse; margin-top:4px;}
.inv-table thead th{background:var(--iv-tint); font-size:10px; text-transform:uppercase; letter-spacing:.09em; color:#475467; text-align:left; padding:10px 12px; font-weight:700;}
.inv-table thead th:first-child{padding-left:34px;} .inv-table thead th:last-child{padding-right:34px;}
.inv-table td{padding:11px 12px; font-size:12.5px; border-bottom:1px solid #F2F4F7; vertical-align:top; color:#344054;}
.inv-table td:first-child{padding-left:34px;} .inv-table td:last-child{padding-right:34px;}
.inv-table .c-no{width:34px; color:#98A2B3;}
.inv-table .c-n{text-align:right; white-space:nowrap;}
.inv-table .c-n.strong{font-weight:700; color:#101828;}
.inv-table .c-sku{color:#667085; font-size:11px;}
.inv-table .l-name{display:block; font-weight:650; color:#101828;}
.inv-table .l-sub{display:block; font-size:10.5px; color:#98A2B3; margin-top:2px;}
.inv-table .l-was{display:block; font-size:10.5px; color:#98A2B3; text-decoration:line-through; margin-top:1px;}
.inv-foot{display:flex; gap:30px; padding:22px 34px 6px; align-items:flex-start;}
.inv-notes{flex:1; min-width:0;}
.inv-words{background:var(--iv-tint); border-left:3px solid var(--iv-accent); border-radius:var(--r-xs); padding:9px 12px; margin-bottom:15px;}
.inv-words .w-l{display:block; font-size:9.5px; text-transform:uppercase; letter-spacing:.11em; color:#667085; font-weight:700;}
.inv-words .w-v{display:block; font-size:12.5px; font-weight:700; color:#101828; margin-top:2px; line-height:1.45;}
.inv-notes h4{font-size:10px; text-transform:uppercase; letter-spacing:.11em; color:#98A2B3; margin:0 0 5px; font-weight:700;}
.inv-notes h4 + p{margin-bottom:13px;}
.inv-notes p{font-size:11.5px; line-height:1.6; color:#667085;}
.inv-window{font-weight:600; color:#475467;}
.inv-sums{width:270px; flex-shrink:0;}
.s-row{display:flex; justify-content:space-between; padding:6px 0; font-size:12.5px; color:#475467;}
.s-row.total{border-top:2px solid #101828; margin-top:7px; padding-top:11px; font-size:17px; font-weight:800; color:#101828; font-family:var(--f-display);}
.s-row.saved{color:#0B7A55; font-weight:700; font-size:12px;}
.s-row.weight{border-top:1px dashed #EAECF0; margin-top:6px; padding-top:8px; font-size:11px; color:#98A2B3;}
.inv-sign{display:flex; gap:60px; padding:26px 34px 4px;}
.inv-sign > div{flex:1;}
.sig-line{display:block; border-bottom:1px solid #D0D5DD; height:30px;}
.sig-l{display:block; font-size:10.5px; color:#98A2B3; margin-top:6px;}
.inv-end{display:flex; justify-content:space-between; gap:14px; padding:16px 34px 22px; font-size:10.5px; color:#98A2B3; border-top:1px solid #F2F4F7; margin-top:16px;}

@media (max-width:720px){
  .inv-head,.inv-parties,.inv-foot,.inv-sign{flex-direction:column; grid-template-columns:1fr; gap:16px;}
  .inv-water{font-size:64px; top:120px; right:14px;}
  .inv-doc{margin-left:0; text-align:left;} .inv-meta{margin-left:0;} .inv-meta td{text-align:left;}
  .inv-sums{width:100%;}
  .rma-meta{grid-template-columns:1fr;}
}

/* the printed document is the sheet alone, not a screenshot of the app */
@media print{
  html,body{background:#fff !important;}
  .tx > *:not(.inv-wrap){display:none !important;}
  .toasts{display:none !important;}
  .inv-wrap{position:static !important; inset:auto; background:none !important; backdrop-filter:none !important; padding:0 !important; display:block !important; overflow:visible !important;}
  .inv-shell{max-width:none !important; width:100% !important;}
  .inv-actions{display:none !important;}
  .invoice-sheet{box-shadow:none !important; border-radius:0 !important;}
  .inv-band,.inv-table thead th,.inv-stamp,.inv-mk,.inv-words,.inv-water{-webkit-print-color-adjust:exact; print-color-adjust:exact;}
  .inv-table thead{display:table-header-group;}
  .inv-table tr,.inv-sign,.inv-foot{page-break-inside:avoid;}
  .invoice-sheet{font-size:11.5px;}
  @page{size:A4; margin:14mm;}
}
.track-acts{display:flex; gap:8px; flex-wrap:wrap; margin-top:16px; padding-top:14px; border-top:1px solid var(--line);}
.track-rma{display:flex; align-items:center; gap:11px; background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:10px 12px; margin-top:9px;}
.themegrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(212px,1fr)); gap:11px; margin-bottom:6px;}
.themecard{text-align:left; background:var(--surface); border:1px solid var(--line2); border-radius:var(--r-sm); padding:12px; display:flex; flex-direction:column; gap:6px; transition:.18s cubic-bezier(.2,.8,.3,1); cursor:pointer;}
.themecard:hover{border-color:var(--blue); transform:translateY(-2px); box-shadow:var(--sh-2);}
.themecard.on{border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint), var(--sh-2);}
.tc-sw{display:flex; height:34px; border-radius:var(--r-xs); overflow:hidden; border:1px solid var(--line);}
.tc-sw span{flex:1;}
.tc-n{display:flex; align-items:center; gap:6px; font-family:var(--f-display); font-weight:700; font-size:14px; color:var(--ink);}
.tc-n svg{margin-left:auto; color:var(--blue);}
.tc-niche{font-size:11px; color:var(--blue-d); font-weight:650; text-transform:uppercase; letter-spacing:.05em;}
.tc-note{font-size:11.5px; color:var(--ink3); line-height:1.45;}
/* ── product gallery ── */
.pd-gallery{display:flex; flex-direction:column; gap:9px;}
.pd-vid{width:100%; height:100%; border:none; border-radius:inherit; position:relative; z-index:3; background:#000; object-fit:cover;}
.pd-thumbs{display:flex; gap:7px; flex-wrap:wrap;}
.pd-th{width:52px; height:52px; border-radius:var(--r-xs); border:1px solid var(--line2); background:var(--surface2); overflow:hidden; padding:0; display:grid; place-items:center; transition:.16s; flex-shrink:0;}
.pd-th img{width:100%; height:100%; object-fit:contain; padding:4px;}
.pd-th:hover{border-color:var(--blue);}
.pd-th.on{border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint);}
.pd-th.vid{color:var(--blue-d); background:var(--blue-soft);}

/* ── media rows in the editor ── */
.mediarow{display:flex; gap:7px; align-items:center; margin-bottom:7px;}
.mediarow .finp{flex:1; min-width:0;}
.mr-thumb{width:34px; height:34px; border-radius:var(--r-xs); border:1px solid var(--line2); background:var(--surface2); display:grid; place-items:center; overflow:hidden; flex-shrink:0; color:var(--ink3);}
.mr-thumb img{width:100%; height:100%; object-fit:contain; padding:2px;}
.iconbtn.danger{color:var(--bad);}

/* ── customer portal ── */
.wrap.narrow{max-width:620px;}
.portal-gate{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-lg); padding:34px 30px; text-align:center; box-shadow:var(--sh-2);}
.pg-mk{width:54px; height:54px; border-radius:var(--r); background:var(--grad); color:#fff; display:grid; place-items:center; margin:0 auto 15px;}
.portal-gate h2{font-size:clamp(21px,3vw,27px); margin-bottom:8px;}
.portal-gate > p{color:var(--ink2); font-size:14px; line-height:1.6; max-width:430px; margin:0 auto 20px;}
.pg-form{display:flex; gap:9px; max-width:420px; margin:0 auto; flex-wrap:wrap;}
.pg-form .inp{flex:1; min-width:180px;}
.pg-err{display:flex; align-items:center; justify-content:center; gap:7px; margin-top:14px; font-size:12.5px; color:var(--warn); background:var(--warn-soft); border-radius:var(--r-xs); padding:9px 12px;}
.pg-alt{background:none; border:none; color:var(--ink3); font-size:12.5px; margin-top:16px; text-decoration:underline; text-underline-offset:3px;}
.pg-alt:hover{color:var(--blue-d);}
.portal-head{display:flex; align-items:center; gap:15px; background:var(--surface); border:1px solid var(--line); border-radius:var(--r-lg); padding:18px 20px; box-shadow:var(--sh-1); flex-wrap:wrap;}
.ph-av{width:54px; height:54px; border-radius:50%; display:grid; place-items:center; color:#fff; font-weight:800; font-family:var(--f-display); font-size:19px; flex-shrink:0;}
.ph-id{min-width:0; flex:1;}
.ph-id h2{font-size:21px; line-height:1.2;}
.ph-id p{font-size:12.5px; color:var(--ink2); margin-top:2px;}
.ph-addr{color:var(--ink3) !important;}
.portal-head .btn{margin-left:auto;}
.portal-stats{display:grid; grid-template-columns:repeat(5,1fr); gap:10px; margin-top:12px;}
.portal-stats > div{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-sm); padding:12px 13px; display:flex; flex-direction:column; gap:3px;}
.portal-stats .k{font-size:10.5px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink3); font-weight:700;}
.portal-stats .v{font-family:var(--f-display); font-size:19px; font-weight:800; letter-spacing:-.02em;}
.portal-list{display:grid; grid-template-columns:repeat(auto-fill,minmax(268px,1fr)); gap:12px; margin-top:14px;}
.po-card{text-align:left; background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px; display:flex; flex-direction:column; gap:11px; box-shadow:var(--sh-1); transition:.18s cubic-bezier(.2,.8,.3,1); cursor:pointer;}
.po-card:hover{transform:translateY(-3px); border-color:var(--blue); box-shadow:var(--sh-2);}
.poc-top{display:flex; align-items:center; gap:9px;}
.poc-id{font-size:13px; font-weight:700;}
.poc-top .ostat{margin-left:auto;}
.poc-mid{display:flex; gap:6px; align-items:center;}
.poc-th{width:40px; height:40px; border-radius:var(--r-xs); background:var(--surface2); border:1px solid var(--line); display:grid; place-items:center; overflow:hidden; color:var(--blue-d); flex-shrink:0;}
.poc-th img{width:100%; height:100%; object-fit:contain; padding:3px;}
.poc-more{font-size:11.5px; color:var(--ink3); font-family:var(--f-mono);}
.poc-foot{display:flex; align-items:baseline; gap:10px; font-size:11.5px; color:var(--ink3); border-top:1px dashed var(--line); padding-top:9px;}
.poc-total{margin-left:auto; font-family:var(--f-mono); font-size:14px; font-weight:700; color:var(--ink);}
.po-lines{margin:14px 0;}
.po-line{display:flex; align-items:center; gap:11px; padding:9px 0; border-bottom:1px dashed var(--line);}
.po-line:last-child{border-bottom:none;}
.pol-m{width:42px; height:42px; border-radius:var(--r-xs); background:var(--surface2); border:1px solid var(--line); display:grid; place-items:center; overflow:hidden; color:var(--blue-d); flex-shrink:0;}
.pol-m img{width:100%; height:100%; object-fit:contain; padding:3px;}
.pol-n{font-size:13.5px; font-weight:600; display:flex; flex-direction:column; gap:1px; min-width:0;}
.pol-n small{font-size:11.5px; color:var(--ink3); font-weight:500;}
.pol-p{margin-left:auto; font-family:var(--f-mono); font-weight:700; font-size:13.5px;}
.po-sums{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:13px 15px;}

@media (max-width:900px){ .portal-stats{grid-template-columns:repeat(2,1fr);} }
@media (max-width:640px){ .portal-head .btn{margin-left:0; width:100%;} }
.cc-art img{width:100%; height:100%; object-fit:contain; padding:6px;}
.sh-media{width:min(46%,420px); aspect-ratio:16/10; border-radius:var(--r-lg); overflow:hidden; border:1px solid var(--line2); background:var(--surface2); flex-shrink:0; box-shadow:var(--sh-2);}
.sh-media img,.sh-media video,.sh-media iframe{width:100%; height:100%; object-fit:cover; border:none; display:block;}
@media (max-width:900px){ .sh-media{width:100%;} }
/* ── uploads ── */
.dropzone{border:1.5px dashed var(--line3); border-radius:var(--r-sm); padding:18px 14px; display:flex; flex-direction:column; align-items:center; gap:4px; text-align:center; cursor:pointer; transition:.16s; background:var(--surface2); margin-bottom:10px;}
.dropzone:hover,.dropzone.over{border-color:var(--blue); background:var(--blue-tint);}
.dropzone svg{color:var(--blue-d);}
.dropzone b{font-size:12.5px; font-weight:650;}
.dropzone span{font-size:11px; color:var(--ink3);}
.shotgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(88px,1fr)); gap:8px; margin-bottom:8px;}
.shotcell{position:relative; aspect-ratio:1/1; border:1px solid var(--line2); border-radius:var(--r-xs); background:var(--surface2); overflow:hidden;}
.shotcell.primary{border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint);}
.shotcell img{width:100%; height:100%; object-fit:contain; padding:5px;}
.sc-tag{position:absolute; top:4px; left:4px; background:var(--grad); color:#fff; font-size:9px; font-weight:800; padding:2px 6px; border-radius:999px; text-transform:uppercase; letter-spacing:.06em;}
.sc-acts{position:absolute; bottom:4px; right:4px; display:flex; gap:3px; opacity:0; transition:.15s;}
.shotcell:hover .sc-acts{opacity:1;}
.sc-acts .iconbtn{width:24px; height:24px; background:var(--surface); box-shadow:var(--sh-1);}
.catimg{display:flex; gap:10px; align-items:flex-start;}
.ci-prev{width:58px; height:58px; border-radius:var(--r-xs); border:1px solid var(--line2); background:var(--surface2); display:grid; place-items:center; overflow:hidden; flex-shrink:0; color:var(--ink3);}
.ci-prev img{width:100%; height:100%; object-fit:cover;}
.ci-ctl{flex:1; min-width:0; display:flex; flex-direction:column; gap:7px;}

/* ── price builder extras ── */
.landed{display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; background:var(--blue-soft); border:1px solid var(--line); border-radius:var(--r-sm); padding:11px 14px; margin-top:4px;}
.ld-l{font-size:11px; text-transform:uppercase; letter-spacing:.07em; color:var(--blue-d); font-weight:700;}
.ld-v{font-family:var(--f-mono); font-size:19px; font-weight:800; color:var(--ink); margin-left:auto;}
.ld-s{width:100%; font-size:11px; color:var(--ink3);}
.ladder{display:grid; grid-template-columns:repeat(auto-fit,minmax(84px,1fr)); gap:7px;}
.lad{background:var(--surface2); border:1px solid var(--line2); border-radius:var(--r-xs); padding:9px 6px; display:flex; flex-direction:column; gap:2px; align-items:center; transition:.16s; cursor:pointer;}
.lad:hover{border-color:var(--blue);}
.lad.on{background:var(--grad); border-color:transparent; color:#fff;}
.lad-m{font-size:11px; font-weight:700; opacity:.8;}
.lad-p{font-family:var(--f-mono); font-size:13px; font-weight:700;}
.pc-grid{grid-template-columns:repeat(3,1fr);}
/* ── product page ── */
.pdp{margin-top:4px;}
.pdp-head{display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:14px;}
.pdp-brand{margin-left:auto; font-size:12px; color:var(--ink3); font-weight:600;}
.pdp-brand .mono{color:var(--ink2);}
.pdp-title{font-size:clamp(25px,3.6vw,40px); line-height:1.1; letter-spacing:-.03em; margin-bottom:4px;}
.pdp-tag{font-size:15px; color:var(--ink2); margin-bottom:20px; max-width:64ch;}
.pdp-body{margin-top:4px;}
.crumb-mute{color:var(--ink3);}
.crumb-now{color:var(--ink); font-weight:650;}
.pd-thumbs{margin-top:2px;}
.pd-th{width:70px; height:70px;}
@media (max-width:900px){
  .pd-media{aspect-ratio:4/3;}
  .pd-th{width:56px; height:56px;}
  .pdp-brand{margin-left:0; width:100%;}
}
/* ── product page, rebuilt ── */
.pd-hero{align-items:start;}
.pd-gallery{position:sticky; top:96px;}
.pd-info{min-width:0; padding-top:2px;}
.pd-crumbtag{font-size:10.5px; text-transform:uppercase; letter-spacing:.11em; color:var(--blue-d); font-weight:800; margin-bottom:7px;}
.pd-info .pdp-title{font-size:clamp(24px,2.9vw,34px); margin-bottom:6px;}
.pd-info .pdp-tag{font-size:14.5px; margin-bottom:12px;}
.pd-rate{margin-bottom:16px; gap:8px; flex-wrap:wrap;}
.rdot{width:3px; height:3px; border-radius:50%; background:var(--ink4); display:inline-block;}
.pd-price{display:flex; align-items:baseline; gap:11px; flex-wrap:wrap; margin-bottom:5px;}
.pd-now{font-family:var(--f-display); font-size:34px; font-weight:800; letter-spacing:-.03em; line-height:1;}
.pd-was{font-size:16px; color:var(--ink3);}
.pd-save{background:var(--ok-soft); color:var(--ok); font-size:11.5px; font-weight:800; padding:4px 10px; border-radius:999px;}
.pd-promo{display:inline-flex; align-items:center; gap:6px; font-size:12.5px; font-weight:700; color:var(--violet); background:var(--violet-soft); padding:5px 11px; border-radius:999px; margin-bottom:14px;}
.pd-blurb{font-size:14.5px; color:var(--ink2); line-height:1.66; margin:12px 0 18px; max-width:56ch;}
.pd-stock{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px 16px; margin-bottom:16px; box-shadow:var(--sh-1);}
.pd-eta{display:flex; align-items:center; gap:7px; font-size:12.5px; color:var(--ink2); margin-top:11px;}
.pd-eta svg{color:var(--blue);}
.pd-buy{display:flex; gap:9px; align-items:stretch; margin-bottom:18px; flex-wrap:wrap;}
.pd-qty{flex-shrink:0;}
.pd-qty button{width:38px;} .pd-qty span{min-width:34px; font-size:14px;}
.pd-cta{flex:1; min-width:170px;}
.btn.icon-only{width:52px; padding:0; flex-shrink:0; justify-content:center;}
.pd-trust{display:grid; grid-template-columns:repeat(3,1fr); gap:9px; margin-bottom:16px;}
.pd-trust > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:11px 12px; display:flex; flex-direction:column; gap:3px;}
.pd-trust .tk{width:28px; height:28px; border-radius:9px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; margin-bottom:3px;}
.pd-trust b{font-size:12.5px; line-height:1.3;}
.pd-trust small{font-size:11px; color:var(--ink3); line-height:1.4;}
.pd-tags{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:16px;}
.pd-console{display:flex; align-items:center; gap:9px; background:var(--blue-soft); border:1px dashed var(--blue-soft2); border-radius:var(--r); padding:12px 14px; font-size:12.5px; color:var(--blue-d); font-weight:700;}
.pd-console .btn{margin-left:auto;}
.pd-detail{display:grid; grid-template-columns:minmax(0,1.15fr) minmax(0,1fr); gap:14px; margin:26px 0 24px;}
.specgrid{display:grid; grid-template-columns:repeat(2,1fr); gap:1px 18px;}
.specgrid > div{display:flex; align-items:baseline; gap:10px; padding:9px 0; border-bottom:1px dashed var(--line);}
.specgrid .sk{font-size:12px; color:var(--ink3); flex-shrink:0; min-width:104px;}
.specgrid .sv{font-size:13px; font-weight:650; margin-left:auto; text-align:right;}
.dlist{display:flex; flex-direction:column; gap:13px;}
.dlist > div{display:flex; gap:11px;}
.dlist .di{width:30px; height:30px; border-radius:9px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.dlist b{font-size:13px; display:block; margin-bottom:2px;}
.dlist p{font-size:12px; color:var(--ink3); line-height:1.5;}
@media (max-width:1000px){ .pd-detail{grid-template-columns:1fr;} .specgrid{grid-template-columns:1fr;} }
@media (max-width:900px){
  .pd-gallery{position:static;}
  .pd-trust{grid-template-columns:1fr;}
  .pd-cta{min-width:100%;}
}
/* ══ MOTION ══
   Everything here is gated behind .anim, which only lands when JS is running
   and the visitor has not asked for reduced motion. Without it the page is
   simply static, never invisible. */
@keyframes txFadeUp{from{opacity:0; transform:translate3d(0,18px,0);} to{opacity:1; transform:none;}}
@keyframes txFadeIn{from{opacity:0;} to{opacity:1;}}
@keyframes txPop{0%{transform:scale(.5); opacity:0;} 60%{transform:scale(1.18);} 100%{transform:scale(1); opacity:1;}}
@keyframes txFrame{from{opacity:0; transform:scale(.97);} to{opacity:1; transform:none;}}
@keyframes txSheen{from{transform:translateX(-120%);} to{transform:translateX(220%);}}
@keyframes txFloat{0%,100%{transform:translateY(0);} 50%{transform:translateY(-7px);}}

.tx.anim .reveal{opacity:0; transform:translate3d(0,20px,0); transition:opacity .55s cubic-bezier(.2,.8,.3,1), transform .55s cubic-bezier(.2,.8,.3,1);}
.tx.anim .reveal.in{opacity:1; transform:none;}
.tx.anim .grid > *{animation:txFadeUp .5s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .grid > *:nth-child(1){animation-delay:.02s} .tx.anim .grid > *:nth-child(2){animation-delay:.06s}
.tx.anim .grid > *:nth-child(3){animation-delay:.1s}  .tx.anim .grid > *:nth-child(4){animation-delay:.14s}
.tx.anim .grid > *:nth-child(5){animation-delay:.18s} .tx.anim .grid > *:nth-child(6){animation-delay:.22s}
.tx.anim .grid > *:nth-child(n+7){animation-delay:.26s}
.tx.anim .catrow > *{animation:txFadeUp .5s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .catrow > *:nth-child(2){animation-delay:.07s} .tx.anim .catrow > *:nth-child(3){animation-delay:.14s}
.tx.anim .catrow > *:nth-child(4){animation-delay:.21s}
.tx.anim .covers > *{animation:txFadeUp .45s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .covers > *:nth-child(2){animation-delay:.05s} .tx.anim .covers > *:nth-child(3){animation-delay:.1s}
.tx.anim .covers > *:nth-child(4){animation-delay:.15s} .tx.anim .covers > *:nth-child(5){animation-delay:.2s}
.tx.anim .pd-info > *{animation:txFadeUp .5s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .pd-info > *:nth-child(2){animation-delay:.04s} .tx.anim .pd-info > *:nth-child(3){animation-delay:.08s}
.tx.anim .pd-info > *:nth-child(4){animation-delay:.12s} .tx.anim .pd-info > *:nth-child(5){animation-delay:.16s}
.tx.anim .pd-info > *:nth-child(n+6){animation-delay:.2s}
.tx.anim .pd-gallery{animation:txFadeIn .5s ease both;}
.tx.anim .pd-media .shot,.tx.anim .pd-media .pd-vid{animation:txFrame .38s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .modal,.tx.anim .drawer{animation:txFadeUp .3s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .badge.pop{animation:txPop .42s cubic-bezier(.3,1.4,.5,1) both;}
.tx.anim .podium{animation:txFloat 7s ease-in-out infinite;}

/* nav settles into a tighter bar once you scroll past the hero */
.nav{transition:padding .28s cubic-bezier(.2,.8,.3,1), box-shadow .28s ease, background .28s ease;}
/* compacting by padding reflowed the page on every scroll, which is what made
   the whole thing feel shaky. Shadow and background only: no layout, no jank. */
.nav.scrolled{box-shadow:var(--sh-2); background:var(--surface);}
.nav .logo-mk,.nav .logo-tx{transition:transform .28s cubic-bezier(.2,.8,.3,1);}
.nav.scrolled .logo-mk{transform:scale(.9);}

/* a light sweep across the primary button on hover, once */
.btn-pri{position:relative; overflow:hidden;}
.btn-pri::after{content:""; position:absolute; top:0; bottom:0; width:38%; pointer-events:none;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.34),transparent); transform:translateX(-120%);}
.tx.anim .btn-pri:hover::after{animation:txSheen .7s ease;}
.btn:active{transform:translateY(1px) scale(.99);}
.card-media .shot{will-change:transform;}
.pd-th{transition:transform .16s cubic-bezier(.2,.8,.3,1), border-color .16s, box-shadow .16s;}
.pd-th:hover{transform:translateY(-2px);}
.po-card,.themecard,.catcard,.cover{will-change:transform;}

@media (prefers-reduced-motion:reduce){
  .tx.anim .reveal,.tx.anim .grid > *,.tx.anim .catrow > *,.tx.anim .covers > *,
  .tx.anim .pd-info > *,.tx.anim .pd-gallery,.tx.anim .pd-media .shot,.tx.anim .pd-media .pd-vid,
  .tx.anim .modal,.tx.anim .drawer,.tx.anim .badge.pop,.tx.anim .podium{animation:none !important; opacity:1 !important; transform:none !important; transition:none !important;}
  .nav,.btn,.pd-th{transition:none !important;}
}
/* ── delivery partners ── */
.pnrgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(340px,1fr)); gap:12px;}
.pnr{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:15px 16px; box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:12px; transition:.18s cubic-bezier(.2,.8,.3,1);}
.pnr:hover{border-color:var(--blue); box-shadow:var(--sh-2);}
.pnr.off{opacity:.62;}
.pnr-top{display:flex; align-items:flex-start; gap:11px;}
.pnr-code{width:42px; height:42px; border-radius:var(--r-xs); background:var(--grad); color:#fff; display:grid; place-items:center; font-family:var(--f-mono); font-size:12px; font-weight:800; flex-shrink:0; letter-spacing:.04em;}
.pnr-id{min-width:0; flex:1;}
.pnr-n{font-family:var(--f-display); font-weight:700; font-size:15px; display:flex; align-items:center; gap:7px; flex-wrap:wrap;}
.pnr-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.pnr-acts{display:flex; gap:6px; align-items:center; flex-shrink:0;}
.pnr-grid{display:grid; grid-template-columns:repeat(2,1fr); gap:8px;}
.pnr-grid > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:8px 10px; display:flex; flex-direction:column; gap:2px;}
.pnr-grid .k{font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.05em;}
.pnr-grid .v{font-family:var(--f-mono); font-size:13.5px; font-weight:700;}
.pnr-grid .v.ok{color:var(--ok);} .pnr-grid .v.bad{color:var(--bad);}
.pnr-terms{display:flex; gap:7px; flex-wrap:wrap;}
.pnr-terms span{display:inline-flex; align-items:center; gap:5px; font-size:11px; color:var(--ink2); background:var(--surface2); border:1px solid var(--line); border-radius:999px; padding:4px 9px;}
.pnr-terms svg{color:var(--blue);}
.pnr-zones{display:flex; gap:6px; flex-wrap:wrap; align-items:center;}
.pz-l{font-size:10.5px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink3); font-weight:700; margin-right:2px;}
.pz{font-size:11px; padding:3px 9px; border-radius:999px; border:1px dashed var(--line2); color:var(--ink4);}
.pz.on{background:var(--blue-soft); border:1px solid transparent; color:var(--blue-d); font-weight:650;}
.pnr-foot{display:flex; align-items:center; gap:10px; font-size:11.5px; color:var(--ink3); border-top:1px dashed var(--line); padding-top:11px; flex-wrap:wrap;}
.pnr-foot .btn{margin-left:auto;}
.pnr-note{font-size:11.5px; color:var(--ink3); font-style:italic; line-height:1.5;}
.cvsub{font-size:15px; color:var(--ink3); font-weight:600;}
.fsec{font-size:10.5px; text-transform:uppercase; letter-spacing:.09em; color:var(--ink3); font-weight:800; margin:18px 0 10px; padding-bottom:6px; border-bottom:1px solid var(--line);}
@media (max-width:520px){ .pnr-grid{grid-template-columns:1fr;} }
/* ══ 3D ══
   A shallow perspective on the pieces a hand actually reaches for. The tilt
   values arrive as custom properties from one delegated pointer listener, so
   nothing here forces a React render. */
.tx.anim .tilt{transform-style:preserve-3d; transition:transform .34s cubic-bezier(.2,.8,.3,1), box-shadow .28s ease, border-color .2s ease;}
.tx.anim .card.tilt:hover{
  transform:perspective(1000px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg)) translate3d(0,-6px,26px);
  box-shadow:0 26px 54px rgba(10,16,32,.16), var(--sh-blue);
}
.tx.anim .card.tilt .card-media{transform:translateZ(0); transition:transform .34s cubic-bezier(.2,.8,.3,1);}
.tx.anim .card.tilt:hover .card-media{transform:translateZ(30px);}
.tx.anim .card.tilt:hover .card-media .shot{transform:scale(1.07) translateZ(18px);}
.tx.anim .card.tilt:hover .card-body{transform:translateZ(14px);}
.tx.anim .card.tilt .card-body{transition:transform .34s cubic-bezier(.2,.8,.3,1);}
.tx.anim .card.tilt .badge,.tx.anim .card.tilt .card-acts{transition:transform .34s cubic-bezier(.2,.8,.3,1);}
.tx.anim .card.tilt:hover .badge,.tx.anim .card.tilt:hover .card-acts{transform:translateZ(42px);}

.tx.anim .catcard.tilt:hover{
  transform:perspective(900px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg)) translate3d(0,-4px,18px);
  box-shadow:0 22px 44px rgba(10,16,32,.14);
}
.tx.anim .catcard.tilt .cc-art{transition:transform .34s cubic-bezier(.2,.8,.3,1);}
.tx.anim .catcard.tilt:hover .cc-art{transform:translateZ(30px) scale(1.06);}

.tx.anim .pd-media.tilt{transform:perspective(1200px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));}
.tx.anim .pd-media.tilt .shot{transition:transform .34s cubic-bezier(.2,.8,.3,1);}
.tx.anim .pd-media.tilt:hover .shot{transform:translateZ(46px) scale(1.04);}
.tx.anim .pd-media.tilt .tick{transform:translateZ(24px);}

/* entrances gain a little depth rather than sliding flat */
@keyframes txRise3d{from{opacity:0; transform:perspective(900px) rotateX(7deg) translate3d(0,26px,-70px);} to{opacity:1; transform:none;}}
.tx.anim .grid > *{animation-name:txRise3d;}
.tx.anim .catrow > *{animation-name:txRise3d;}
.tx.anim .pnrgrid > *{animation:txRise3d .5s cubic-bezier(.2,.8,.3,1) both;}
.tx.anim .reveal{transform:perspective(1000px) rotateX(4deg) translate3d(0,22px,-40px);}
.tx.anim .reveal.in{transform:none;}
.tx.anim .modal{animation-name:txRise3d;}

/* the hero stand keeps a slow orbit so the page is never completely still */
@keyframes txOrbit{0%,100%{transform:perspective(1000px) rotateY(-7deg) translateY(0);} 50%{transform:perspective(1000px) rotateY(7deg) translateY(-9px);}}
.tx.anim .podium{animation:txOrbit 11s ease-in-out infinite; transform-style:preserve-3d;}

@media (hover:none){ .tx.anim .tilt{transform:none !important;} }
@media (prefers-reduced-motion:reduce){
  .tx.anim .tilt,.tx.anim .card.tilt:hover,.tx.anim .catcard.tilt:hover,.tx.anim .pd-media.tilt,
  .tx.anim .card.tilt:hover .card-media,.tx.anim .card.tilt:hover .card-body,
  .tx.anim .card.tilt:hover .badge,.tx.anim .card.tilt:hover .card-acts,
  .tx.anim .catcard.tilt:hover .cc-art,.tx.anim .pd-media.tilt:hover .shot,
  .tx.anim .pnrgrid > *,.tx.anim .podium{transform:none !important; animation:none !important; transition:none !important;}
}
/* ── receivables / payables ── */
.agebar{display:flex; height:18px; border-radius:999px; overflow:hidden; background:var(--surface3); margin-bottom:14px;}
.ageseg{transition:width .35s cubic-bezier(.2,.8,.3,1);}
.ageseg.s0{background:var(--ok);} .ageseg.s1{background:var(--blue);}
.ageseg.s2{background:var(--warn);} .ageseg.s3{background:var(--bad);}
.agekey{display:flex; flex-direction:column; gap:8px;}
.agekey > div{display:flex; align-items:center; gap:9px; font-size:12.5px; color:var(--ink2);}
.agekey .dot{width:10px; height:10px; border-radius:3px; flex-shrink:0;}
.agekey .dot.s0{background:var(--ok);} .agekey .dot.s1{background:var(--blue);}
.agekey .dot.s2{background:var(--warn);} .agekey .dot.s3{background:var(--bad);}
.agekey .ak-l{flex:1; min-width:0;}
.agekey .ak-c{font-size:11px; color:var(--ink4); font-family:var(--f-mono);}
.agekey b{font-family:var(--f-mono); font-size:13px; color:var(--ink); min-width:88px; text-align:right;}
.apr{border:1px solid var(--line); border-radius:var(--r-sm); padding:12px 13px; margin-bottom:10px; background:var(--surface2);}
.apr:last-child{margin-bottom:0;}
.apr-t{display:flex; align-items:baseline; gap:10px; margin-bottom:8px;}
.apr-n{font-weight:700; font-size:13.5px;}
.apr-v{margin-left:auto; font-family:var(--f-mono); font-weight:700; font-size:14px;}
.apr-bar{height:7px; border-radius:999px; background:var(--surface3); overflow:hidden; margin-bottom:7px;}
.apr-bar span{display:block; height:100%; background:var(--grad); border-radius:999px; transition:width .35s cubic-bezier(.2,.8,.3,1);}
.apr-s{display:flex; gap:10px; flex-wrap:wrap; font-size:11.5px; color:var(--ink3); margin-bottom:10px;}
.apr-od{color:var(--bad); font-weight:700; margin-left:auto;}
.btn.btn-block{width:100%; justify-content:center;}
.stl{display:flex; gap:11px; align-items:flex-start; padding:10px 0; border-bottom:1px dashed var(--line);}
.stl:last-child{border-bottom:none;}
.stl-d{width:26px; height:26px; border-radius:8px; display:grid; place-items:center; flex-shrink:0;}
.stl-d.in{background:var(--ok-soft); color:var(--ok);}
.stl-d.out{background:var(--violet-soft); color:var(--violet);}
.stl-b{flex:1; min-width:0;}
.stl-t{font-size:13px; font-weight:650;}
.stl-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.stl-note{font-size:11.5px; color:var(--ink2); font-style:italic; margin-top:3px;}
.stl-id{font-size:10.5px; color:var(--ink4); flex-shrink:0;}
.settle-top{display:grid; grid-template-columns:repeat(3,1fr); gap:9px; margin-bottom:16px;}
.settle-top > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:10px 11px; display:flex; flex-direction:column; gap:3px;}
.settle-top .k{font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3); font-weight:700;}
.settle-top .v{font-family:var(--f-mono); font-size:15px; font-weight:800;}
.settle-top .v.ok{color:var(--ok);} .settle-top .v.warn{color:var(--warn);}
.quickamt{display:flex; gap:6px; flex-wrap:wrap; margin-top:8px;}
.pill.violet{background:var(--violet-soft); color:var(--violet);}
@media (max-width:640px){ .settle-top{grid-template-columns:1fr;} }
/* ══ LANDING PAGE SCROLL ══
   Everything reads from --sy (scroll offset) and --sp (0 to 1 across the hero),
   both written by one rAF-throttled listener. No layer costs an extra handler. */
.tx.anim .hero-copy,.tx.anim .hero-stage,.tx.anim .parx-trust{will-change:transform; backface-visibility:hidden;}
/* the copy sinks, the stage rises. Opposing directions is what reads as depth. */
.tx.anim .hero.parx .hero-copy{
  transform:translate3d(0, calc(var(--sp,0) * 38px), 0);
  opacity:calc(1 - var(--sp,0) * 0.65);
}
.tx.anim .hero.parx .hero-stage{transform:translate3d(0, calc(var(--sp,0) * -46px), 0);}
.tx.anim .parx-trust{
  transform:translate3d(0, calc(var(--sp,0) * -18px), 0);
  opacity:calc(1 - var(--sp,0) * 0.3);
}
.tx.anim .parx-trust .trust-cell{transition:transform .3s cubic-bezier(.2,.8,.3,1);}
.tx.anim .parx-trust .trust-cell:hover{transform:translateY(-4px);}
/* the wash drifts slower than the page so the background sits on its own plane */
.tx.anim::before{transform:translate3d(0, calc(var(--sy,0px) * -0.045), 0); will-change:transform; backface-visibility:hidden;}

/* section headings sweep their rules open as they arrive */
.tx.anim .reveal .dashes i{transform:scaleX(0); transform-origin:left; transition:transform .5s cubic-bezier(.2,.8,.3,1) .12s;}
.tx.anim .reveal.in .dashes i{transform:scaleX(1);}
.tx.anim .reveal .sec-title h2{clip-path:inset(0 100% 0 0); transition:clip-path .6s cubic-bezier(.2,.8,.3,1) .1s;}
.tx.anim .reveal.in .sec-title h2{clip-path:inset(0 0 0 0);}

/* the navy bands rise into place rather than appearing */
@keyframes txBand{from{opacity:0; transform:perspective(1000px) rotateX(6deg) translate3d(0,34px,-60px);} to{opacity:1; transform:none;}}
.tx.anim .reveal.in .band,.tx.anim .reveal.in .dealband{animation:txBand .6s cubic-bezier(.2,.8,.3,1) both;}

/* a thin progress rail across the top so scrolling has a readout */
.scrollrail{position:fixed; top:0; left:0; right:0; height:3px; z-index:90; pointer-events:none; background:transparent;}
.scrollrail span{display:block; height:100%; width:100%; background:var(--grad); transform-origin:0 50%; transform:scaleX(var(--sdone,0));}
@media (prefers-reduced-motion:reduce){
  .tx.anim .hero-copy,.tx.anim .hero-stage,.tx.anim .parx-trust,.tx.anim::before{transform:none !important; opacity:1 !important;}
  .tx.anim .reveal .sec-title h2{clip-path:none !important;}
  .tx.anim .reveal .dashes i{transform:none !important;}
  .tx.anim .reveal.in .band,.tx.anim .reveal.in .dealband{animation:none !important;}
  .scrollrail{display:none;}
}
/* ── order routing, expenses, balance sheet, HR ── */
.orouting{display:flex; gap:14px; flex-wrap:wrap; align-items:flex-end; background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:11px 13px; margin:10px 0;}
.orouting label{display:flex; flex-direction:column; gap:4px; font-size:10.5px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink3); font-weight:700;}
.orouting select{min-width:190px;}
.orouting-n{font-size:11.5px; color:var(--ink3); margin-left:auto; align-self:center;}
.rowacts{display:flex; gap:5px;}
.checkrow{display:flex; align-items:flex-start; gap:11px; background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:11px 13px; cursor:pointer;}
.checkrow b{display:block; font-size:13px;}
.checkrow small{display:block; font-size:11.5px; color:var(--ink3); margin-top:2px;}
.grossbox{background:var(--blue-soft); border:1px solid var(--line); border-radius:var(--r-xs); padding:9px 12px; font-family:var(--f-mono); font-size:16px; font-weight:800; color:var(--blue-d);}
.bsrow{margin-bottom:14px;}
.bs-t{display:flex; justify-content:space-between; font-size:13px; font-weight:600; margin-bottom:5px;}
.bs-t .mono{font-weight:700;} .bs-t .mono.neg{color:var(--bad);}
.bs-bar{height:8px; border-radius:999px; background:var(--surface3); overflow:hidden;}
.bs-bar span{display:block; height:100%; background:var(--grad); border-radius:999px; transition:width .4s cubic-bezier(.2,.8,.3,1);}
.bs-bar.liab span{background:linear-gradient(90deg,var(--warn),var(--bad));}
.bs-n{font-size:11px; color:var(--ink3); margin-top:4px;}
.bstotal{display:flex; justify-content:space-between; border-top:2px solid var(--ink); padding-top:11px; margin-top:4px; font-family:var(--f-display); font-weight:800; font-size:15px;}
.empgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(320px,1fr)); gap:12px;}
.empc{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px 15px; box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:11px; transition:.18s cubic-bezier(.2,.8,.3,1);}
.empc:hover{border-color:var(--blue); box-shadow:var(--sh-2);}
.empc.off{opacity:.6;}
.empc-t{display:flex; align-items:flex-start; gap:11px;}
.empc-av{width:40px; height:40px; border-radius:50%; display:grid; place-items:center; color:#fff; font-weight:800; font-size:14px; font-family:var(--f-display); flex-shrink:0;}
.empc-id{min-width:0; flex:1;}
.empc-n{font-family:var(--f-display); font-weight:700; font-size:14.5px; display:flex; align-items:center; gap:7px; flex-wrap:wrap;}
.empc-r{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.empc-g{display:grid; grid-template-columns:repeat(4,1fr); gap:7px;}
.empc-g > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:7px 8px; display:flex; flex-direction:column; gap:2px; min-width:0;}
.empc-g .k{font-size:9.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3);}
.empc-g .v{font-family:var(--f-mono); font-size:12px; font-weight:700; overflow:hidden; text-overflow:ellipsis;}
.empc-f{display:flex; justify-content:space-between; font-size:11px; color:var(--ink3); border-top:1px dashed var(--line); padding-top:9px;}
.dtable.payroll th,.dtable.payroll td{padding:8px 9px; font-size:12px;}
.slipcols{display:grid; grid-template-columns:1fr 1fr; gap:0; margin:4px 34px 0; border:1px solid #EAECF0; border-radius:8px; overflow:hidden;}
.slipcols > div:first-child{border-right:1px solid #EAECF0;}
.slip-h{background:var(--iv-tint); padding:9px 14px; font-size:10.5px; text-transform:uppercase; letter-spacing:.09em; font-weight:800; color:#475467;}
.slip-r{display:flex; justify-content:space-between; gap:12px; padding:8px 14px; font-size:12.5px; color:#344054; border-bottom:1px solid #F2F4F7;}
.slip-r.total{background:#FAFBFD; font-weight:800; color:#101828; border-bottom:none;}
@media (max-width:760px){ .slipcols{grid-template-columns:1fr;} .slipcols > div:first-child{border-right:none; border-bottom:1px solid #EAECF0;} .empc-g{grid-template-columns:repeat(2,1fr);} .orouting-n{margin-left:0;} }
.potot{display:grid; grid-template-columns:repeat(3,1fr); gap:9px; margin-top:14px;}
.potot > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:10px 12px; display:flex; flex-direction:column; gap:3px;}
.potot .k{font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3); font-weight:700;}
.potot .v{font-family:var(--f-mono); font-size:16px; font-weight:800;}
.potot .v.ok{color:var(--ok);} .potot .v.warn{color:var(--warn);}
@media (max-width:640px){ .potot{grid-template-columns:1fr;} }
/* ══ CARD IMAGE CYCLING ══
   Hovering a product walks its angles. Pure CSS: the frames are stacked and
   cross-faded, so a grid of twelve cards costs zero React renders. */
.shots{position:absolute; inset:0; z-index:2; display:block;}
.shots .shot{position:absolute; inset:0; width:100%; height:100%; padding:14px; object-fit:contain; opacity:0;
  transition:opacity .45s ease, transform .45s cubic-bezier(.2,.8,.3,1);
  filter:drop-shadow(0 12px 18px rgba(29,78,216,.18));}
.shots .shot.s1{opacity:1;}
.shotdots{position:absolute; left:0; right:0; bottom:9px; display:flex; justify-content:center; gap:5px; z-index:4;
  opacity:0; transition:opacity .25s ease; pointer-events:none;}
.shotdots i{width:5px; height:5px; border-radius:50%; background:var(--ink4); transition:background .3s ease, transform .3s ease;}
.card:hover .shotdots{opacity:1;}

@keyframes cyc2a{0%,44%{opacity:1} 50%,94%{opacity:0} 100%{opacity:1}}
@keyframes cyc2b{0%,44%{opacity:0} 50%,94%{opacity:1} 100%{opacity:0}}
@keyframes cyc3a{0%,28%{opacity:1} 34%,94%{opacity:0} 100%{opacity:1}}
@keyframes cyc3b{0%,28%{opacity:0} 34%,61%{opacity:1} 67%,100%{opacity:0}}
@keyframes cyc3c{0%,61%{opacity:0} 67%,94%{opacity:1} 100%{opacity:0}}
@keyframes dot2a{0%,44%{background:var(--blue); transform:scale(1.35)} 50%,100%{background:var(--ink4); transform:none}}
@keyframes dot2b{0%,44%{background:var(--ink4); transform:none} 50%,94%{background:var(--blue); transform:scale(1.35)} 100%{background:var(--ink4); transform:none}}
@keyframes dot3a{0%,28%{background:var(--blue); transform:scale(1.35)} 34%,100%{background:var(--ink4); transform:none}}
@keyframes dot3b{0%,28%{background:var(--ink4); transform:none} 34%,61%{background:var(--blue); transform:scale(1.35)} 67%,100%{background:var(--ink4); transform:none}}
@keyframes dot3c{0%,61%{background:var(--ink4); transform:none} 67%,94%{background:var(--blue); transform:scale(1.35)} 100%{background:var(--ink4); transform:none}}

.tx.anim .card:hover .shots.f2 .shot.s1{animation:cyc2a 3.4s linear infinite;}
.tx.anim .card:hover .shots.f2 .shot.s2{animation:cyc2b 3.4s linear infinite;}
.tx.anim .card:hover .shots.f3 .shot.s1{animation:cyc3a 4.8s linear infinite;}
.tx.anim .card:hover .shots.f3 .shot.s2{animation:cyc3b 4.8s linear infinite;}
.tx.anim .card:hover .shots.f3 .shot.s3{animation:cyc3c 4.8s linear infinite;}
.tx.anim .card:hover .shots.f3 .shotdots .d1{animation:dot3a 4.8s linear infinite;}
.tx.anim .card:hover .shots.f3 .shotdots .d2{animation:dot3b 4.8s linear infinite;}
.tx.anim .card:hover .shots.f3 .shotdots .d3{animation:dot3c 4.8s linear infinite;}
.tx.anim .card:hover .shots.f2 .shotdots .d1{animation:dot2a 3.4s linear infinite;}
.tx.anim .card:hover .shots.f2 .shotdots .d2{animation:dot2b 3.4s linear infinite;}
.tx.anim .card:hover .shots .shot{transform:scale(1.06);}
@media (hover:none){ .shots .shot{animation:none !important; transform:none !important;} .shotdots{display:none;} }
@media (prefers-reduced-motion:reduce){
  .tx.anim .card:hover .shots .shot,.tx.anim .card:hover .shotdots i{animation:none !important; transform:none !important;}
}
/* ══ CARD POLISH ══
   White product shots were blending into a white card, and the buy action was
   competing with the image for attention. A soft floor, a lit rim on hover,
   and the action only surfaces when the card is engaged. */
.card-media{background:
  radial-gradient(120% 80% at 50% 118%, rgba(10,16,32,.07), transparent 62%),
  var(--grad-soft);}
.card{position:relative; isolation:isolate;}
.card::after{content:""; position:absolute; inset:0; border-radius:inherit; pointer-events:none; z-index:3;
  padding:1px; background:var(--grad); opacity:0; transition:opacity .28s ease;
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite:xor; mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite:exclude;}
.card:hover::after{opacity:.55;}
.card-media::after{content:""; position:absolute; inset:0; pointer-events:none; z-index:3;
  background:linear-gradient(180deg, transparent 62%, rgba(10,16,32,.05));}
.card-acts{opacity:0; transform:translateY(-4px); transition:opacity .24s ease, transform .24s cubic-bezier(.2,.8,.3,1);}
.card:hover .card-acts,.card:focus-within .card-acts{opacity:1; transform:none;}
.card .add-btn{transition:transform .22s cubic-bezier(.2,.8,.3,1), box-shadow .22s ease;}
.card:hover .add-btn{transform:scale(1.06); box-shadow:var(--sh-blue);}
.card-body h3{transition:color .2s ease;}
.card:hover .card-body h3{color:var(--blue-d);}

/* section rhythm: headings breathe, the rule under them draws the eye across */
.sec-head{align-items:flex-end; margin-bottom:20px;}
.sec-title h2{line-height:1.12;}
.dashes i{height:3px; border-radius:2px;}
.section.tight{padding-top:34px; padding-bottom:34px;}

/* one smooth-scroll pass so anchor jumps do not snap */
html{scroll-behavior:smooth;}
@media (prefers-reduced-motion:reduce){ html{scroll-behavior:auto;} .card::after,.card-acts{transition:none !important;} }
/* ── loans and payroll recovery ── */
.loangrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(330px,1fr)); gap:12px;}
.loanc{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px 15px; box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:11px; transition:.18s cubic-bezier(.2,.8,.3,1);}
.loanc:hover{border-color:var(--blue); box-shadow:var(--sh-2);}
.loanc.off{opacity:.62;}
.loanc-t{display:flex; align-items:flex-start; gap:11px;}
.loanc-bar{height:8px; border-radius:999px; background:var(--surface3); overflow:hidden;}
.loanc-bar span{display:block; height:100%; background:var(--grad); border-radius:999px; transition:width .4s cubic-bezier(.2,.8,.3,1);}
.loanc-s{display:flex; justify-content:space-between; font-size:11.5px; color:var(--ink3);}
.loanc-out{font-family:var(--f-mono); font-weight:700; color:var(--ink);}
.loanrow td{background:var(--surface2); border-top:none; padding-top:0 !important;}
.loanline{display:flex; flex-direction:column; gap:7px; padding:2px 0 8px;}
.ll{display:flex; align-items:center; gap:10px; flex-wrap:wrap; background:var(--surface); border:1px solid var(--line); border-radius:var(--r-xs); padding:7px 10px;}
.ll.skip{opacity:.55;}
.ll-n{display:flex; flex-direction:column; gap:1px; font-size:12px; font-weight:650; min-width:180px;}
.ll-n small{font-size:10.5px; color:var(--ink3); font-weight:500;}
.ll-mult{display:inline-flex; border:1px solid var(--line2); border-radius:999px; overflow:hidden;}
.ll-mult button{border:none; background:none; padding:4px 10px; font-size:11px; font-weight:700; color:var(--ink2);}
.ll-mult button.on{background:var(--grad); color:#fff;}
.ll .btn{margin-left:auto;}
@media (max-width:640px){ .ll-n{min-width:100%;} .ll .btn{margin-left:0;} }
/* ══ HERO CAROUSEL ══ */
.hero-dots button{position:relative; overflow:hidden;}
.hd-fill{position:absolute; inset:0; border-radius:inherit; background:var(--blue); transform-origin:left; transform:scaleX(0);}
.hero-dots button.on .hd-fill{animation:hdrun 6.5s linear forwards;}
@keyframes hdrun{from{transform:scaleX(0)} to{transform:scaleX(1)}}
.hero-arrow{position:absolute; top:50%; transform:translateY(-50%); z-index:6; width:40px; height:40px; border-radius:50%;
  background:var(--surface); border:1px solid var(--line2); color:var(--ink2); display:grid; place-items:center;
  box-shadow:var(--sh-2); opacity:0; transition:opacity .24s ease, transform .24s cubic-bezier(.2,.8,.3,1), color .2s;}
.hero-arrow.prev{left:14px;} .hero-arrow.next{right:14px;}
.hero:hover .hero-arrow{opacity:1;}
.hero-arrow:hover{color:var(--blue-d); border-color:var(--blue); transform:translateY(-50%) scale(1.08);}
.hero-arrow:focus-visible{opacity:1;}

/* ══ PRODUCT ZOOM ══ */
.pd-media .shot{transition:transform .22s cubic-bezier(.2,.8,.3,1);}
.zoombar{position:absolute; bottom:12px; left:50%; transform:translateX(-50%); z-index:6; display:flex; align-items:center; gap:3px;
  background:rgba(255,255,255,.9); backdrop-filter:blur(8px); border:1px solid var(--line2); border-radius:999px;
  padding:4px 5px; box-shadow:var(--sh-2); opacity:0; transition:opacity .24s ease;}
.pd-media:hover .zoombar,.zoombar:focus-within{opacity:1;}
.zoombar button{width:28px; height:28px; border-radius:50%; border:none; background:none; color:var(--ink2); display:grid; place-items:center; transition:.15s;}
.zoombar button:hover:not(:disabled){background:var(--blue-soft); color:var(--blue-d);}
.zoombar button:disabled{opacity:.35;}
.zoombar .zl{font-size:11.5px; font-weight:700; min-width:40px; text-align:center; color:var(--ink2);}
.zoombar .zr{border-left:1px solid var(--line); border-radius:0 999px 999px 0;}
.zoomhint{position:absolute; top:12px; left:50%; transform:translateX(-50%); z-index:6; font-size:10.5px; font-weight:600;
  background:rgba(255,255,255,.9); border:1px solid var(--line); border-radius:999px; padding:3px 10px; color:var(--ink3);}

/* ══ LIGHTBOX ══ */
.lbx{position:fixed; inset:0; z-index:200; background:rgba(8,12,22,.94); display:flex; flex-direction:column;
  animation:txFadeIn .2s ease both;}
.lbx-top{display:flex; align-items:center; gap:16px; padding:14px 18px; flex-wrap:wrap;}
.lbx-t{color:#fff; font-family:var(--f-display); font-weight:700; font-size:15px; display:flex; flex-direction:column;}
.lbx-t small{font-size:11.5px; opacity:.6; font-weight:500; font-family:var(--f-body);}
.lbx-z{margin-left:auto; display:flex; align-items:center; gap:4px; background:rgba(255,255,255,.1); border-radius:999px; padding:4px 6px;}
.lbx-z button{width:30px; height:30px; border-radius:50%; border:none; background:none; color:#fff; display:grid; place-items:center;}
.lbx-z button:hover:not(:disabled){background:rgba(255,255,255,.16);}
.lbx-z button:disabled{opacity:.3;}
.lbx-z .mono{color:#fff; font-size:12px; min-width:44px; text-align:center;}
.lbx-x{width:36px; height:36px; border-radius:50%; border:1px solid rgba(255,255,255,.2); background:rgba(255,255,255,.08); color:#fff; display:grid; place-items:center;}
.lbx-x:hover{background:rgba(255,255,255,.18);}
.lbx-stage{flex:1; position:relative; display:grid; place-items:center; overflow:hidden; padding:0 16px;}
.lbx-stage img{max-width:min(1000px,92vw); max-height:70vh; object-fit:contain; transition:transform .2s cubic-bezier(.2,.8,.3,1); user-select:none;}
.lbx-arrow{position:absolute; top:50%; transform:translateY(-50%); width:46px; height:46px; border-radius:50%;
  border:1px solid rgba(255,255,255,.2); background:rgba(255,255,255,.09); color:#fff; display:grid; place-items:center; z-index:3;}
.lbx-arrow:hover{background:rgba(255,255,255,.2);}
.lbx-arrow.prev{left:18px;} .lbx-arrow.next{right:18px;}
.lbx-thumbs{display:flex; gap:8px; justify-content:center; padding:12px 16px 4px; flex-wrap:wrap;}
.lbx-thumbs button{width:62px; height:62px; border-radius:12px; overflow:hidden; border:2px solid transparent; background:rgba(255,255,255,.08); padding:0;}
.lbx-thumbs button.on{border-color:var(--cyan);}
.lbx-thumbs img{width:100%; height:100%; object-fit:contain; padding:4px;}
.lbx-hint{text-align:center; color:rgba(255,255,255,.5); font-size:11.5px; padding:8px 16px 18px;}
@media (max-width:640px){
  .lbx-z{margin-left:0; order:3; width:100%; justify-content:center;}
  .lbx-stage img{max-height:56vh;}
  .hero-arrow{opacity:1; width:34px; height:34px;}
}
@media (prefers-reduced-motion:reduce){
  .hero-dots button.on .hd-fill{animation:none; transform:scaleX(1);}
  .lbx,.lbx-stage img,.pd-media .shot{animation:none !important; transition:none !important;}
}
.btn.btn-danger{background:var(--bad); border-color:transparent; color:#fff;}
.btn.btn-danger:hover{filter:brightness(1.06);}
/* ── lots & serials ── */
.trace{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r); padding:15px 16px; margin-top:12px;}
.tr-head{display:flex; align-items:center; gap:11px; margin-bottom:13px; flex-wrap:wrap;}
.tr-s{font-size:15px; font-weight:800;}
.tr-chain{display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:13px;}
.tr-step{background:var(--surface); border:1px solid var(--line2); border-radius:var(--r-xs); padding:8px 11px; display:flex; flex-direction:column; gap:2px; min-width:0;}
.tr-step .k{font-size:9.5px; text-transform:uppercase; letter-spacing:.07em; color:var(--ink3); font-weight:700;}
.tr-step .v{font-size:12.5px; font-weight:650;}
.tr-step .v.link{background:none; border:none; padding:0; color:var(--blue-d); text-decoration:underline; text-underline-offset:2px; cursor:pointer; text-align:left;}
.tr-arrow{color:var(--ink4); flex-shrink:0;}
.tr-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:8px;}
.tr-grid > div{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-xs); padding:8px 10px; display:flex; flex-direction:column; gap:2px;}
.tr-grid .k{font-size:10px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3);}
.tr-grid .v{font-size:12.5px; font-weight:650;} .tr-grid .v.bad{color:var(--bad);}
.tr-warn{display:flex; gap:8px; align-items:flex-start; margin-top:12px; background:var(--warn-soft); color:var(--warn); border-radius:var(--r-xs); padding:10px 12px; font-size:12.5px; line-height:1.5;}
.serhits{margin-top:12px;}
.serialgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(76px,1fr)); gap:6px;}
.ser{position:relative; background:var(--surface2); border:1px solid var(--line2); border-left-width:3px; border-radius:var(--r-xs); padding:7px 8px; text-align:left; cursor:pointer; transition:.15s;}
.ser:hover{background:var(--surface); box-shadow:var(--sh-1);}
.ser-c{font-size:11px; font-weight:700; color:var(--ink2);}
.ser-d{position:absolute; top:6px; right:6px; width:6px; height:6px; border-radius:50%;}
.serkey{display:flex; gap:12px; flex-wrap:wrap; margin-top:16px; padding-top:12px; border-top:1px dashed var(--line);}
.serkey span{display:flex; align-items:center; gap:6px; font-size:11.5px; color:var(--ink3);}
.serkey i{width:8px; height:8px; border-radius:50%;}

/* ── B2B ── */
.dealgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(340px,1fr)); gap:12px;}
.deal{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:15px 16px; box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:11px; transition:.18s cubic-bezier(.2,.8,.3,1);}
.deal:hover{border-color:var(--blue); box-shadow:var(--sh-2);}
.deal-t{display:flex; align-items:flex-start; gap:11px;}
.deal-av{width:40px; height:40px; border-radius:12px; display:grid; place-items:center; color:#fff; font-weight:800; font-size:13px; font-family:var(--f-display); flex-shrink:0;}
.deal-id{min-width:0; flex:1;}
.deal-n{font-family:var(--f-display); font-weight:700; font-size:14.5px;}
.deal-s{font-size:11.5px; color:var(--ink3); margin-top:2px;}
.dealsteps{display:flex; gap:4px;}
.dst{flex:1; height:4px; border-radius:999px; background:var(--surface3);}
.dst.on{background:var(--grad);}
.deal-g{display:grid; grid-template-columns:repeat(2,1fr); gap:7px;}
.deal-g > div{background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-xs); padding:7px 9px; display:flex; flex-direction:column; gap:2px;}
.deal-g .k{font-size:10px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3);}
.deal-g .v{font-family:var(--f-mono); font-size:13px; font-weight:700;}
.deal-g .v.ok{color:var(--ok);} .deal-g .v.bad{color:var(--bad);}
.deal-msg{font-size:12.5px; color:var(--ink3); line-height:1.55; font-style:italic;}
.deal-acts{display:flex; gap:6px; flex-wrap:wrap; border-top:1px dashed var(--line); padding-top:11px;}

.b2b-hero{display:grid; grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr); gap:30px; align-items:center; margin-bottom:22px;}
.b2b-hero h1{font-size:clamp(28px,4vw,44px); line-height:1.08; letter-spacing:-.03em; margin:10px 0 12px;}
.b2b-points{display:grid; grid-template-columns:repeat(2,1fr); gap:10px; margin-top:20px;}
.b2b-points > div{display:flex; gap:10px; background:var(--surface); border:1px solid var(--line); border-radius:var(--r-sm); padding:11px 12px;}
.b2b-points .ic{width:30px; height:30px; border-radius:9px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.b2b-points b{font-size:13px; display:block;}
.b2b-points small{font-size:11.5px; color:var(--ink3); line-height:1.45;}
.b2b-grid{display:grid; grid-template-columns:minmax(0,1.35fr) minmax(0,1fr); gap:14px; align-items:start;}
.b2b-done{text-align:center; padding:20px 10px;}
.bd-ic{width:56px; height:56px; border-radius:50%; background:var(--ok-soft); color:var(--ok); display:grid; place-items:center; margin:0 auto 14px;}
.b2b-done h4{font-size:19px; margin-bottom:7px;}
.b2b-done p{font-size:13.5px; color:var(--ink2); line-height:1.6; max-width:400px; margin:0 auto 16px;}
@media (max-width:1000px){ .b2b-hero,.b2b-grid{grid-template-columns:1fr;} .b2b-stage{display:none;} }
@media (max-width:640px){ .tr-grid,.b2b-points,.deal-g{grid-template-columns:1fr;} }
`;

/* ══════════════════════════════════════════════════════════════════════════
   THEMES
   One per client niche. Each changes palette, type, corner radius and the
   background wash together, because a grocer and a jeweller do not want the
   same shop wearing different paint. `tokens` is appended after the base
   stylesheet, so anything omitted falls back to Aurora.
   ══════════════════════════════════════════════════════════════════════════ */
const THEMES = [
  {
    id: "epic", name: "Epic Devices", niche: "House brand, computing and peripherals",
    swatch: ["#0B5CE6", "#17202A", "#F5F7FA"],
    note: "The brand palette from the logo: cobalt blue and graphite on a cool white sheet.",
    tokens: `
      --bg:#F5F7FA; --bg2:#FAFBFD; --surface:#FFFFFF; --surface2:#F1F4F9; --surface3:#E4E9F2;
      --ink:#17202A; --ink2:#434F5E; --ink3:#647081; --ink4:#B6BECB;
      --line:rgba(23,32,42,.09); --line2:rgba(23,32,42,.15); --line3:rgba(23,32,42,.24);
      --blue:#0B5CE6; --blue-l:#1F6FF2; --blue-d:#0033A6; --cyan:#1F6FF2; --sky:#5B8BF0;
      --blue-soft:#E9F0FB; --blue-soft2:#DBE6F8; --blue-tint:rgba(11,92,230,.08);
      --violet:#3B4658; --violet-l:#5A6879; --violet-soft:#ECEFF4;
      --navy:#17202A; --navy2:#10161E;
      --grad:linear-gradient(135deg,#1F6FF2 0%,#0B5CE6 42%,#0033A6 100%);
      --grad-soft:linear-gradient(135deg,#EDF2FC 0%,#FAFBFE 52%,#E9EFFB 100%);
      --f-display:'Epic Display','Saira',system-ui,sans-serif; --f-body:'Epic Text','Plus Jakarta Sans',system-ui,sans-serif; --f-mono:ui-monospace,'SF Mono','Cascadia Mono',Consolas,monospace;
      --r-xs:6px; --r-sm:10px; --r:14px; --r-lg:20px; --r-xl:26px;
      --sh-blue:0 6px 18px rgba(11,92,230,.30);
      --sh-1:0 1px 2px rgba(23,32,42,.05), 0 2px 8px rgba(11,92,230,.05);
      --sh-2:0 4px 14px rgba(23,32,42,.07), 0 12px 30px rgba(11,92,230,.08);
      --sh-3:0 12px 30px rgba(23,32,42,.11), 0 32px 66px rgba(11,92,230,.12);
      --wash:
        radial-gradient(760px 500px at 80% -6%, rgba(11,92,230,.16), transparent 62%),
        radial-gradient(660px 440px at 6% 4%, rgba(23,32,42,.07), transparent 60%);`,
  },
];
const THEME_BY_ID = Object.fromEntries(THEMES.map((t) => [t.id, t]));
const themeCss = (id) => {
  const t = THEME_BY_ID[id];
  return (t && t.tokens ? ".tx{" + t.tokens + "}" : "") + THEME_SHAPES;
};

/* ══════════════════════════════════════════════════════════════════════════
   THEME SHAPES
   Tokens alone only repaint. These change the actual construction of the page
   per niche: how a card is built, how a button is cut, how dense a row runs,
   how images are framed. A fashion store and a tools store should not be the
   same layout in different colours.
   ══════════════════════════════════════════════════════════════════════════ */
const CSS_D = `
/* ══ TAX ══ */
.taxdemo{border:1px solid var(--line); border-radius:var(--r-sm); padding:12px 14px; margin-bottom:10px; background:var(--surface2);}
.taxdemo.warn{border-color:var(--warn-soft2, var(--line2)); background:var(--warn-soft);}
.td-h{font-size:10.5px; text-transform:uppercase; letter-spacing:.07em; font-weight:800; color:var(--ink3); margin-bottom:8px;}
.td-r{display:flex; justify-content:space-between; gap:14px; font-size:12.5px; padding:3px 0; color:var(--ink2);}
.td-r.total{border-top:1px solid var(--line2); margin-top:6px; padding-top:7px; font-weight:800; color:var(--ink);}
.whtbox{border:1px solid var(--line2); border-radius:var(--r-sm); padding:13px 14px; margin-bottom:14px; background:var(--surface2);}
.wb-h{display:flex; align-items:center; gap:7px; font-size:11px; text-transform:uppercase; letter-spacing:.06em;
  font-weight:800; color:var(--blue-d); margin-bottom:10px;}
.wb-sum{display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-top:4px;}
.wb-sum > div{display:flex; flex-direction:column; gap:2px; background:var(--surface); border-radius:var(--r-xs); padding:9px 11px;}
.wb-sum span{font-size:10.5px; color:var(--ink3); text-transform:uppercase; letter-spacing:.04em; font-weight:700;}
.wb-sum b{font-size:14px;}
/* category badges: small, never stretched */
.cbadge{display:inline-flex; align-items:center; flex:0 0 auto; width:auto; max-width:max-content;
  font-size:9.5px; font-weight:800; letter-spacing:.05em; text-transform:uppercase;
  padding:3px 8px; border-radius:999px; margin-left:8px; vertical-align:middle;
  background:var(--surface3); color:var(--ink3);}
.cbadge.off{background:var(--bad-soft); color:var(--bad);}
@media (max-width:640px){ .wb-sum{grid-template-columns:1fr;} }

/* ══ STAMP ══ a round office stamp, the way one actually looks ══ */
.lh-stampwrap{flex-shrink:0;}
.lh-stamp{width:132px; height:132px; color:var(--iv-stamp); transform:rotate(-11deg); opacity:.88;}
.st-arc{font-family:var(--f-display); font-size:16px; font-weight:800; letter-spacing:.22em; text-transform:uppercase;}
.st-arc.sm{font-size:9.5px; font-weight:700; letter-spacing:.13em;}
.st-core{font-family:var(--f-display); font-size:15px; font-weight:900; letter-spacing:.09em; text-transform:uppercase;}
.st-dt{font-family:var(--f-mono); font-size:10px; letter-spacing:.14em;}
/* the header keeps only what identifies the document */
.lh-ntn{display:flex; flex-direction:column; align-items:flex-end; gap:1px; flex-shrink:0;}
.lh-ntn span{font-size:9px; text-transform:uppercase; letter-spacing:.11em; color:#98A2B3; font-weight:700;}
.lh-ntn b{font-size:12px; color:#344054;}
/* and the footer carries the address */
.lh-terms{font-size:11px; color:#475467; line-height:1.6; margin-bottom:9px;}
.lh-addr{display:flex; flex-direction:column; gap:3px; border-top:1px solid #E4E7EC; padding-top:9px;}
.la-n{font-family:var(--f-display); font-size:11.5px; font-weight:800; color:#101828; letter-spacing:.04em; text-transform:uppercase;}
.la-r{display:flex; flex-wrap:wrap; gap:4px 14px; font-size:10px; color:#667085;}
.la-r span{position:relative;}
.la-r span + span::before{content:""; position:absolute; left:-8px; top:50%; width:3px; height:3px;
  border-radius:50%; background:#C4CAD4; transform:translateY(-50%);}
.inv-parties .muted3{color:#98A2B3;}
@media print{ .lh-stamp{-webkit-print-color-adjust:exact; print-color-adjust:exact;} }

/* number fields must never clip the digits */
.finp[type=number]{min-width:0; width:100%; font-family:var(--f-mono); font-size:14px; letter-spacing:.01em;}
.finp.price{font-size:16px; font-weight:700; padding:11px 13px;}
.form-row.three .finp[type=number]{font-size:13.5px;}
.cinp[type=number],.ofe-cell.num{min-width:86px;}

/* ══ A4 LETTER ══ a real page, with the footer sitting at the foot of it ══ */
.lh-view{grid-column:1 / -1; display:flex; gap:7px; align-items:center; flex-wrap:wrap;
  background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:10px 12px; box-shadow:var(--sh-1);}
.lh-view button{display:inline-flex; align-items:center; gap:7px; font-size:12px; font-weight:650;
  padding:7px 13px; border-radius:999px; border:1px solid var(--line2); background:var(--surface); color:var(--ink2); transition:.15s;}
.lh-view button:hover{border-color:var(--blue); color:var(--blue-d);}
.lh-view button.on{background:var(--blue-soft); border-color:transparent; color:var(--blue-d);}
.lh-size{margin-left:auto; font-family:var(--f-mono); font-size:11px; color:var(--ink3);}
.lhpage.editonly .lh-preview{display:none;}
.lhpage.editonly{grid-template-columns:1fr;}
.lhpage.pageonly .lh-edit{display:none;}
.lhpage.pageonly{grid-template-columns:1fr;}
.lhpage.pageonly .lh-preview{position:static; max-width:820px; margin:0 auto;}
/* the sheet is a true A4 page: fixed aspect, content flows, footer pinned */
.invoice-sheet.letter{width:100%; aspect-ratio:210 / 297; min-height:0; max-width:none; margin:0;
  display:flex; flex-direction:column; overflow:hidden; box-shadow:var(--sh-3);}
.invoice-sheet.letter .letter-body{flex:1 1 auto; min-height:0; overflow:hidden; padding:26px 34px 8px;}
.invoice-sheet.letter .lh-bottom{margin-top:auto; flex-shrink:0;}
.lh-of{font-size:10.5px; color:var(--ink3); text-align:center; padding:6px 0 0;}
@media (max-width:1100px){ .invoice-sheet.letter{aspect-ratio:auto; min-height:620px;} }
@media print{
  .lh-view{display:none;}
  .invoice-sheet.letter{aspect-ratio:auto; height:auto; min-height:0; box-shadow:none;}
}

/* ══ PAYMENT TERMS AND AGEING ══ */
.terml{display:flex; gap:8px; align-items:center; margin-bottom:8px; flex-wrap:wrap;}
.terml select.finp{flex:1; min-width:190px;}
.duenote{display:flex; flex-direction:column; gap:2px; font-family:var(--f-mono); font-size:12px; font-weight:700; color:var(--blue-d);}
.duerow{display:block; font-family:var(--f-mono); font-size:12.5px;}
.agebar{display:flex; height:14px; border-radius:999px; overflow:hidden; background:var(--surface3); margin-bottom:14px;}
.ageseg{transition:width .4s cubic-bezier(.2,.8,.3,1);}
.ageseg.s0{background:var(--ok);} .ageseg.s1{background:var(--blue);}
.ageseg.s2{background:var(--warn);} .ageseg.s3{background:#E8833A;} .ageseg.s4{background:var(--bad);}
.agekey{display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:9px;}
.agekey > div{display:flex; align-items:center; gap:8px; font-size:12px; padding:8px 11px;
  background:var(--surface2); border-radius:var(--r-xs);}
.agekey .dot{width:9px; height:9px; border-radius:50%; flex-shrink:0;}
.agekey .dot.s0{background:var(--ok);} .agekey .dot.s1{background:var(--blue);}
.agekey .dot.s2{background:var(--warn);} .agekey .dot.s3{background:#E8833A;} .agekey .dot.s4{background:var(--bad);}
.ak-l{color:var(--ink2);} .ak-c{font-family:var(--f-mono); font-size:10.5px; color:var(--ink4);}
.agekey b{margin-left:auto; font-family:var(--f-mono); font-weight:800;}
.otable td.neg{color:var(--bad);}
.cvsub{font-size:12px; font-weight:600; color:var(--ink3);}

/* ══ BIGGER SEARCH ══ */
.gsearch{min-width:420px; padding:11px 10px 11px 20px; gap:12px;}
.gsearch input{font-size:14.5px;}
.gsearch input::placeholder{font-size:12.5px; letter-spacing:.08em;}
.gs-ic{width:34px; height:34px;}
.gs-drop{width:min(620px, 94vw); top:calc(100% + 12px);}
.gs-list{max-height:60vh;}
@media (max-width:1200px){ .gsearch{min-width:0; flex:1; max-width:400px;} }

/* ══ LETTERHEAD PAGE ══ */
.lhpage{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1.05fr); gap:14px; align-items:start;}
.letterbody{font-family:var(--f-body); line-height:1.7; resize:vertical;}
.tplrow{display:flex; gap:7px; flex-wrap:wrap;}
.tpl{font-size:12px; font-weight:650; padding:7px 13px; border-radius:999px; border:1px solid var(--line2);
  background:var(--surface); color:var(--ink2); transition:.15s;}
.tpl:hover{border-color:var(--blue); color:var(--blue-d);}
.tpl.on{background:var(--blue-soft); border-color:transparent; color:var(--blue-d);}
.lh-preview{position:sticky; top:14px;}
.lh-pvh{display:flex; align-items:center; gap:7px; font-size:11px; text-transform:uppercase; letter-spacing:.08em;
  font-weight:800; color:var(--ink3); margin-bottom:9px;}
.invoice-sheet.letter{max-width:none; margin:0; box-shadow:var(--sh-3); min-height:640px; display:flex; flex-direction:column;}
.letter-body{flex:1; padding:26px 34px 10px;}
.lt-ref{display:flex; justify-content:space-between; font-size:11.5px; color:#667085; margin-bottom:22px;}
.lt-to{margin-bottom:20px;}
.lt-to p{font-size:13px; color:#344054; line-height:1.6;}
.lt-to p.strong{font-weight:700; color:#101828;}
.lt-title{font-size:16px; font-weight:800; color:#101828; margin-bottom:16px; text-decoration:underline; text-underline-offset:4px;}
.lt-p{font-size:13px; line-height:1.85; color:#344054; margin-bottom:13px;}
.lt-empty{font-size:13px; color:#98A2B3; font-style:italic;}
.lt-sign{margin-top:34px; display:flex; flex-direction:column; gap:4px; max-width:250px;}
.lt-sign .sig-line{display:block; height:1px; background:#98A2B3; margin-bottom:8px;}
.lt-sn{font-size:12.5px; font-weight:700; color:#101828;}
.lt-sc{font-size:11px; color:#667085;}
@media (max-width:1100px){ .lhpage{grid-template-columns:1fr;} .lh-preview{position:static;} }
@media print{ .lh-edit{display:none;} .lh-pvh{display:none;} }

/* ══ COMPARISON CONTROLS ══ */
.stmtbar{display:flex; gap:16px; align-items:center; flex-wrap:wrap; background:var(--surface);
  border:1px solid var(--line); border-radius:var(--r); padding:12px 14px; margin-bottom:14px; box-shadow:var(--sh-1);}
.cmpgroup{display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-left:auto;}
.cmp-l{font-size:10.5px; text-transform:uppercase; letter-spacing:.07em; color:var(--ink3); font-weight:800;}
.cmpcount{display:flex; gap:8px; align-items:center;}
.otable.stmt thead th small{display:block; font-size:9.5px; font-weight:600; color:var(--ink4);
  text-transform:none; letter-spacing:0; margin-top:2px;}
.otable.stmt thead th.colnow{color:var(--blue-d); border-bottom:2px solid var(--blue);}
.otable.stmt thead th.colnow small{color:var(--blue);}
.varc small{display:block; font-size:10px; font-weight:600; opacity:.8;}
@media (max-width:900px){ .cmpgroup{margin-left:0; width:100%;} }

/* ══ ACCOUNTING ══ */
.grouprow td{background:var(--surface2); font-size:10.5px; text-transform:uppercase; letter-spacing:.09em;
  font-weight:800; color:var(--ink3); padding:9px 14px !important;}
.acctype{display:inline-flex; font-size:10.5px; font-weight:700; padding:3px 9px; border-radius:999px;
  background:var(--surface3); color:var(--ink2);}
.acctype.asset{background:var(--blue-soft); color:var(--blue-d);}
.acctype.liability{background:var(--warn-soft); color:var(--warn);}
.acctype.equity{background:var(--violet-soft); color:var(--violet);}
.acctype.income{background:var(--ok-soft); color:var(--ok);}
.acctype.cogs,.acctype.expense{background:var(--bad-soft); color:var(--bad);}
.typegrid{display:grid; grid-template-columns:repeat(3,1fr); gap:8px;}
.typebtn{display:flex; flex-direction:column; gap:2px; text-align:left; padding:10px 12px; border-radius:var(--r-xs);
  border:1px solid var(--line2); background:var(--surface); transition:.15s;}
.typebtn:hover{border-color:var(--blue);}
.typebtn.on{background:var(--blue-soft); border-color:transparent; box-shadow:0 0 0 2px var(--blue-tint);}
.typebtn b{font-size:12.5px;} .typebtn small{font-size:10.5px; color:var(--ink3);}
.otable.stmt td:first-child{padding-left:22px;}
.otable.stmt .grouprow td{padding-left:14px !important;}
.totalrow td{background:var(--surface2); font-weight:800; border-top:1px solid var(--line2); border-bottom:1px solid var(--line2);}
.totalrow.grand td{background:var(--navy); color:#fff; font-family:var(--f-display); font-size:15px;}
.totalrow.grand .osoft{color:rgba(255,255,255,.6);}
.varc{font-family:var(--f-mono); font-size:12px; font-weight:700;}
.varc.up{color:var(--ok);} .varc.down{color:var(--bad);}
.totalrow.grand .varc.up{color:#6EE7B7;} .totalrow.grand .varc.down{color:#FCA5A5;}
@media (max-width:640px){ .typegrid{grid-template-columns:1fr 1fr;} }

/* ══ TREASURY ══ */
.acctrow{display:grid; grid-template-columns:repeat(auto-fit,minmax(250px,1fr)); gap:12px; margin-bottom:14px;}
.acct{display:flex; align-items:flex-start; gap:12px; text-align:left; background:var(--surface);
  border:1px solid var(--line); border-radius:var(--r); padding:16px 17px; box-shadow:var(--sh-1);
  transition:.18s cubic-bezier(.2,.8,.3,1); width:100%;}
button.acct:hover{border-color:var(--blue); transform:translateY(-2px); box-shadow:var(--sh-2);}
.acct.on{border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint), var(--sh-2);}
.acct.total{background:linear-gradient(150deg, var(--navy), #16204A); color:#fff; border-color:transparent; flex-direction:column; gap:14px;}
.acct-i{width:40px; height:40px; border-radius:12px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.acct-b{display:flex; flex-direction:column; gap:3px; min-width:0; flex:1;}
.acct-l{font-size:11px; text-transform:uppercase; letter-spacing:.07em; color:var(--ink3); font-weight:800;}
.acct.total .acct-l{color:rgba(255,255,255,.6);}
.acct-v{font-family:var(--f-mono); font-size:25px; font-weight:800; letter-spacing:-.02em; line-height:1.1;}
.acct-v.neg{color:var(--bad);}
.acct-s{font-size:11.5px; color:var(--ink3);}
.acct.total .acct-s{color:rgba(255,255,255,.6);}
.acctchip{display:inline-flex; font-size:10.5px; font-weight:800; text-transform:uppercase; letter-spacing:.05em;
  padding:3px 9px; border-radius:999px;}
.acctchip.cash{background:var(--warn-soft); color:var(--warn);}
.acctchip.bank{background:var(--blue-soft); color:var(--blue-d);}
.xfer{display:grid; grid-template-columns:1fr auto 1fr; gap:10px; align-items:center; margin-bottom:18px;}
.xf-a{display:flex; flex-direction:column; gap:2px; text-align:left; background:var(--surface2);
  border:1px solid var(--line); border-radius:var(--r-sm); padding:13px 15px; transition:.16s;}
.xf-a:hover{border-color:var(--blue);}
.xf-l{font-size:10px; text-transform:uppercase; letter-spacing:.07em; color:var(--ink3); font-weight:800;}
.xf-n{font-size:14px; font-weight:700;}
.xf-v{font-family:var(--f-mono); font-size:12.5px; color:var(--ink3);}
.xf-swap{width:36px; height:36px; border-radius:50%; background:var(--grad); color:#fff; display:grid; place-items:center;
  box-shadow:0 3px 10px rgba(22,87,220,.3); transition:transform .2s;}
.xf-swap:hover{transform:rotate(180deg);}
@media (max-width:560px){ .xfer{grid-template-columns:1fr; } .xf-swap{justify-self:center; transform:rotate(90deg);} }

/* ══ SETTINGS NAV ══ */
.setnav{position:sticky; top:0; z-index:20; display:flex; gap:6px; flex-wrap:wrap; padding:11px 0 13px;
  margin-bottom:4px; background:linear-gradient(var(--canvas) 78%, transparent);}
.setnav button{font-size:12px; font-weight:650; padding:7px 13px; border-radius:999px;
  border:1px solid var(--line2); background:var(--surface); color:var(--ink2); transition:.15s;}
.setnav button:hover{border-color:var(--blue); color:var(--blue-d);}
.setnav button.on{background:var(--blue-soft); border-color:transparent; color:var(--blue-d);}

/* ══ CATEGORY FACET ══ plain text, counts, multi-select ══ */
.fcat{display:flex; align-items:center; gap:10px; width:100%; text-align:left; padding:8px 10px;
  border-radius:var(--r-xs); border:1px solid transparent; background:none; font-size:13px;
  color:var(--ink2); transition:.14s;}
.fcat:hover{background:var(--surface2); color:var(--ink);}
.fcat .ct{margin-left:auto; font-family:var(--f-mono); font-size:11px; color:var(--ink4); font-weight:700;}
.fcat.group{font-weight:700; color:var(--ink); margin-top:6px;}
.fcat.sub{padding-left:20px; font-size:12.5px;}
.fcat.all{font-weight:700; color:var(--ink);}
.fcat.on{background:var(--blue-soft); border-color:transparent; color:var(--blue-d); font-weight:800;}
.fcat.on .ct{color:var(--blue-d);}
.fcat.on::before{content:""; position:absolute;}
.fcat.sub.on{padding-left:20px; box-shadow:inset 3px 0 0 var(--blue);}
.fcat-note{font-size:11.5px; color:var(--ink3); padding:9px 10px 2px; line-height:1.5;}
.tickbox{display:inline-block; width:14px; height:14px; border:1px solid #98A2B3; border-radius:3px;}
.inv-head.slim{grid-template-columns:1fr auto;}

/* ══ INQUIRY LIFECYCLE ══ status down the left of the form ══ */
.of-split{display:grid; grid-template-columns:232px minmax(0,1fr); align-items:start;}
.lifetrack{border-right:1px solid var(--line); padding:22px 18px 26px; align-self:stretch; background:var(--surface2);}
.lt-h{display:block; font-size:10px; text-transform:uppercase; letter-spacing:.11em; color:var(--ink3); font-weight:800; margin-bottom:14px;}
.lt-s{position:relative; display:flex; gap:11px; padding:0 0 20px;}
.lt-s:last-child{padding-bottom:0;}
.lt-s::before{content:""; position:absolute; left:13px; top:28px; bottom:0; width:2px; background:var(--line2);}
.lt-s:last-child::before{display:none;}
.lt-s.past::before{background:var(--ok);}
.lt-i{width:28px; height:28px; border-radius:50%; display:grid; place-items:center; flex-shrink:0; z-index:1;
  background:var(--surface); border:2px solid var(--line2); color:var(--ink4);}
.lt-s.past .lt-i{background:var(--ok); border-color:var(--ok); color:#fff;}
.lt-s.now .lt-i{background:var(--grad); border-color:transparent; color:#fff; box-shadow:0 0 0 4px var(--blue-tint);}
.lt-s.lost .lt-i{background:var(--bad); border-color:var(--bad); color:#fff;}
.lt-b{display:flex; flex-direction:column; gap:1px; min-width:0; padding-top:3px;}
.lt-l{font-size:12.5px; font-weight:700; color:var(--ink3);}
.lt-s.past .lt-l,.lt-s.now .lt-l{color:var(--ink);}
.lt-s.now .lt-l{color:var(--blue-d);}
.lt-d{font-size:10.5px; color:var(--ink4); font-family:var(--f-mono); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.of-sheet.flush{padding:22px 26px 26px;}
.deal-av.sm{width:30px; height:30px; border-radius:9px; font-size:11px;}
.lifechip{display:inline-flex; align-items:center; gap:6px; font-size:11px; font-weight:700; padding:5px 11px;
  border-radius:999px; white-space:nowrap; background:var(--surface3); color:var(--ink2);}
.lifechip.s0{background:var(--warn-soft); color:var(--warn);}
.lifechip.s1{background:var(--blue-soft); color:var(--blue-d);}
.lifechip.s2{background:var(--violet-soft); color:var(--violet);}
.lifechip.s3{background:var(--ok-soft); color:var(--ok);}
@media (max-width:860px){
  .of-split{grid-template-columns:1fr;}
  .lifetrack{border-right:none; border-bottom:1px solid var(--line); display:flex; gap:14px; overflow-x:auto; padding:14px 16px;}
  .lt-h{display:none;}
  .lt-s{padding:0; flex-shrink:0;}
  .lt-s::before{display:none;}
}

/* ══ LETTERHEAD ══ printed on every document sheet ══ */
.lh-top{display:flex; align-items:flex-start; gap:16px; padding:26px 34px 16px; border-bottom:2px solid var(--iv-accent);}
.lh-logo{height:44px; width:auto; object-fit:contain; flex-shrink:0;}
.lh-mk{width:44px; height:44px; border-radius:12px; background:var(--iv-band); display:grid; place-items:center; flex-shrink:0;}
.lh-id{flex:1; min-width:0;}
.lh-name{font-family:var(--f-display); font-size:21px; font-weight:800; letter-spacing:-.01em; color:#101828;}
.lh-sub{font-size:11.5px; color:#667085; margin-top:1px;}
.lh-line{font-size:11px; color:var(--iv-accent); font-weight:650; margin-top:5px;}
.lh-contact{display:flex; flex-direction:column; gap:2px; text-align:right; font-size:10.5px; color:#667085; max-width:250px; flex-shrink:0;}
.lh-bottom{display:flex; gap:22px; align-items:flex-start; padding:18px 34px 8px; margin-top:6px; border-top:1px dashed #D0D5DD;}
.lh-stamp{border:2px solid var(--iv-accent); border-radius:8px; padding:10px 16px; display:flex; flex-direction:column; gap:2px;
  color:var(--iv-accent); font-size:10px; font-weight:700; letter-spacing:.04em; text-transform:uppercase;
  transform:rotate(-3deg); opacity:.86; flex-shrink:0; max-width:210px;}
.lh-note{flex:1; min-width:0;}
.lh-note p{font-size:11px; color:#475467; line-height:1.6;}
.lh-meta{font-size:10px; color:#98A2B3; margin-top:6px;}
.ofe-pick{display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-top:4px;}
.ofe-pick .ofe-title{margin-top:0; flex:1; min-width:220px;}
@media print{ .lh-top,.lh-bottom{break-inside:avoid;} }
@media (max-width:700px){ .lh-top{flex-wrap:wrap;} .lh-contact{text-align:left; max-width:none;} .lh-bottom{flex-direction:column;} }

/* ══ SHOWREEL ══ */
.reel{display:grid; grid-template-columns:minmax(0,1fr) 268px; gap:14px; align-items:start;}
.reel-nav{display:flex; align-items:center; gap:8px;}
.reel-count{font-size:12px; color:var(--ink3); min-width:46px; text-align:center;}
.reel-stage{position:relative; border-radius:var(--r-lg); overflow:hidden; aspect-ratio:16/10; background:var(--navy); box-shadow:var(--sh-3);}
.reel-stage > img,.reel-stage > video,.reel-stage > iframe{width:100%; height:100%; object-fit:cover; display:block; border:none;}
.reel-copy{position:absolute; left:0; right:0; bottom:0; padding:30px 30px 26px; color:#fff;
  background:linear-gradient(180deg, transparent, rgba(6,10,22,.34) 38%, rgba(6,10,22,.88));}
.reel-copy h3{font-size:clamp(19px,2.4vw,29px); line-height:1.15; letter-spacing:-.02em; margin-bottom:7px; color:#fff;}
.reel-copy p{font-size:14px; color:rgba(255,255,255,.82); line-height:1.55; max-width:52ch;}
.reel-acts{display:flex; gap:9px; margin-top:16px; flex-wrap:wrap;}
.btn.btn-glass{background:rgba(255,255,255,.14); border:1px solid rgba(255,255,255,.28); color:#fff; backdrop-filter:blur(8px);}
.btn.btn-glass:hover{background:rgba(255,255,255,.24);}
.reel-mute{position:absolute; top:14px; right:14px; width:36px; height:36px; border-radius:50%; z-index:3;
  background:rgba(8,12,22,.55); border:1px solid rgba(255,255,255,.22); color:#fff; display:grid; place-items:center; backdrop-filter:blur(6px);}
.reel-rail{display:flex; flex-direction:column; gap:8px;}
.reel-th{position:relative; display:flex; gap:10px; align-items:center; text-align:left; padding:8px; border-radius:var(--r-sm);
  border:1px solid var(--line); background:var(--surface); overflow:hidden; transition:.18s cubic-bezier(.2,.8,.3,1);}
.reel-th:hover{border-color:var(--blue); transform:translateX(-2px);}
.reel-th.on{border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint);}
.rt-m{position:relative; width:66px; height:44px; border-radius:var(--r-xs); overflow:hidden; flex-shrink:0; background:var(--navy);}
.rt-m img{width:100%; height:100%; object-fit:cover;}
.rt-play{position:absolute; inset:0; display:grid; place-items:center; color:#fff; background:rgba(8,12,22,.3);}
.rt-t{font-size:12.5px; font-weight:650; line-height:1.35; color:var(--ink);}
.rt-bar{position:absolute; left:0; bottom:0; height:2px; width:100%; background:var(--grad); transform-origin:left; transform:scaleX(0);}
.tx.anim .reel-th.on .rt-bar{animation:hdrun 7s linear forwards;}
@media (max-width:900px){ .reel{grid-template-columns:1fr;} .reel-rail{flex-direction:row; overflow-x:auto; padding-bottom:4px;} .reel-th{min-width:210px;} }

/* ══ GLOBAL SEARCH ══ one bar, results drop out of it ══ */
.gsearch{position:relative; display:flex; align-items:center; gap:9px; min-width:300px;
  background:var(--surface); border:1px solid var(--line2); border-radius:999px; padding:9px 15px;
  transition:box-shadow .2s, border-color .2s, background .2s;}
.gsearch:hover{border-color:var(--blue-soft2);}
.gsearch:focus-within,.gsearch.open{border-color:var(--blue);
  box-shadow:0 0 0 4px var(--blue-tint), 0 6px 22px rgba(22,87,220,.16); background:var(--surface);}
.gsearch input{flex:1; min-width:0; border:none; background:none; outline:none; font-size:13.5px;
  color:var(--ink); font-family:var(--f-body); letter-spacing:.01em;}
.gsearch input::placeholder{color:var(--ink3); letter-spacing:.06em; text-transform:uppercase; font-size:11.5px; font-weight:600;}
.gsearch kbd{font-family:var(--f-mono); font-size:10px; color:var(--ink4);
  border:1px solid var(--line2); border-radius:5px; padding:2px 6px; flex-shrink:0; transition:opacity .18s;}
.gsearch:focus-within kbd{opacity:0;}
.gs-ic{width:28px; height:28px; border-radius:50%; display:grid; place-items:center; flex-shrink:0;
  background:var(--grad); color:#fff; box-shadow:0 2px 8px rgba(22,87,220,.34); transition:transform .2s;}
.gsearch:focus-within .gs-ic{transform:scale(1.06);}
.gs-scrim{position:fixed; inset:0; z-index:60;}
.gs-drop{position:absolute; top:calc(100% + 10px); right:0; width:min(520px, 92vw); z-index:61;
  background:var(--surface); border:1px solid var(--line2); border-radius:var(--r);
  box-shadow:0 24px 60px rgba(8,12,22,.24); overflow:hidden; animation:txFadeUp .16s cubic-bezier(.2,.8,.3,1) both;}
.gs-list{max-height:56vh; overflow-y:auto; padding:6px;}
.gs-sec{font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--ink3); font-weight:800; padding:10px 11px 5px;}
.gs-row{width:100%; display:flex; align-items:center; gap:11px; padding:9px 11px; border-radius:var(--r-xs);
  border:none; background:none; text-align:left; transition:background .12s;}
.gs-row.on{background:var(--blue-soft);}
.gs-i{width:30px; height:30px; border-radius:9px; background:var(--surface2); color:var(--blue-d);
  display:grid; place-items:center; flex-shrink:0;}
.gs-row.on .gs-i{background:var(--surface);}
.gs-l{display:flex; flex-direction:column; gap:1px; min-width:0; flex:1;}
.gs-l small{font-size:11.5px; color:var(--ink3); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.gs-go{font-size:10px; color:var(--blue-d); border:1px solid var(--blue-soft2); border-radius:5px; padding:2px 6px;}
.gs-none{padding:26px; text-align:center; color:var(--ink3); font-size:13px;}
.gs-foot{display:flex; gap:14px; align-items:center; padding:9px 15px; border-top:1px solid var(--line);
  background:var(--surface2); font-size:11px; color:var(--ink3);}
.gs-foot b{font-family:var(--f-mono); color:var(--ink2); font-weight:600;}
.gs-count{margin-left:auto;}
@media (max-width:1100px){ .gsearch{min-width:0; flex:1; max-width:340px;} }
@media (max-width:720px){ .gsearch{padding:7px 9px;} .gsearch kbd{display:none;} .gs-drop{right:auto; left:0; width:min(420px,92vw);} }

/* ══ STICKY BUY BAR ══ */
.buybar{position:fixed; left:0; right:0; bottom:0; z-index:80; background:var(--surface); border-top:1px solid var(--line2);
  box-shadow:0 -8px 30px rgba(10,16,32,.12); padding:10px 16px; display:none; align-items:center; gap:12px;}
.buybar.show{display:flex;}
.bb-m{width:44px; height:44px; border-radius:var(--r-xs); background:var(--surface2); border:1px solid var(--line); overflow:hidden; display:grid; place-items:center; flex-shrink:0;}
.bb-m img{width:100%; height:100%; object-fit:contain; padding:3px;}
.bb-i{min-width:0; flex:1;}
.bb-n{font-size:13px; font-weight:650; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.bb-p{font-family:var(--f-mono); font-size:14px; font-weight:800; color:var(--ink);}
.buybar .btn{flex-shrink:0;}
@media (max-width:900px){ .buybar{padding-bottom:calc(10px + env(safe-area-inset-bottom));} }

/* showreel manager */
.reeledit{border:1px solid var(--line); border-radius:var(--r-sm); padding:12px 13px; margin-bottom:11px; background:var(--surface2);}
.reeledit.off{opacity:.55;}
.re-top{display:flex; gap:11px; align-items:flex-start; margin-bottom:11px;}
.re-th{width:82px; height:56px; border-radius:var(--r-xs); overflow:hidden; background:var(--navy); flex-shrink:0; border:1px solid var(--line2);}
.re-th img{width:100%; height:100%; object-fit:cover;}
.re-i{flex:1; min-width:0; display:flex; flex-direction:column; gap:7px;}
.re-i .finp:first-child{font-weight:650;}

.reelrow{display:flex; gap:11px; align-items:flex-start; padding:12px 0; border-bottom:1px dashed var(--line);}
.reelrow:last-of-type{border-bottom:none;}
.rr-n{width:26px; height:26px; border-radius:8px; background:var(--surface2); border:1px solid var(--line); display:grid; place-items:center; font-size:11px; font-weight:700; color:var(--ink3); flex-shrink:0; margin-top:6px;}
.rr-f{flex:1; min-width:0; display:flex; flex-direction:column; gap:8px;}

/* ══ DOCUMENT CHAINS ══ */
.chainbar{display:flex; align-items:center; gap:8px; flex-wrap:wrap; background:var(--surface); border:1px solid var(--line);
  border-radius:var(--r); padding:12px 14px; margin-bottom:14px; box-shadow:var(--sh-1);}
.chainstep{display:flex; align-items:center; gap:10px; padding:9px 13px; border-radius:var(--r-sm);
  border:1px solid var(--line); background:var(--surface2); transition:.18s cubic-bezier(.2,.8,.3,1); text-align:left;}
.chainstep:hover{border-color:var(--blue); transform:translateY(-1px);}
.chainstep.on{border-color:var(--blue); background:var(--blue-soft); box-shadow:0 0 0 2px var(--blue-tint);}
.cs-i{width:30px; height:30px; border-radius:9px; background:var(--surface); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.chainstep.on .cs-i{background:var(--grad); color:#fff;}
.cs-b{display:flex; flex-direction:column; gap:1px; min-width:0;}
.cs-l{font-size:12.5px; font-weight:700;}
.cs-v{font-size:11px; color:var(--ink3); font-family:var(--f-mono);}
.chainarrow{color:var(--ink4); flex-shrink:0;}
.chainend{margin-left:auto; display:flex; align-items:center; gap:8px; font-size:11.5px; color:var(--ink3);
  background:var(--surface2); border:1px dashed var(--line2); border-radius:999px; padding:7px 13px;}
.chainend svg{color:var(--blue);}
.docgrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(340px,1fr)); gap:12px;}
.doc{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:14px 15px;
  box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:11px; transition:.18s cubic-bezier(.2,.8,.3,1);}
.doc:hover{border-color:var(--blue); box-shadow:var(--sh-2);}
.doc.done{border-left:3px solid var(--ok);}
.doc-t{display:flex; align-items:flex-start; gap:11px;}
.doc-i{width:34px; height:34px; border-radius:10px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.doc.done .doc-i{background:var(--ok-soft); color:var(--ok);}
.doc-id{min-width:0; flex:1;}
.doc-n{font-family:var(--f-mono); font-weight:800; font-size:13.5px; display:flex; align-items:center; gap:7px; flex-wrap:wrap;}
.doc-s{font-size:11.5px; color:var(--ink3); margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.doc-v{font-weight:800; font-size:14px; flex-shrink:0;}
.docsteps{display:flex; gap:4px;}
.dss{flex:1; height:4px; border-radius:999px; background:var(--surface3);}
.dss.on{background:var(--grad);}
.doc-meta{display:flex; gap:9px; flex-wrap:wrap; font-size:11px; color:var(--ink3);}
.doc-meta span{display:inline-flex; align-items:center; gap:5px;}
.doc-meta svg{color:var(--ink4);}
.doc-due{color:var(--warn); font-weight:700; margin-left:auto;}
.doc-acts{display:flex; gap:6px; flex-wrap:wrap; border-top:1px dashed var(--line); padding-top:11px;}
.trailrow{display:flex; align-items:center; gap:7px; flex-wrap:wrap;}
.trailrow .chip.on{background:var(--blue-soft); color:var(--blue-d); border-color:transparent; font-weight:700;}
@media (max-width:640px){ .chainend{margin-left:0; width:100%;} .doc-meta .doc-due{margin-left:0;} }

.quickrow{display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:10px; margin-bottom:14px;}
.qact{display:flex; align-items:center; gap:11px; text-align:left; background:var(--surface); border:1px solid var(--line);
  border-radius:var(--r-sm); padding:12px 14px; box-shadow:var(--sh-1); transition:.18s cubic-bezier(.2,.8,.3,1);}
.qact:hover{border-color:var(--blue); transform:translateY(-2px); box-shadow:var(--sh-2);}
.qa-i{width:34px; height:34px; border-radius:10px; background:var(--blue-soft); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.qact b{display:block; font-size:13px;}
.qact small{display:block; font-size:11.5px; color:var(--ink3); margin-top:1px;}

/* ══ DASHBOARD ══ */
.rangebar.dash{margin-bottom:14px;}
.dashtop{display:grid; grid-template-columns:minmax(0,1.35fr) minmax(0,1fr); gap:12px; margin-bottom:14px;}
.dt-hero{background:linear-gradient(150deg, var(--navy) 0%, #10193A 58%, #1B1140 100%); color:#fff;
  border-radius:var(--r); padding:22px 24px; box-shadow:var(--sh-3); position:relative; overflow:hidden;}
.dt-hero::after{content:""; position:absolute; right:-70px; top:-70px; width:240px; height:240px; border-radius:50%;
  background:var(--blue); opacity:.18;}
.dt-l{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:rgba(255,255,255,.62); font-weight:700;}
.dt-v{display:block; font-family:var(--f-display); font-size:clamp(30px,4.4vw,46px); font-weight:800; letter-spacing:-.03em; margin:6px 0 4px; position:relative;}
.dt-s{display:block; font-size:12.5px; color:rgba(255,255,255,.7); margin-bottom:18px;}
.dt-split{display:flex; height:10px; border-radius:999px; overflow:hidden; background:rgba(255,255,255,.14); position:relative;}
.dts{transition:width .4s cubic-bezier(.2,.8,.3,1);}
.dts.empty{background:rgba(255,255,255,.14);}
.dt-key{display:flex; gap:14px; flex-wrap:wrap; margin-top:11px; font-size:11.5px; color:rgba(255,255,255,.78);}
.dt-key span{display:inline-flex; align-items:center; gap:6px;}
.dt-key i{width:8px; height:8px; border-radius:50%;}
.dt-side{display:grid; grid-template-columns:1fr 1fr; gap:10px;}
.dtile{background:var(--surface); border:1px solid var(--line); border-radius:var(--r-sm); padding:13px 14px;
  display:flex; flex-direction:column; gap:3px; box-shadow:var(--sh-1); transition:.18s cubic-bezier(.2,.8,.3,1);}
.dtile:hover{border-color:var(--blue); transform:translateY(-2px);}
.dtile .k{display:inline-flex; align-items:center; gap:6px; font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3); font-weight:700;}
.dtile .k svg{color:var(--blue);}
.dtile .v{font-family:var(--f-mono); font-size:22px; font-weight:800; line-height:1.1;}
.dtile .v.warn{color:var(--warn);}
.dtile .s{font-size:11px; color:var(--ink3);}
.chanrow{display:grid; grid-template-columns:repeat(auto-fit,minmax(250px,1fr)); gap:12px; margin-bottom:14px;}
.chan{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); padding:15px 16px;
  box-shadow:var(--sh-1); display:flex; flex-direction:column; gap:11px; border-top:3px solid var(--cc);
  transition:.18s cubic-bezier(.2,.8,.3,1);}
.chan:hover{box-shadow:var(--sh-2); transform:translateY(-2px);}
.chan-t{display:flex; align-items:flex-start; gap:10px;}
.chan-i{width:32px; height:32px; border-radius:10px; background:var(--surface2); color:var(--cc); display:grid; place-items:center; flex-shrink:0;}
.chan-n{font-family:var(--f-display); font-weight:700; font-size:14px;}
.chan-s{font-size:11px; color:var(--ink3); margin-top:1px;}
.chan-p{margin-left:auto; font-size:13px; font-weight:800; color:var(--cc);}
.chan-v{font-family:var(--f-mono); font-size:21px; font-weight:800; letter-spacing:-.01em;}
.chan-bar{height:6px; border-radius:999px; background:var(--surface3); overflow:hidden;}
.chan-bar span{display:block; height:100%; background:var(--cc); border-radius:999px; transition:width .4s cubic-bezier(.2,.8,.3,1);}
.chan-g{display:grid; grid-template-columns:repeat(4,1fr); gap:6px; border-top:1px dashed var(--line); padding-top:10px;}
.chan-g .k{display:block; font-size:9.5px; text-transform:uppercase; letter-spacing:.04em; color:var(--ink3);}
.chan-g .v{display:block; font-family:var(--f-mono); font-size:12.5px; font-weight:700;}
.sostrip{display:flex; align-items:stretch; gap:8px; flex-wrap:wrap;}
.so{flex:1; min-width:150px; background:var(--surface2); border:1px solid var(--line); border-radius:var(--r-sm); padding:12px 13px; display:flex; flex-direction:column; gap:2px;}
.so.done{background:var(--blue-soft); border-color:transparent;}
.so .k{font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3); font-weight:700;}
.so .v{font-family:var(--f-mono); font-size:22px; font-weight:800; line-height:1.15;}
.so .s{font-size:11px; color:var(--ink3);}
.so-a{color:var(--ink4); align-self:center; flex-shrink:0;}
@media (max-width:1000px){ .dashtop{grid-template-columns:1fr;} }
@media (max-width:560px){ .dt-side{grid-template-columns:1fr;} .chan-g{grid-template-columns:repeat(2,1fr);} .so-a{display:none;} }

/* clickable metrics: they must look pressable, not decorative */
/* a <button> centres its children by default, which was pulling every tile's
   contents into the middle. Force the same alignment a <div> would give. */
.dtile,.chan,.so{text-align:left; font:inherit; color:inherit; cursor:default; align-items:stretch; width:100%;}
button.dtile > *,button.chan > *,button.so > *{text-align:left;}
button.dtile,button.chan,button.so{cursor:pointer; position:relative;}
button.dtile::after,button.so::after{content:""; position:absolute; right:11px; top:11px; width:5px; height:5px;
  border-right:1.5px solid var(--ink4); border-top:1.5px solid var(--ink4); transform:rotate(45deg); opacity:0; transition:opacity .18s, transform .18s;}
button.dtile:hover::after,button.so:hover::after{opacity:1; transform:rotate(45deg) translate(2px,-2px);}
button.so:hover{border-color:var(--blue); background:var(--surface);}
button.chan:hover{border-color:var(--cc);}
button.chan:focus-visible,button.dtile:focus-visible,button.so:focus-visible{outline:2px solid var(--blue); outline-offset:2px;}
/* rows you can open */
.dtable.rows tbody tr.clickrow{cursor:pointer; transition:background .14s;}
.dtable.rows tbody tr.clickrow:hover{background:var(--blue-soft);}
.docline{display:flex; align-items:center; gap:10px; min-width:0;}
.doc-i.sm{width:28px; height:28px; border-radius:8px;}
.doc-i.sm.done{background:var(--ok-soft); color:var(--ok);}
.nextup{display:flex; align-items:flex-start; gap:10px; background:var(--blue-soft); border-radius:var(--r-sm);
  padding:11px 13px; font-size:12.5px; line-height:1.5; color:var(--blue-d); margin-bottom:14px;}
.nu-i{width:26px; height:26px; border-radius:8px; background:var(--surface); color:var(--blue-d); display:grid; place-items:center; flex-shrink:0;}
.drawer-foot{display:flex; gap:8px; flex-wrap:wrap;}
.dtable .nowrap{white-space:nowrap;}
.dtable .nowrap svg{vertical-align:-1px; margin-right:3px;}

/* ══ DOCUMENT MODULE ══ control panel, list, form ══ */
.gsearch{display:flex; align-items:center; gap:8px; background:var(--surface2); border:1px solid var(--line2);
  border-radius:999px; padding:6px 12px; min-width:210px; transition:.16s;}
.gsearch:focus-within{border-color:var(--blue); background:var(--surface); box-shadow:0 0 0 3px var(--blue-tint);}
.gsearch svg{color:var(--ink3); flex-shrink:0;}
.gsearch input{border:none; background:none; outline:none; font-size:12.5px; color:var(--ink); width:100%; font-family:var(--f-body);}
.gsearch kbd{font-family:var(--f-mono); font-size:10px; color:var(--ink4); border:1px solid var(--line2); border-radius:4px; padding:1px 5px; flex-shrink:0;}
@media (max-width:900px){ .gsearch{min-width:0; width:38px; padding:6px;} .gsearch input,.gsearch kbd{display:none;} }

.ocp{background:var(--surface); border:1px solid var(--line); border-radius:var(--r) var(--r) 0 0; border-bottom:none;}
.ocp-top{display:flex; align-items:center; gap:12px; padding:11px 14px; border-bottom:1px solid var(--line);}
.ocp-search{flex:1; display:flex; align-items:center; gap:9px; background:var(--surface2); border:1px solid var(--line2);
  border-radius:var(--r-sm); padding:8px 12px; max-width:520px;}
.ocp-search:focus-within{border-color:var(--blue); background:var(--surface);}
.ocp-search svg{color:var(--ink3); flex-shrink:0;}
.ocp-search input{border:none; background:none; outline:none; font-size:13px; width:100%; color:var(--ink); font-family:var(--f-body);}
.ocp-right{margin-left:auto; display:flex; align-items:center; gap:8px;}
.opager-c{font-size:11.5px; color:var(--ink3);}
.opager{display:flex; gap:2px;}
.ocp-facets{display:flex; align-items:center; gap:6px; padding:10px 14px; flex-wrap:wrap;}
.ofacet{display:inline-flex; align-items:center; gap:6px; font-size:12px; padding:6px 11px; border-radius:999px;
  border:1px solid var(--line2); background:var(--surface); color:var(--ink2); transition:.15s;}
.ofacet:hover{border-color:var(--blue); color:var(--blue-d);}
.ofacet.on{background:var(--blue-soft); border-color:transparent; color:var(--blue-d); font-weight:650;}
.ofacet b{font-family:var(--f-mono); font-size:11px; color:var(--ink3); font-weight:700;}
.ofacet.on b{color:var(--blue-d);}
.ofacet.soft{border-style:dashed;}
.ofacet.clear{border-color:transparent; color:var(--ink3);}
.ofacet-div{width:1px; height:20px; background:var(--line2); margin:0 4px;}

.olist{background:var(--surface); border:1px solid var(--line); border-radius:0 0 var(--r) var(--r); overflow-x:auto;}
.otable{width:100%; border-collapse:collapse; font-size:13px;}
.otable thead th{text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink3);
  font-weight:700; padding:10px 14px; border-bottom:1px solid var(--line2); background:var(--surface2); white-space:nowrap;}
.otable th.num,.otable td.num{text-align:right;}
.otable th.sortable{cursor:pointer; user-select:none;}
.otable th.sortable:hover{color:var(--blue-d);}
.otable tbody tr{border-bottom:1px solid var(--line); cursor:pointer; transition:background .12s;}
.otable tbody tr:hover{background:var(--blue-soft);}
.otable tbody tr.plain{cursor:default;}
.otable tbody tr.plain:hover{background:transparent;}
.otable td{padding:11px 14px; vertical-align:middle;}
.oref{font-weight:700; font-size:12.5px;}
.otrail{display:block; font-size:10.5px; color:var(--ink4); margin-top:1px;}
.oparty{font-weight:600;}
.osub{display:block; font-size:11px; color:var(--ink3); margin-top:1px;}
.osoft{color:var(--ink3);}
.ostrong{font-weight:800;}
.otable tfoot td{padding:10px 14px; font-size:12px; color:var(--ink3); background:var(--surface2); border-top:1px solid var(--line2);}
.ostate{display:inline-flex; align-items:center; font-size:11px; font-weight:700; padding:4px 10px; border-radius:999px; white-space:nowrap;}
.ostate.draft{background:var(--surface3); color:var(--ink2);}
.ostate.wait{background:var(--violet-soft); color:var(--violet);}
.ostate.due{background:var(--warn-soft); color:var(--warn);}
.ostate.ok{background:var(--ok-soft); color:var(--ok);}

.oform{background:var(--surface); border:1px solid var(--line); border-radius:var(--r); box-shadow:var(--sh-1); overflow:hidden;}
.of-head{display:flex; align-items:center; gap:10px; padding:11px 14px; border-bottom:1px solid var(--line); flex-wrap:wrap;}
.of-acts{display:flex; gap:7px; flex-wrap:wrap;}
.of-stages{margin-left:auto; display:flex; gap:2px; flex-wrap:wrap;}
.ostage{font-size:10.5px; text-transform:uppercase; letter-spacing:.06em; font-weight:700; padding:6px 13px;
  background:var(--surface2); color:var(--ink3); border:1px solid var(--line2); border-right:none;}
.ostage:first-child{border-radius:999px 0 0 999px;}
.ostage:last-child{border-radius:0 999px 999px 0; border-right:1px solid var(--line2);}
.ostage.past{color:var(--ink2); background:var(--surface3);}
.ostage.now{background:var(--grad); color:#fff; border-color:transparent;}
.ostage.now.done{background:var(--ok); }
.of-smart{display:flex; gap:8px; padding:12px 14px; border-bottom:1px solid var(--line); flex-wrap:wrap;}
.smart{display:flex; flex-direction:column; align-items:flex-start; gap:1px; min-width:104px; padding:9px 13px;
  border:1px solid var(--line2); border-radius:var(--r-sm); background:var(--surface2); transition:.16s;}
.smart:hover{border-color:var(--blue); background:var(--surface); transform:translateY(-1px);}
.sm-v{font-family:var(--f-mono); font-size:15px; font-weight:800;}
.sm-l{font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--ink3); font-weight:700;}
.of-sheet{padding:22px 26px 26px; max-width:1000px;}
.of-title{margin-bottom:20px;}
.of-kind{font-size:11px; text-transform:uppercase; letter-spacing:.09em; color:var(--ink3); font-weight:700;}
.of-title h2{font-size:30px; letter-spacing:-.02em; margin-top:3px;}
.of-trail{display:flex; align-items:center; gap:6px; margin-top:9px; flex-wrap:wrap;}
.of-trail .chip.on{background:var(--blue-soft); color:var(--blue-d); border-color:transparent; font-weight:700;}
.of-groups{display:grid; grid-template-columns:1fr 1fr; gap:0 34px; margin-bottom:22px;}
.of-g{display:flex; flex-direction:column;}
.of-f{display:flex; gap:14px; padding:7px 0; border-bottom:1px solid var(--line); font-size:13px;}
.of-f span{min-width:120px; color:var(--ink3); flex-shrink:0;}
.of-f b{font-weight:650; min-width:0; word-break:break-word;}
.of-tabs{display:flex; gap:0; border-bottom:1px solid var(--line2); margin-bottom:14px;}
.of-tabs button{font-size:12.5px; font-weight:650; padding:9px 15px; color:var(--ink3); border-bottom:2px solid transparent; transition:.15s;}
.of-tabs button:hover{color:var(--ink);}
.of-tabs button.on{color:var(--blue-d); border-bottom-color:var(--blue);}
.otable.inner{border:1px solid var(--line); border-radius:var(--r-sm); overflow:hidden;}
.of-tot{display:flex; flex-direction:column; align-items:flex-end; gap:6px; margin-top:16px; padding-top:14px; border-top:1px solid var(--line);}
.of-tot > div{display:flex; gap:26px; font-size:13px; color:var(--ink2); min-width:270px; justify-content:space-between;}
.of-tot .grand{font-family:var(--f-display); font-size:19px; font-weight:800; color:var(--ink); border-top:2px solid var(--ink); padding-top:9px; margin-top:3px;}
@media (max-width:820px){ .of-groups{grid-template-columns:1fr;} .of-sheet{padding:18px;} .of-stages{margin-left:0; width:100%;} }

/* ══ EDITABLE FORM ══ fields read as fields, not as a wall of boxes ══ */
.oform.editing{border-color:var(--blue-soft2); box-shadow:0 0 0 3px var(--blue-tint), var(--sh-1);}
.of-dirty{display:inline-flex; align-items:center; font-size:10.5px; text-transform:uppercase; letter-spacing:.07em;
  font-weight:800; color:var(--warn); background:var(--warn-soft); border-radius:999px; padding:5px 11px; align-self:center;}
.oform.editing .ostage{opacity:.55;}
.oform.editing .ostage.now{opacity:1;}
.ofe-title{font-family:var(--f-display); font-size:29px; font-weight:800; letter-spacing:-.02em; color:var(--ink);
  border:none; border-bottom:2px dashed var(--line2); background:none; outline:none; padding:2px 0 6px;
  width:100%; max-width:520px; margin-top:4px; transition:border-color .18s;}
.ofe-title:focus{border-bottom-color:var(--blue); border-bottom-style:solid;}
.ofe-title::placeholder{color:var(--ink4); font-weight:600;}
select.ofe-title{cursor:pointer;}
.ofe-sub{font-size:12.5px; color:var(--ink3); margin-top:10px; max-width:62ch; line-height:1.55;}
.ofe-f{display:flex; align-items:baseline; gap:14px; padding:7px 0; border-bottom:1px solid var(--line);}
.ofe-f > label{min-width:120px; flex-shrink:0; font-size:12.5px; color:var(--ink3); font-weight:600;}
.ofe-c{flex:1; min-width:0; display:flex; align-items:baseline; gap:8px;}
.ofe-h{font-size:11px; color:var(--ink4); flex-shrink:0;}
.ofe-i{flex:1; min-width:0; border:none; border-bottom:1px solid transparent; background:none; outline:none;
  font-size:13px; font-weight:600; color:var(--ink); font-family:var(--f-body); padding:2px 0; transition:border-color .16s, background .16s;}
.ofe-i:hover{border-bottom-color:var(--line2);}
.ofe-i:focus{border-bottom-color:var(--blue);}
.ofe-i::placeholder{color:var(--ink4); font-weight:400;}
.ofe-i.num{font-family:var(--f-mono); max-width:110px; flex:none;}
.otable.editable td{padding:7px 12px; vertical-align:top;}
.otable.editable .tiny{width:34px; padding-left:0;}
.ofe-cell{border:1px solid transparent; border-radius:var(--r-xs); background:none; outline:none; font-size:13px;
  color:var(--ink); font-family:var(--f-body); padding:5px 7px; width:100%; transition:.15s;}
.ofe-cell:hover{background:var(--surface2); border-color:var(--line);}
.ofe-cell:focus{background:var(--surface); border-color:var(--blue); box-shadow:0 0 0 2px var(--blue-tint);}
.ofe-cell.wide{min-width:220px; font-weight:600;}
.ofe-cell.num{text-align:right; font-family:var(--f-mono); max-width:104px; margin-left:auto;}
.ofe-note{display:block; font-size:11px; color:var(--ink3); padding:1px 8px 0;}
.ofe-note.bad{color:var(--bad); font-weight:600;}
.otable.editable .addrow td{padding:0; border:none;}
.addline{display:inline-flex; align-items:center; gap:7px; font-size:12.5px; font-weight:650; color:var(--blue-d);
  padding:11px 12px; width:100%; justify-content:flex-start; transition:background .15s;}
.addline:hover{background:var(--blue-soft);}
.rowx{width:26px; height:26px; border-radius:7px; color:var(--ink4); display:grid; place-items:center; transition:.15s;}
.rowx:hover:not(:disabled){background:var(--bad-soft); color:var(--bad);}
.rowx:disabled{opacity:.3;}
.of-tot b.pos{color:var(--ok);} .of-tot b.neg{color:var(--bad);}
@media (max-width:820px){ .ofe-f{flex-direction:column; align-items:stretch; gap:3px;} .ofe-f > label{min-width:0;} .ofe-i.num{max-width:none;} }
`;

const THEME_SHAPES = `
/* ── Atelier · editorial fashion. Rules instead of cards, image does the work ── */
.th-atelier .card{border:none; background:none; box-shadow:none; border-radius:0;}
.th-atelier .card:hover{transform:none; box-shadow:none;}
.th-atelier .card-media{border-radius:0; background:var(--surface2); aspect-ratio:3/4; border:none;}
.th-atelier .card-media .glow,.th-atelier .card-media .pad{display:none;}
.th-atelier .card-body{padding:14px 2px 0;}
.th-atelier .card-body h3{font-size:13.5px; font-weight:500; letter-spacing:.01em;}
.th-atelier .card-foot{border-top:none; padding-top:8px;}
.th-atelier .btn,.th-atelier .btn-pri,.th-atelier .add-btn{border-radius:0; text-transform:uppercase; letter-spacing:.13em; font-size:11px; font-weight:700;}
.th-atelier .nav{border-radius:0; border-left:none; border-right:none; box-shadow:none; border-bottom:1px solid var(--line2); background:var(--surface);}
.th-atelier .nav-links{gap:26px;}
.th-atelier .chip,.th-atelier .pill,.th-atelier .badge{border-radius:0; text-transform:uppercase; letter-spacing:.09em; font-size:10px;}
.th-atelier .sec-title h2{font-weight:400; letter-spacing:-.01em;}
.th-atelier .catcard{border-radius:0; border:none; border-bottom:1px solid var(--line2);}
.th-atelier .hero{border-radius:0;}
.th-atelier .meter span{border-radius:0;}

/* ── Forge · industrial. Dense, boxy, everything labelled and scannable ── */
.th-forge .card{border-radius:var(--r-xs); border-width:1px;}
.th-forge .card-media{border-radius:0; border-bottom:1px solid var(--line2);}
.th-forge .card-body{padding:11px 12px;}
.th-forge .card-body h3{font-size:13px; font-weight:700;}
.th-forge .card-sub{font-family:var(--f-mono); font-size:10.5px; text-transform:uppercase; letter-spacing:.05em;}
.th-forge .price{font-family:var(--f-mono);}
.th-forge .btn,.th-forge .add-btn{border-radius:var(--r-xs); text-transform:uppercase; letter-spacing:.08em; font-size:11.5px; font-weight:700;}
.th-forge .chip,.th-forge .pill,.th-forge .badge{border-radius:var(--r-xs); font-family:var(--f-mono); text-transform:uppercase; font-size:10px;}
.th-forge .nav{border-radius:var(--r-xs);}
.th-forge .dtable th{font-family:var(--f-mono); text-transform:uppercase; letter-spacing:.06em;}
.th-forge .cover{border-radius:var(--r-xs);}
.th-forge .sec-title h2{text-transform:uppercase; letter-spacing:.02em;}

/* ── Orchard · grocery. Soft, round, generous, nothing sharp ── */
.th-orchard .card{border-radius:var(--r-lg);}
.th-orchard .card-media{border-radius:var(--r) var(--r) 0 0; aspect-ratio:1/1;}
.th-orchard .btn,.th-orchard .add-btn,.th-orchard .chip,.th-orchard .pill{border-radius:999px;}
.th-orchard .nav{border-radius:999px;}
.th-orchard .catcard{border-radius:var(--r-lg);}
.th-orchard .sec-title h2{letter-spacing:-.015em;}
.th-orchard .hero{border-radius:var(--r-xl);}

/* ── Bloom · beauty. Elegant, airier, serif headings carry more size ── */
.th-bloom .card-media{aspect-ratio:1/1; border-radius:var(--r) var(--r) 0 0;}
.th-bloom .btn,.th-bloom .add-btn,.th-bloom .chip,.th-bloom .pill{border-radius:999px;}
.th-bloom .nav{border-radius:999px;}
.th-bloom .sec-title h2{font-size:clamp(24px,3vw,34px); font-weight:600; letter-spacing:-.02em;}
.th-bloom .card-body h3{font-family:var(--f-display); font-weight:600; font-size:15px;}
.th-bloom .hero{border-radius:var(--r-xl);}

/* ── Apothecary · clinical. Bigger type, more air, calmer contrast ── */
.th-apothecary{font-size:15.5px;}
.th-apothecary .card-body{padding:15px 15px 13px;}
.th-apothecary .card-body h3{font-size:14.5px; line-height:1.45;}
.th-apothecary .sec-title h2{font-weight:600;}
.th-apothecary .btn,.th-apothecary .add-btn{border-radius:var(--r-sm); font-weight:600;}
.th-apothecary .section{padding-top:44px; padding-bottom:44px;}
.th-apothecary .card{border-radius:var(--r);}

/* ── Souk · handmade. Warm frames, softer edges, tactile ── */
.th-souk .card-media{aspect-ratio:4/5; border-radius:var(--r) var(--r) 0 0;}
.th-souk .card{border-radius:var(--r-lg); border-color:var(--line2);}
.th-souk .btn,.th-souk .add-btn{border-radius:999px;}
.th-souk .chip,.th-souk .pill{border-radius:999px;}
.th-souk .sec-title h2{letter-spacing:-.015em;}

/* ── Midnight · dark. Glow instead of shadow, hairline borders that catch light ── */
.th-midnight .card{background:var(--surface); border-color:var(--line);}
.th-midnight .card:hover{border-color:var(--blue); box-shadow:0 0 0 1px var(--blue), 0 12px 34px rgba(124,92,255,.28);}
.th-midnight .card-media{background:linear-gradient(160deg,#1A2338,#12182A);}
.th-midnight .nav{background:rgba(21,28,46,.86); border-color:var(--line);}
.th-midnight .btn-pri,.th-midnight .add-btn{box-shadow:0 0 18px rgba(124,92,255,.34);}
.th-midnight .invoice-sheet{color:#101828;}
.th-midnight .podium{filter:brightness(.86) saturate(1.15);}
.th-midnight .inv-wrap{background:rgba(0,0,0,.72);}
`;

