/* ══════════════════════════ PROMOTIONS ENGINE ══════════════════════════ */
const SEED_PROMOS = [
  { id: "pm1", name: "Student Discount", kind: "percent", value: 15, scope: "all", target: "", code: "STUDENT15", active: true, showBanner: true, bannerText: "15% off with a student ID", minSpend: 0 },
  { id: "pm2", name: "Charger Blowout", kind: "percent", value: 20, scope: "category", target: "Chargers & Adapters", code: "", active: true, showBanner: true, bannerText: "20% off every charger", minSpend: 0 },
  { id: "pm3", name: "Sony Audio Deal", kind: "fixed", value: 5000, scope: "brand", target: "Sony", code: "", active: true, showBanner: false, bannerText: "", minSpend: 0 },
  { id: "pm4", name: "Bundle & Save", kind: "percent", value: 25, scope: "all", target: "", code: "BUNDLE25", active: false, showBanner: true, bannerText: "Save up to 25% on bundles", minSpend: 15000 },
];
const SEED_AUTO = SEED_PROMOS.filter((p) => !p.code && p.active);
const applyPromo = (price, promo) => {
  if (!promo) return price;
  if (promo.kind === "percent") return price * (1 - promo.value / 100);
  return Math.max(0, price - promo.value);
};
const promoMatches = (p, promo) => {
  if (!p || !promo || !promo.active) return false;
  if (promo.scope === "all") return true;
  if (promo.scope === "category") return p.category === promo.target;
  if (promo.scope === "brand") return p.brand === promo.target;
  if (promo.scope === "product") return p.id === promo.target;
  return false;
};
const bestPromo = (p, promos) => {
  let best = null, bestPrice = p.price;
  (promos || []).forEach((pr) => {
    if (!pr.code && promoMatches(p, pr)) {
      const np = applyPromo(p.price, pr);
      if (np < bestPrice) { bestPrice = np; best = pr; }
    }
  });
  return best;
};
const priceInfo = (p, autoPromos) => {
  const promo = bestPromo(p, autoPromos);
  const final = promo ? applyPromo(p.price, promo) : p.price;
  const was = promo ? p.price : (p.compareAt || null);
  const offPct = was && was > final ? Math.round((1 - final / was) * 100) : 0;
  return { final, was, offPct, promo };
};
const isSoldOut = (p) => !p || p.soldOut || p.stock <= 0;

