const SEED_DOCS = (function () {
  const rows = [];
  const line = (i, qty, disc) => {
    const p = PRODUCTS_INIT[i];
    return p ? { id: p.id, name: p.name, sku: p.sku, kind: p.kind || "product",
      qty, unitPrice: Math.round(p.price * (1 - disc)), cost: p.cost, retail: p.price } : null;
  };
  const SALES = [
    ["QT", "quotation", "Meridian Corporate Services", "Faraz Siddiqui", "0321 4455661", "Karachi", [0, 2], 40, 0.22, 3, false, 0],
    ["QT", "quotation", "Bluewave Hospitality", "Nadia Rehman", "0300 8877223", "Lahore", [9, 10], 25, 0.18, 6, false, 0],
    ["SO", "order", "Zenith IT Solutions", "Kamran Butt", "0333 1122447", "Islamabad", [4, 5, 6], 60, 0.25, 11, false, 0],
    ["INV", "invoice", "Northline Logistics", "Adeel Farooq", "0312 9988776", "Rawalpindi", [14, 15], 30, 0.2, 19, true, 0.5],
    ["INV", "invoice", "Crescent Trading Co", "Hira Aslam", "0345 6677889", "Faisalabad", [1, 3], 80, 0.24, 27, true, 1],
  ];
  SALES.forEach(([prefix, stage, party, contact, phone, city, idx, qty, disc, daysAgo, confirmed, paidFrac], i) => {
    const lines = idx.map((x) => line(x, qty, disc)).filter(Boolean);
    const total = lines.reduce((a, l) => a + l.qty * l.unitPrice, 0);
    const at = Date.now() - daysAgo * 86400000;
    rows.push({
      id: "D" + (3000 + i), side: "sale", stage, no: prefix + "-" + (3000 + i), at,
      party, contact, phone, email: "", city, ntn: "", supplierId: "",
      date: new Date(at).toISOString().slice(0, 10), validDays: 14, terms: 30, termId: ["PT-04", "PT-02", "PT-08", "PT-05", "PT-06"][i % 5], note: "", reference: "",
      lines, payments: paidFrac > 0 ? [{ id: "R-s" + i, at: at + 86400000, amount: Math.round(total * paidFrac), paidFrom: i % 2 ? "cash" : "bank", note: "Advance" }] : [],
      confirmed, stockMoved: confirmed, history: [{ at, what: "Raised" }], trail: [],
    });
  });
  const BUYS = [
    ["RFQ", "rfq", "SUP-02", [9, 10, 11], 50, 4, false, 0],
    ["PO", "porder", "SUP-01", [0, 1, 2], 70, 9, false, 0],
    ["BILL", "bill", "SUP-03", [20, 21], 45, 16, true, 0.4],
  ];
  BUYS.forEach(([prefix, stage, supplierId, idx, qty, daysAgo, confirmed, paidFrac], i) => {
    const lines = idx.map((x) => {
      const p = PRODUCTS_INIT[x];
      return p ? { id: p.id, name: p.name, sku: p.sku, kind: p.kind || "product", qty, unitPrice: p.cost, cost: p.cost, retail: p.price } : null;
    }).filter(Boolean);
    const total = lines.reduce((a, l) => a + l.qty * l.unitPrice, 0);
    const at = Date.now() - daysAgo * 86400000;
    const names = { "SUP-01": "Anker Pakistan Distribution", "SUP-02": "Shenzhen Tech Imports", "SUP-03": "Karachi Accessory House" };
    rows.push({
      id: "D" + (3050 + i), side: "buy", stage, no: prefix + "-" + (3050 + i), at,
      party: names[supplierId] || supplierId, contact: "", phone: "", email: "", city: "", ntn: "", supplierId,
      date: new Date(at).toISOString().slice(0, 10), validDays: 15, terms: 30, termId: ["PT-04", "PT-03", "PT-08"][i % 3], note: "", reference: "",
      lines, payments: paidFrac > 0 ? [{ id: "R-b" + i, at: at + 86400000, amount: Math.round(total * paidFrac), paidFrom: "bank", note: "Part payment" }] : [],
      confirmed, stockMoved: confirmed, history: [{ at, what: "Raised" }], trail: [],
    });
  });
  return rows.sort((a, b) => b.at - a.at);
})();

