/* ══════════════════════════ HELPERS ══════════════════════════ */
/* a Pakistani number gets typed a dozen different ways, so compare on digits only */
/* main photo first, then extra angles, de-duplicated and blanks dropped */
const galleryFrames = (p) => {
  const out = [];
  [p.image, ...(p.images || [])].forEach((u) => {
    const v = String(u || "").trim();
    if (v && out.indexOf(v) === -1) out.push(v);
  });
  return out;
};
/* turn a watch page URL into something an iframe will actually play */
const embedUrl = (url) => {
  const u = String(url || "").trim();
  if (!u) return null;
  const yt = u.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([\w-]{6,})/);
  if (yt) return "https://www.youtube.com/embed/" + yt[1];
  const vm = u.match(/vimeo\.com\/(?:video\/)?(\d+)/);
  if (vm) return "https://player.vimeo.com/video/" + vm[1];
  return null; /* treat anything else as a direct file */
};
const normalisePhone = (v) => String(v || "").replace(/\D/g, "").replace(/^0+/, "").replace(/^92/, "");
const money = (n) => "Rs " + Math.round(n || 0).toLocaleString("en-US");
const compact = (n) => n >= 1000000 ? (n / 1000000).toFixed(1) + "M" : n >= 1000 ? (n / 1000).toFixed(n >= 100000 ? 0 : 1) + "k" : String(Math.round(n));
const avatarColor = (s) => { let h = 0; for (let i = 0; i < s.length; i++) h = s.charCodeAt(i) + ((h << 5) - h); const hue = 68 + (Math.abs(h) % 110); return `hsl(${hue} 58% 78%)`; };
const slugify = (s) => s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const relTime = (ts) => {
  const d = Math.floor((Date.now() - ts) / 1000);
  if (d < 60) return "just now";
  if (d < 3600) return Math.floor(d / 60) + "m ago";
  if (d < 86400) return Math.floor(d / 3600) + "h ago";
  return Math.floor(d / 86400) + "d ago";
};

function computeTotals(lines, zoneId, methodId, config, byId, autoPromos, weightBy) {
  const src = byId || MODULE_BY_ID;
  const promos = autoPromos || [];
  const wmap = weightBy || SEED_WEIGHTS;
  const items = lines.map((l) => { const p = src[l.id]; return p ? { ...p, qty: l.qty, effPrice: priceInfo(p, promos).final } : null; }).filter(Boolean);
  const subtotal = items.reduce((s, it) => s + it.effPrice * it.qty, 0);
  const weight = items.reduce((s, it) => s + (it.weightKg != null ? it.weightKg : (wmap[it.category] != null ? wmap[it.category] : 0.3)) * it.qty, 0);
  const zone = config.zones.find((z) => z.id === zoneId) || config.zones[0];
  const method = config.methods.find((m) => m.id === methodId) || config.methods[0];
  const base = zone.base + zone.perKg * weight;
  /* with deliveries switched off there is no carriage to charge and nothing to
     recover: the customer collects, so the quote is the goods and the tax. */
  const ships = config.deliveries !== false;
  let shipping = ships ? base * method.mult : 0;
  const free = ships && method.id === "standard" && subtotal >= config.freeShipThreshold && subtotal > 0;
  if (!ships) shipping = 0;
  else if (free) shipping = 0;
  else if (subtotal > 0) shipping += config.handlingFee;
  const tax = subtotal * config.taxRate;
  const total = subtotal + shipping + tax;
  const etaMin = Math.max(1, zone.etaMin + (method.addDays || 0));
  const etaMax = Math.max(etaMin, zone.etaMax + (method.addDays || 0));
  /* what the courier bills us. Independent of what the customer paid, so a free
     shipping promo shows up as a real cost rather than quietly disappearing. */
  /* the partner's own rate card for this zone wins. Fall back to the zone default
     so a method with no partner assigned still quotes something sane. */
  const partner = (config.partners || []).find((x) => x.id === method.partnerId);
  const pz = partner && partner.zones ? partner.zones[zone.id] : null;
  const vBase = pz && pz.base != null ? pz.base : (zone.vendorBase != null ? zone.vendorBase : Math.round(zone.base * 0.72));
  const vPerKg = pz && pz.perKg != null ? pz.perKg : (zone.vendorPerKg != null ? zone.vendorPerKg : Math.round(zone.perKg * 0.72));
  const vMult = method.vendorMult != null ? method.vendorMult : method.mult;
  const shipCost = ships && subtotal > 0 ? Math.round((vBase + vPerKg * weight) * vMult) : 0;
  const shipMargin = shipping - shipCost;
  return { items, subtotal, weight, shipping, shipCost, shipMargin, tax, total, free, etaMin, etaMax, zone, method };
}

function generateSeed() {
  const pick = (a) => a[Math.floor(Math.random() * a.length)];
  const names = [
    ["Ahmed Raza","ahmed.raza@mail.com"],["Fatima Khan","fatima.k@mail.com"],["Bilal Hussain","bilal.h@mail.com"],
    ["Ayesha Siddiqui","ayesha.s@mail.com"],["Usman Ali","usman.ali@mail.com"],["Zainab Malik","zainab.m@mail.com"],
    ["Hassan Sheikh","hassan.s@mail.com"],["Maryam Butt","maryam.b@mail.com"],["Imran Farooq","imran.f@mail.com"],
    ["Sana Tariq","sana.t@mail.com"],["Kamran Javed","kamran.j@mail.com"],["Hira Baloch","hira.b@mail.com"],
    ["Faisal Mehmood","faisal.m@mail.com"],["Nida Yousaf","nida.y@mail.com"],["Omar Chaudhry","omar.c@mail.com"],
    ["Rabia Nawaz","rabia.n@mail.com"],["Ali Zafar","ali.z@mail.com"],["Sadia Iqbal","sadia.i@mail.com"],
  ];
  const cities = PK_CITIES.filter((c) => c.name !== "Other city / town");
  const ids = PRODUCTS_INIT.map((p) => p.id);
  const out = [];
  const N = 168;
  for (let i = 0; i < N; i++) {
    const daysAgo = Math.floor((i / N) * 118) + Math.floor(Math.random() * 3);
    const n = 1 + Math.floor(Math.random() * 2.6);
    const chosen = [];
    for (let j = 0; j < n; j++) { const pid = pick(ids); if (!chosen.find((c) => c.id === pid)) chosen.push({ id: pid, qty: 1 + Math.floor(Math.random() * 2) }); }
    const city = pick(cities), zoneId = city.zoneId;
    const methodId = zoneId === "z1" ? pick(["standard", "express", "sameday"]) : pick(["standard", "express"]);
    let status;
    if (daysAgo > 11) status = Math.random() < 0.19 ? "Cancelled" : "Delivered";
    else if (daysAgo > 5) status = pick(["Delivered", "Delivered", "Out for delivery", "Shipped"]);
    else if (daysAgo > 1) status = pick(["Shipped", "Out for delivery", "Packed"]);
    else status = pick(["Processing", "Packed", "Processing"]);
    const paymentMethod = Math.random() < 0.68 ? "cod" : "card";
    const t = computeTotals(chosen, zoneId, methodId, INITIAL_CONFIG, MODULE_BY_ID, SEED_AUTO, SEED_WEIGHTS);
    const lines = chosen.map((l) => ({ id: l.id, qty: l.qty, price: priceInfo(MODULE_BY_ID[l.id], SEED_AUTO).final, cost: MODULE_BY_ID[l.id].cost }));
    const [nm, em] = names[i % names.length];
    out.push({
      id: "TX-" + (10066 + i), createdAt: Date.now() - daysAgo * 86400000, customer: { name: nm, email: em, city: city.name, address: "House " + (10 + i) + ", Block " + String.fromCharCode(65 + (i % 6)) },
      zoneId, methodId, paymentMethod, lines, subtotal: t.subtotal, weight: t.weight, shipping: t.shipping, shipCost: t.shipCost, tax: t.tax, total: t.total,
      etaMin: t.etaMin, etaMax: t.etaMax, status, paid: paymentMethod === "card" ? true : status === "Delivered", discount: 0, promoCode: null, note: "",
      /* older business is already reconciled so the ledger opens with a realistic balance */
      /* how much of this order has actually been settled, not a yes/no flag.
         Couriers remit in lumps that rarely line up with order boundaries. */
      codPaid: paymentMethod === "cod" && daysAgo > 9 && status === "Delivered" ? t.total : 0,
      freightPaid: daysAgo > 9 && status !== "Cancelled" ? (t.shipCost || 0) : 0,
      /* a cancelled COD order that already shipped is a return to origin: freight burned both ways, no revenue */
      rto: status === "Cancelled" && paymentMethod === "cod",
    });
  }
  return out.sort((a, b) => b.createdAt - a.createdAt);
}
const SEED_ORDERS = generateSeed();
/* the customer portal keys on phone number, so every repeat buyer needs the same
   one across their orders. Derived from the name so it stays stable. */
const phoneFor = (name) => {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  const nets = ["300", "301", "321", "333", "345", "312"];
  return "0" + nets[h % nets.length] + " " + String(1000000 + (h % 9000000)).slice(0, 7);
};
SEED_ORDERS.forEach((o) => { o.customer.phone = phoneFor(o.customer.name); });

function generateReturns() {
  const REASONS = ["Damaged in transit", "Wrong item sent", "Not as described", "Faulty on arrival", "Changed mind", "Found it cheaper", "Arrived too late", "Missing parts"];
  const STAGES = [
    { status: "Requested", restocked: 0, writtenOff: 0, refunded: 0 },
    { status: "Approved", restocked: 0, writtenOff: 0, refunded: 0 },
    { status: "In transit", restocked: 0, writtenOff: 0, refunded: 0 },
    { status: "Received", restocked: 0, writtenOff: 0, refunded: 0 },
    { status: "Closed", restocked: 1, writtenOff: 0, refunded: -1 },
    { status: "Closed", restocked: 0, writtenOff: 1, refunded: -1 },
  ];
  const delivered = SEED_ORDERS.filter((o) => o.status === "Delivered");
  const out = [];
  for (let i = 0; i < Math.min(14, delivered.length); i++) {
    const o = delivered[Math.floor((i / 14) * delivered.length)];
    if (!o || out.find((r) => r.orderId === o.id)) continue;
    const line = o.lines[0];
    const stage = STAGES[i % STAGES.length];
    const qty = 1;
    const gross = qty * line.price;
    const at = o.createdAt + (2 + (i % 4)) * 86400000;
    if (at > Date.now()) continue;
    out.push({
      id: "RMA-" + (4100 + i), orderId: o.id, customer: o.customer,
      lines: [{ id: line.id, name: (MODULE_BY_ID[line.id] || {}).name || line.id, qty, price: line.price, cost: line.cost }],
      reason: REASONS[i % REASONS.length],
      resolution: i % 5 === 0 ? "exchange" : i % 7 === 0 ? "credit" : "refund",
      note: "", status: stage.status, createdAt: at,
      restocked: stage.restocked, writtenOff: stage.writtenOff,
      refunded: stage.refunded === -1 ? gross : 0,
      freightCost: INITIAL_CONFIG.storePaysReturnFreight ? INITIAL_CONFIG.returnPickupCost : 0,
      timeline: [{ at, what: "Return requested by customer" }],
    });
  }
  return out.sort((a, b) => b.createdAt - a.createdAt);
}
const SEED_RETURNS = generateReturns();

const ONES = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
  "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
const TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
function underThousand(n) {
  if (n === 0) return "";
  if (n < 20) return ONES[n];
  if (n < 100) return TENS[Math.floor(n / 10)] + (n % 10 ? " " + ONES[n % 10] : "");
  return ONES[Math.floor(n / 100)] + " Hundred" + (n % 100 ? " " + underThousand(n % 100) : "");
}
/* crore / lakh / thousand, which is how an invoice reads in Pakistan */
function amountInWords(value) {
  /* must round the same way money() does, or the words and the figure disagree */
  const n = Math.round(Math.abs(Number(value) || 0));
  if (n === 0) return "Zero Only";
  const parts = [];
  const crore = Math.floor(n / 10000000);
  const lakh = Math.floor((n % 10000000) / 100000);
  const thousand = Math.floor((n % 100000) / 1000);
  const rest = n % 1000;
  if (crore) parts.push(underThousand(crore) + " Crore");
  if (lakh) parts.push(underThousand(lakh) + " Lakh");
  if (thousand) parts.push(underThousand(thousand) + " Thousand");
  if (rest) parts.push(underThousand(rest));
  return parts.join(" ") + " Only";
}
const hexA = (hex, a) => {
  const h = String(hex || "").replace("#", "");
  if (h.length !== 6) return "rgba(29,78,216," + a + ")";
  return "rgba(" + parseInt(h.slice(0, 2), 16) + "," + parseInt(h.slice(2, 4), 16) + "," + parseInt(h.slice(4, 6), 16) + "," + a + ")";
};


/* ══════════════════════════════════════════════════════════════════════════
   PRODUCT ARTWORK
   Vector illustrations rendered as real <img> data URIs, one silhouette per
   category with three angles each. They exist so the catalog ships looking
   like a shop rather than a wall of icons, and so the image paths get
   exercised end to end. Swap any of them for a photo URL or an upload and
   nothing else changes.
   ══════════════════════════════════════════════════════════════════════════ */
/* ── lifestyle scenes ──
   Animated vector scenes of someone actually using the gear. Deliberately
   stylised rather than photographic: flat shapes, no facial detail, editorial
   rather than a bad attempt at a photo. They play until real footage is added
   to the showreel in Settings, at which point these step aside. */
const FIG = {
  skin: "#F0C6A0", skin2: "#DBA97F", hair: "#171320", hair2: "#241C33",
  desk: "#0A0F22", panel: "#E7ECF7", panel2: "#B9C4D8",
};

/* one figure, reused across every scene, seated three quarters facing right */
const figureBase = (accent, lean) => (
  '<g transform="translate(0 ' + (lean || 0) + ')">' +
  /* seat shadow */
  '<ellipse cx="300" cy="536" rx="150" ry="18" fill="#000" opacity=".28"/>' +
  /* torso */
  '<path d="M214 540 C214 430 246 372 300 372 C354 372 386 430 386 540 Z" fill="' + accent + '"/>' +
  /* shoulder highlight, gives the flat shape some form */
  '<path d="M300 372 C346 372 378 418 384 470 L336 470 C332 424 318 396 300 388 Z" fill="#fff" opacity=".14"/>' +
  /* neck */
  '<path d="M282 340 h36 v40 c0 12 -36 12 -36 0 Z" fill="' + FIG.skin2 + '"/>' +
  /* head */
  '<ellipse cx="304" cy="292" rx="52" ry="58" fill="' + FIG.skin + '"/>' +
  /* jaw shade */
  '<path d="M256 300 C262 340 288 352 304 352 C288 348 272 330 266 300 Z" fill="' + FIG.skin2 + '" opacity=".55"/>' +
  /* hair, long, falling behind the shoulder */
  '<path d="M252 288 C246 226 282 202 316 204 C352 206 368 236 362 274 C356 248 340 234 316 232 C292 230 272 246 268 288 Z" fill="' + FIG.hair + '"/>' +
  '<path d="M256 276 C240 320 236 392 250 452 C222 442 214 372 226 316 C230 296 242 282 256 276 Z" fill="' + FIG.hair2 + '"/>' +
  '</g>'
);

