/* the ED monogram: a slanted E in signal blue interlocking with a solid D.
   Used as the default mark, replaced the moment a logo file is uploaded. */

/* shared scene furniture: soft ground, contact shadow, faint grid */
const ART_SCENE = (w, h, a, b) =>
  '<defs>' +
  '<linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' + a + '"/><stop offset="1" stop-color="' + b + '"/></linearGradient>' +
  '<linearGradient id="mtl" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FDFDFF"/><stop offset="0.45" stop-color="#DFE6F2"/><stop offset="1" stop-color="#AEBACD"/></linearGradient>' +
  '<linearGradient id="drk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#48536B"/><stop offset="0.5" stop-color="#232C3E"/><stop offset="1" stop-color="#141A26"/></linearGradient>' +
  '<radialGradient id="sh"><stop offset="0" stop-color="#0B1220" stop-opacity="0.30"/><stop offset="1" stop-color="#0B1220" stop-opacity="0"/></radialGradient>' +
  '</defs>' +
  '<rect width="' + w + '" height="' + h + '" fill="url(#bg)"/>' +
  '<ellipse cx="' + w / 2 + '" cy="' + (h * 0.845) + '" rx="' + (w * 0.34) + '" ry="' + (h * 0.055) + '" fill="url(#sh)"/>';

/* one body per category. c = accent, f = body fill id */
