const ART_KIND = {
  cat_lap_every: "laptop", cat_lap_biz: "laptop", cat_lap_game: "laptop", cat_lap_apple: "laptop",
  "Chargers & Adapters": "charger", "Cables & Hubs": "cable", "Keyboards": "keyboard",
  "Mice": "mouse", "Stands & Holders": "stand", "Headphones": "headphones",
  "Phone Cases": "phone", "Laptop Bags": "bag",
};
/* three angles: straight on in dark, tilted in metal, and a close crop */
const ART_ANGLES = [
  { fill: "drk", rot: 0, scale: 1, bg: ["#F4F7FE", "#E3EBFA"] },
  { fill: "mtl", rot: -14, scale: 0.94, bg: ["#FFFFFF", "#EDF2FB"] },
  { fill: "drk", rot: 9, scale: 1.14, bg: ["#EEF3FC", "#DCE7F8"] },
];

const productShot = (categoryId, accent, angle) => {
  const kind = ART_KIND[categoryId] || "charger";
  const a = ART_ANGLES[angle % ART_ANGLES.length];
  const body = (ART_BODY[kind] || ART_BODY.charger)(accent, a.fill);
  return svgURI(512, 512,
    ART_SCENE(512, 512, a.bg[0], a.bg[1]) +
    '<g transform="translate(256 244) rotate(' + a.rot + ') scale(' + a.scale + ') translate(-256 -244)">' + body + '</g>');
};

const categoryBanner = (categoryId, accent) => {
  const kind = ART_KIND[categoryId] || "charger";
  const body = (ART_BODY[kind] || ART_BODY.charger)(accent, "drk");
  return svgURI(800, 500,
    '<defs><linearGradient id="cbg" x1="0" y1="0" x2="1" y2="1">' +
    '<stop offset="0" stop-color="' + accent + '" stop-opacity="0.16"/><stop offset="1" stop-color="#EEF3FC"/></linearGradient></defs>' +
    '<rect width="800" height="500" fill="url(#cbg)"/>' +
    ART_SCENE(800, 500, "rgba(0,0,0,0)", "rgba(0,0,0,0)").replace(/<rect width="800"[^/]*\/>/, "") +
    '<circle cx="640" cy="120" r="150" fill="' + accent + '" opacity="0.10"/>' +
    '<circle cx="150" cy="430" r="120" fill="' + accent + '" opacity="0.08"/>' +
    '<g transform="translate(400 250) scale(0.88) translate(-256 -244)">' + body + '</g>');
};

/* accents rotate so a shelf of the same category is not eight identical pictures */
const ART_ACCENTS = ["#2563EB", "#22D3EE", "#7C3AED", "#0E9F6E", "#F0A83C", "#E0567A"];
/* groups borrow the artwork of their first child so nothing renders bare */
const GROUP_ART = { grp_laptops: "Laptops", grp_power: "Chargers & Adapters", grp_desk: "Keyboards", grp_audio: "Headphones", grp_carry: "Laptop Bags" };
CHILDREN_SEED.forEach((c, i) => { c.image = categoryBanner(c.id, ART_ACCENTS[i % ART_ACCENTS.length]); });
PARENTS_SEED.forEach((g, i) => { let c_ = GROUP_ART[g.id] || (CHILDREN_SEED.find((c) => c.parentId === g.id) || {}).id; if (c_) g.image = categoryBanner(c_, ART_ACCENTS[(i + 2) % ART_ACCENTS.length]); });
PRODUCTS_INIT.forEach((p, i) => {
  const accent = ART_ACCENTS[i % ART_ACCENTS.length];
  p.image = productShot(p.category, accent, 0);
  p.images = [productShot(p.category, accent, 1), productShot(p.category, accent, 2)];
});

