const SEED_PURCHASES = (function () {
  /* build from the real catalog rather than hardcoded ids, so a product rename
     or reshuffle can never leave a purchase pointing at nothing */
  const byCat = {};
  PRODUCTS_INIT.forEach((p) => { (byCat[p.category] = byCat[p.category] || []).push(p); });
  const SPEC = [
    ["SUP-01", "Chargers & Adapters", 3, 62, 2, "full"],
    ["SUP-02", "Keyboards", 3, 40, 11, "part"],
    ["SUP-03", "Phone Cases", 2, 55, 19, "full"],
    ["SUP-04", "Headphones", 2, 34, 27, "none"],
    ["SUP-01", "Cables & Hubs", 3, 48, 38, "full"],
    ["SUP-02", "Mice", 2, 36, 52, "full"],
  ];
  const rows = [];
  SPEC.forEach(([supplierId, cat, take, qty, daysAgo, pay], i) => {
    const pool = (byCat[cat] || []).slice(0, take);
    if (!pool.length) return;
    const at = Date.now() - daysAgo * 86400000;
    const d = new Date(at);
    const lines = pool.map((p) => ({ id: p.id, name: p.name, qty, unitCost: p.cost, total: qty * p.cost }));
    const total = lines.reduce((a, l) => a + l.total, 0);
    rows.push({
      id: "PO-" + (7100 + i), supplierId, kind: "purchase",
      date: d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"),
      at, lines, total,
      paid: pay === "full" ? total : pay === "part" ? Math.round(total * 0.4) : 0,
      status: "received", invoiceNo: "INV-" + (44120 + i), note: "",
    });
  });
  return rows.sort((a, b) => b.at - a.at);
})();

