/* a few faulty units already in quarantine so the register opens with something */
const SEED_FAULTS = (function () {
  const SPEC = [
    [0, 3, "Damaged in transit", "receiving", 9],
    [4, 2, "Dead on arrival", "receiving", 21],
    [9, 5, "Customer return, not resellable", "customer", 4],
    [14, 1, "Manufacturing defect", "warehouse", 33],
  ];
  const rows = [];
  SPEC.forEach(([pi, qty, reason, source, daysAgo], i) => {
    const p = PRODUCTS_INIT[pi];
    if (!p) return;
    const at = Date.now() - daysAgo * 86400000;
    const d = new Date(at);
    rows.push({
      id: "FLT-" + (600 + i), productId: p.id, name: p.name, sku: p.sku,
      qty, remaining: qty, unitCost: p.cost, reason, source, supplierId: "",
      date: d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"),
      at, note: "", status: "quarantine", history: [],
    });
    p.stock = Math.max(0, p.stock - qty);
  });
  return rows.sort((a, b) => b.at - a.at);
})();

/* lots and serials for the seeded purchases, so traceability opens with history */
const SEED_LOTS = [];
const SEED_SERIALS = [];
(function () {
  const supCode = { "SUP-01": "ANK", "SUP-02": "SZT", "SUP-03": "KAH", "SUP-04": "AUD" };
  SEED_PURCHASES.slice().sort((a, b) => a.at - b.at).forEach((po, li) => {
    const d = new Date(po.at);
    const seq = 400 + li;
    const code = (supCode[po.supplierId] || "GEN") + "-" +
      String(d.getFullYear()).slice(2) + String(d.getMonth() + 1).padStart(2, "0") + String(d.getDate()).padStart(2, "0") + "-" + seq;
    const lot = {
      id: "LOT-" + seq, code, purchaseId: po.id, supplierId: po.supplierId, at: po.at, date: po.date,
      invoiceNo: po.invoiceNo, lines: po.lines.map((l) => ({ id: l.id, name: l.name, qty: l.qty, unitCost: l.unitCost })),
      units: po.lines.reduce((a, l) => a + l.qty, 0), value: po.total, note: "",
    };
    SEED_LOTS.push(lot);
    let running = 0;
    po.lines.forEach((l) => {
      const p = MODULE_BY_ID[l.id];
      const stub = ((p && p.sku) || l.id).replace(/[^A-Za-z0-9]/g, "").slice(-6).toUpperCase();
      for (let i = 0; i < l.qty; i++) {
        /* most of a lot sells through, a little stays on the shelf, a little goes bad */
        const r = (i * 37 + li * 11) % 100;
        const status = r < 62 ? "sold" : r < 94 ? "stock" : r < 98 ? "faulty" : "writtenoff";
        SEED_SERIALS.push({
          serial: code + "-" + stub + "-" + String(running + i + 1).padStart(4, "0"),
          lotId: lot.id, purchaseId: po.id, productId: l.id, unitCost: l.unitCost,
          at: po.at, status, ref: "",
        });
      }
      running += l.qty;
    });
  });
  SEED_LOTS.reverse();
})();

/* a live wholesale pipeline so the B2B desk is not empty on first load */
const SEED_B2B = (function () {
  const pick = (i, n) => PRODUCTS_INIT.slice(i, i + n).map((p) => ({
    id: p.id, name: p.name, sku: p.sku, qty: [40, 60, 25, 100, 75][i % 5],
    unitPrice: Math.round(p.price * 0.72), cost: p.cost, retail: p.price,
  }));
  const SPEC = [
    ["Meridian Corporate Services", "Faraz Siddiqui", "0321 4455661", "faraz@meridiancorp.pk", "Karachi", "Confirmed", 0, 3, 18, 0.5],
    ["Bluewave Hospitality Group", "Nadia Rehman", "0300 8877223", "nadia@bluewavehg.com", "Lahore", "Quoted", 4, 2, 6, 0],
    ["Zenith IT Solutions", "Kamran Butt", "0333 1122447", "kamran@zenithit.pk", "Islamabad", "Delivered", 9, 3, 32, 1],
    ["Crescent Trading Co", "Hira Aslam", "0345 6677889", "hira@crescenttrading.pk", "Faisalabad", "Enquiry", 0, 0, 2, 0],
    ["Northline Logistics", "Adeel Farooq", "0312 9988776", "adeel@northline.com.pk", "Rawalpindi", "Closed", 14, 2, 54, 1],
  ];
  return SPEC.map(([company, contact, phone, email, city, stage, pi, n, daysAgo, paidFrac], i) => {
    const at = Date.now() - daysAgo * 86400000;
    const lines = n > 0 ? pick(pi, n) : [];
    const total = lines.reduce((a, l) => a + l.qty * l.unitPrice, 0);
    const payments = paidFrac > 0 ? [{
      id: "RCPT-" + (8800 + i), at: at + 86400000 * 2,
      amount: Math.round(total * paidFrac), paidFrom: i % 2 ? "cash" : "bank", note: "Advance against order",
    }] : [];
    return {
      id: "B2B-" + (9100 + i), stage, at, createdAt: at, company, contact, phone, email, city,
      ntn: "", interest: "", volume: "", message: "",
      lines, payments, terms: 30, note: "", invoiceNo: total > 0 ? "WS-" + (2200 + i) : "",
      timeline: [{ at, what: "Enquiry received" }],
    };
  }).sort((a, b) => b.at - a.at);
})();

